import type { EffectBuilderDraft, EffectBuilderKind } from "../../types/effect-builders";

export const EFFECT_BUILDERS: { kind: EffectBuilderKind; title: string; description: string }[] = [
  {
    kind: "wounds",
    title: "Wound Formula",
    description: "Calculate wounds from characteristics, skills, and a custom formula.",
  },
  { kind: "grant", title: "Item Grant", description: "Give a character a fixed set of Items." },
  {
    kind: "random",
    title: "Random Item",
    description: "Roll for Items, including results from nested RollTables.",
  },
  {
    kind: "choice",
    title: "Item Choice",
    description: "Let a player choose between Items or packages of Items.",
  },
];

export function createEffectBuilderDraft(kind: EffectBuilderKind): EffectBuilderDraft {
  return {
    kind,
    name: EFFECT_BUILDERS.find((entry) => entry.kind === kind)!.title,
    formula: "@sb + 2 * @tb + @wpb",
    items: [],
    table: null,
    count: 1,
    groups: [],
    recipe: { grantMode: "all", lifetime: "linked-to-effect", ownerAction: "keep" },
  };
}
