import {
  buildSpeciesEffectCarrier,
  SPECIES_EFFECT_CARRIER_FLAG,
} from "../../../../functions/species-builder/items/effect-carriers";
import { readUnknownPath } from "../../../../shared/object-readers";
import { MODULE_ID } from "../../../constants";
import { logInfo } from "../../../logging";
import { readSpeciesItem } from "./adapter";
import { syncCarrierEffects } from "./carrier-effects";
import { hasNativeSpeciesSupport } from "./migration";
import { worldSpeciesItems } from "./repository";

const FOLDER_NAME = "WFRP Customizer Species Effect Carriers";

export async function syncSpeciesEffectCarriers(): Promise<void> {
  if (hasNativeSpeciesSupport() || !game.user?.isGM) return;
  if (game.users?.activeGM && game.users.activeGM.id !== game.user.id) return;

  const sources = worldSpeciesItems()
    .map(readSpeciesItem)
    .filter((item) => item.effects.length);
  const generated = (game.items?.contents ?? []).filter((item) => carrierSpeciesUuid(item));
  const retained = new Set<string>();
  for (const item of sources) {
    const source = buildSpeciesEffectCarrier(item, MODULE_ID);
    let carrier = generated.find((entry) => carrierSpeciesUuid(entry) === item.uuid);
    if (carrier) {
      const description = readUnknownPath(carrier.toObject(), ["system", "description", "value"]);
      if (
        carrier.name !== source.name ||
        carrier.img !== source.img ||
        description !== source.system.description.value
      )
        await carrier.update({
          "name": source.name,
          "img": source.img,
          "system.description.value": source.system.description.value,
        });
      await syncCarrierEffects(carrier, source.effects);
    } else {
      const folder = await ensureCarrierFolder();
      carrier =
        (await Item.create({ ...source, folder: folder.id, ownership: { default: 2 } })) ??
        undefined;
      if (!carrier) throw new Error(`Foundry did not create the effects carrier for ${item.name}.`);
    }
    retained.add(carrier.id);
  }

  // Only derived world documents are reconciled. Actor-owned copies and old Builder Traits stay intact.
  for (const carrier of generated) {
    if (!retained.has(carrier.id)) await carrier.delete();
  }
  if (sources.length || generated.length)
    logInfo(`${MODULE_ID} | Synchronized ${sources.length} Species effect carrier(s).`);
}

function carrierSpeciesUuid(item: FoundryItemDocument): string | undefined {
  if (item.type !== "trait") return undefined;
  const uuid = readUnknownPath(item.toObject(), [
    "flags",
    MODULE_ID,
    SPECIES_EFFECT_CARRIER_FLAG,
    "speciesUuid",
  ]);
  return typeof uuid === "string" ? uuid : undefined;
}

async function ensureCarrierFolder(): Promise<FoundryFolderDocument> {
  const existing = game.folders.contents.find(
    (folder) => folder.type === "Item" && folder.name === FOLDER_NAME,
  );
  if (existing) return existing;
  const folder = await Folder.create({ name: FOLDER_NAME, type: "Item" });
  if (!folder) throw new Error("Foundry did not create the species effects carrier folder.");
  return folder;
}
