import type {
  NpcAdvancementKind,
  NpcAdvancementSourceSummary,
  NpcBuilderSettings,
  NpcCareerQueueEntry,
  NpcTraitDraftConfig,
} from "../../types/npc-builder";

import { createDefaultTraitConfig } from "./create-default-trait-config";

export const CAREER_ADVANCE_STEP = 5;

export function advancementKey(kind: NpcAdvancementKind, name: string): string {
  return `${kind}:${normalizeName(name)}`;
}

export function careerLevelAdvanceValue(career: NpcCareerQueueEntry): number {
  const level = career.level ?? 1;

  if (!Number.isFinite(level)) {
    return CAREER_ADVANCE_STEP;
  }

  return Math.max(1, Math.floor(level)) * CAREER_ADVANCE_STEP;
}

export function careerLevelLabel(career: NpcCareerQueueEntry): string {
  return career.name;
}

export function isBaseAdvancementAllowed(
  kind: NpcAdvancementKind,
  settings: NpcBuilderSettings,
): boolean {
  if (kind === "characteristic") {
    return settings.allowBaseActorCharacteristics;
  }

  if (kind === "skill") {
    return settings.allowBaseActorSkills;
  }

  return settings.allowBaseActorTalents;
}

export function mergeTraitConfig(
  config: NpcTraitDraftConfig,
  override: Partial<NpcTraitDraftConfig> | undefined,
): NpcTraitDraftConfig {
  return {
    ...createDefaultTraitConfig(),
    ...config,
    ...override,
  };
}

export function namesMatch(left: string, right: string): boolean {
  return normalizeName(left) === normalizeName(right);
}

export function normalizeName(name: string): string {
  return name.trim().toLocaleLowerCase();
}

export function normalizeQuantity(quantity: number): number {
  if (!Number.isFinite(quantity)) {
    return 1;
  }

  return Math.max(1, Math.floor(quantity));
}

export function sumSourceCounts(sources: NpcAdvancementSourceSummary[]): number {
  let total = 0;

  for (const source of sources) {
    total += source.count;
  }

  return total;
}

export function uniqueNames(names: string[]): string[] {
  const seen = new Set<string>();
  const unique: string[] = [];

  for (const name of names) {
    const normalized = normalizeName(name);

    if (!normalized || seen.has(normalized)) {
      continue;
    }

    seen.add(normalized);
    unique.push(name);
  }

  return unique;
}
