import type {
  SpeciesTableBridge,
  SpeciesTableDraft,
  SpeciesTableState,
} from "../../../types/species-table";
import { speciesTableProblems } from "../../../functions/species-table/draft";
import { speciesItemKey } from "../../../functions/species-builder/items/identity";
import { readSpeciesItem } from "../species-builder/items/adapter";
import { loadSpeciesBuilderSpeciesTable } from "../species-builder/world-table";
import {
  registerSpeciesTable,
  upsertManagedSpeciesTable,
} from "../species-builder/world-table/persistence";
import {
  importSpeciesSource,
  requireSpeciesTableGm,
  resolveSpeciesSource,
  resolveSpeciesTableDrop,
  speciesSourceFamily,
  speciesTableOptions,
} from "./items";

let saving = false;

function tableRevision(tableId?: string): string {
  return JSON.stringify({
    table: tableId ? game.tables?.get(tableId)?.toObject() : null,
    settings: game.settings.get("wfrp4e", "tableSettings"),
  });
}

export async function loadSpeciesTable(): Promise<SpeciesTableState> {
  requireSpeciesTableGm();
  const options = speciesTableOptions();
  const { draft } = await loadSpeciesBuilderSpeciesTable(options);
  return {
    draft: {
      ...draft,
      rows: draft.rows.map((row) => {
        const option = options.find((entry) => entry.key === row.speciesKey);
        const itemUuid =
          option?.itemUuid ?? (row.journalUuid?.startsWith("Item.") ? row.journalUuid : undefined);
        return {
          ...row,
          name: option?.label ?? row.name,
          ...(itemUuid ? { itemUuid } : {}),
          sources: itemUuid ? [{ uuid: itemUuid, name: row.name }] : [],
        };
      }),
    },
    options,
    revision: tableRevision(draft.tableId),
  };
}

async function assertFresh(revision: string): Promise<void> {
  if ((await loadSpeciesTable()).revision !== revision)
    throw new Error(
      "The world's Species table or table settings changed. Reload the editor before saving.",
    );
}

async function preflight(draft: SpeciesTableDraft): Promise<void> {
  const options = speciesTableOptions();
  for (const row of draft.rows) {
    if (!row.itemUuid) continue;
    const drop = await resolveSpeciesTableDrop(JSON.stringify({ uuid: row.itemUuid }));
    // Item edits while this window is open must not silently change the table being approved.
    if (drop.option.key !== row.speciesKey || drop.option.label !== row.name)
      throw new Error(
        `${row.name} changed. Reload the editor and drop the updated Species Item again.`,
      );
    for (const source of row.sources) {
      const family = await speciesSourceFamily(source.uuid);
      if (family[0]!.uuid !== drop.option.itemUuid)
        throw new Error(
          `${source.name} now belongs to a different species. Remove and drop it again.`,
        );
    }
    const other = options.find((entry) => entry.key === drop.option.key);
    if (other?.itemUuid && other.itemUuid !== drop.option.itemUuid)
      throw new Error(`Multiple Items use the species key “${row.speciesKey}”.`);
    if (!other) options.push(drop.option);
  }
  const problems = speciesTableProblems(draft, options);
  if (problems.length) throw new Error(problems.join("\n"));
}

export async function saveSpeciesTable(
  draft: SpeciesTableDraft,
  revision: string,
  register: boolean,
): Promise<SpeciesTableState> {
  requireSpeciesTableGm();
  if (saving)
    throw new Error("Another Species table save is in progress. Try again when it finishes.");
  saving = true;
  try {
    await assertFresh(revision);
    await preflight(draft);
    const prepared = structuredClone(draft);
    for (const row of prepared.rows) {
      if (!row.itemUuid) continue;
      await importSpeciesSource(row.itemUuid);
      for (const source of row.sources) await importSpeciesSource(source.uuid);
      const worldItem = await resolveSpeciesSource(row.itemUuid);
      row.speciesKey = speciesItemKey(readSpeciesItem(worldItem));
      row.itemUuid = worldItem.uuid;
      row.journalUuid = worldItem.uuid;
      row.name = speciesTableOptions().find((option) => option.key === row.speciesKey)!.label;
    }
    await assertFresh(revision);
    const problems = speciesTableProblems(prepared, speciesTableOptions());
    if (problems.length) throw new Error(problems.join("\n"));
    const table = await upsertManagedSpeciesTable(prepared);
    let registrationError: string | undefined;
    if (register) {
      try {
        await registerSpeciesTable(table.id);
      } catch (cause) {
        registrationError = cause instanceof Error ? cause.message : String(cause);
      }
    }
    return { ...(await loadSpeciesTable()), ...(registrationError ? { registrationError } : {}) };
  } finally {
    saving = false;
  }
}

export const speciesTableBridge: SpeciesTableBridge = {
  load: loadSpeciesTable,
  resolveDrop: resolveSpeciesTableDrop,
  save: saveSpeciesTable,
};
