export function isFoundryActor(document: unknown): document is FoundryActorDocument {
  return (
    typeof document === "object" &&
    document !== null &&
    "documentName" in document &&
    document.documentName === "Actor"
  );
}

export function isFoundryItem(document: unknown): document is FoundryItemDocument {
  return (
    typeof document === "object" &&
    document !== null &&
    "documentName" in document &&
    document.documentName === "Item"
  );
}

export function assertFoundryActor(
  document: unknown,
  message = "Expected a Foundry Actor.",
): FoundryActorDocument {
  if (!isFoundryActor(document)) {
    throw new Error(message);
  }

  return document;
}

export function assertFoundryItem(
  document: unknown,
  message = "Expected a Foundry Item.",
): FoundryItemDocument {
  if (!isFoundryItem(document)) {
    throw new Error(message);
  }

  return document;
}

export function assertFoundryItemType(
  document: unknown,
  type: string,
  message = `Expected a Foundry ${type} Item.`,
): FoundryItemDocument {
  const item = assertFoundryItem(document, message);

  if (item.type !== type) {
    throw new Error(message);
  }

  return item;
}
