import { computed, type Ref } from "vue";

import type {
  NpcBaseActorDraftData,
  NpcBuilderSettings,
  NpcQuickTraitSummary,
  NpcTraitDraftConfig,
  NpcTraitDraftEntry,
} from "../../types/npc-builder";

import {
  createSelectedTraitDraft,
  deriveNpcBuildTraits,
  deriveNpcTraits,
  deriveOptionalTraits,
  findTraitByName,
  getBaseTraitKey,
  hasTraitName,
} from "../../functions/npc-builder/traits/derive-traits";

interface TraitStoreSliceContext {
  baseActorDraftData: Ref<NpcBaseActorDraftData>;
  customTraits: Ref<NpcTraitDraftEntry[]>;
  ignoredBaseTraitKeys: Ref<Record<string, boolean>>;
  quickTraits: Ref<NpcQuickTraitSummary[]>;
  settings: Ref<NpcBuilderSettings>;
  traitConfigOverrides: Ref<Record<string, Partial<NpcTraitDraftConfig>>>;
}

export function createTraitStoreSlice(context: TraitStoreSliceContext) {
  const {
    baseActorDraftData,
    customTraits,
    ignoredBaseTraitKeys,
    quickTraits,
    settings,
    traitConfigOverrides,
  } = context;

  const traits = computed(() =>
    deriveNpcTraits({
      allowBaseActorTraits: settings.value.allowBaseActorTraits,
      baseActorDraftData: baseActorDraftData.value,
      customTraits: customTraits.value,
      ignoredBaseTraitKeys: ignoredBaseTraitKeys.value,
      traitConfigOverrides: traitConfigOverrides.value,
    }),
  );

  // The UI shows only selected traits, but build output also needs ignored
  // base traits so the copied Actor can delete those embedded Items.
  const buildTraits = computed(() =>
    deriveNpcBuildTraits({
      allowBaseActorTraits: settings.value.allowBaseActorTraits,
      baseActorDraftData: baseActorDraftData.value,
      ignoredBaseTraitKeys: ignoredBaseTraitKeys.value,
      selectedTraits: traits.value,
      traitConfigOverrides: traitConfigOverrides.value,
    }),
  );

  const optionalTraits = computed(() => deriveOptionalTraits(baseActorDraftData.value));

  function addCustomTrait(trait: NpcTraitDraftEntry): void {
    const existingQuickTrait = findQuickTraitByName(trait.name);
    const existingOptionalTrait = findOptionalTraitByName(trait.name);

    if (existingOptionalTrait) {
      setOptionalTraitSelected(existingOptionalTrait, true);
      return;
    }

    if (existingQuickTrait) {
      setQuickTraitSelected(existingQuickTrait, true);
      return;
    }

    addSelectedTrait(trait);
  }

  function removeCustomTrait(key: string): void {
    customTraits.value = customTraits.value.filter((entry) => entry.key !== key);
    delete traitConfigOverrides.value[key];
  }

  function setQuickTraitSelected(trait: NpcQuickTraitSummary, selected: boolean): void {
    setTraitDraftSelected("quick", trait, selected);
  }

  function setOptionalTraitSelected(trait: NpcQuickTraitSummary, selected: boolean): void {
    setTraitDraftSelected("optional", trait, selected);
  }

  function setTraitDraftSelected(
    source: "optional" | "quick",
    trait: NpcQuickTraitSummary,
    selected: boolean,
  ): void {
    const selectedTrait = createSelectedTraitDraft(source, trait);

    if (!selected) {
      removeCustomTrait(selectedTrait.key);
      setMatchingBaseTraitIgnored(trait.name, true);
      return;
    }

    if (setMatchingBaseTraitIgnored(trait.name, false)) {
      return;
    }

    const existing = customTraits.value.find((entry) => entry.key === selectedTrait.key);

    if (existing) {
      return;
    }

    addSelectedTrait(selectedTrait);
  }

  function addSelectedTrait(trait: NpcTraitDraftEntry): void {
    if (hasTraitName(traits.value, trait.name)) {
      return;
    }

    if (!customTraits.value.some((entry) => entry.key === trait.key)) {
      customTraits.value.push(trait);
    }
  }

  function setTraitConfig(key: string, config: Partial<NpcTraitDraftConfig>): void {
    traitConfigOverrides.value[key] = {
      ...traitConfigOverrides.value[key],
      ...config,
    };
  }

  function setBaseTraitIgnored(key: string, ignored: boolean): void {
    if (!key.startsWith("base:")) {
      return;
    }

    if (!ignored) {
      delete ignoredBaseTraitKeys.value[key];
      return;
    }

    ignoredBaseTraitKeys.value[key] = true;
  }

  function findOptionalTraitByName(name: string): NpcQuickTraitSummary | undefined {
    return findTraitByName(optionalTraits.value, name);
  }

  function findQuickTraitByName(name: string): NpcQuickTraitSummary | undefined {
    return findTraitByName(quickTraits.value, name);
  }

  function findBaseTraitByName(name: string): null | { ignored: boolean; key: string } {
    const trait = findTraitByName(baseActorDraftData.value.traits, name);

    if (!trait) {
      return null;
    }

    const key = getBaseTraitKey(trait);

    return {
      ignored: Boolean(ignoredBaseTraitKeys.value[key]),
      key,
    };
  }

  function setMatchingBaseTraitIgnored(name: string, ignored: boolean): boolean {
    const baseTrait = findBaseTraitByName(name);

    if (!baseTrait) {
      return false;
    }

    setBaseTraitIgnored(baseTrait.key, ignored);

    return true;
  }

  return {
    addCustomTrait,
    buildTraits,
    optionalTraits,
    removeCustomTrait,
    setBaseTraitIgnored,
    setOptionalTraitSelected,
    setQuickTraitSelected,
    setTraitConfig,
    traits,
  };
}
