<script setup lang="ts">
import type { NpcFolderSummary } from "../../../../../types/npc-builder";

defineProps<{
  buttonLabel?: string;
  createName: string;
  defaultOptionLabel: string;
  disabled: boolean;
  folders: NpcFolderSummary[];
  folderLabel: string;
  selectedUuid: string;
}>();

const emit = defineEmits<{
  createNameChange: [name: string];
  saveFolderName: [];
  selectedUuidChange: [uuid: string];
}>();

function handleSelectedUuidChange(event: Event): void {
  const select = event.target as HTMLSelectElement | null;

  emit("selectedUuidChange", select?.value ?? "");
}

function handleCreateNameChange(event: Event): void {
  const input = event.target as HTMLInputElement | null;

  emit("createNameChange", input?.value ?? "");
}
</script>

<template>
  <section>
    <fieldset class="dui-fieldset">
      <legend class="dui-fieldset-legend">{{ folderLabel }}</legend>
      <select
        :aria-label="folderLabel"
        class="dui-select dui-select-sm"
        :value="selectedUuid"
        @change="handleSelectedUuidChange"
      >
        <option value="">{{ defaultOptionLabel }}</option>
        <option v-for="folder in folders" :key="folder.uuid" :value="folder.uuid">
          {{ folder.name }}
        </option>
      </select>
    </fieldset>
    <fieldset class="dui-fieldset">
      <legend class="dui-fieldset-legend">Create or use by name</legend>
      <input
        :aria-label="`Create or use ${folderLabel} by name`"
        class="dui-input dui-input-sm"
        :value="createName"
        placeholder="Folder name"
        type="text"
        @input="handleCreateNameChange"
      />
    </fieldset>
    <div class="dui-card-actions">
      <button
        class="dui-btn dui-btn-sm"
        :disabled="disabled || !createName.trim()"
        type="button"
        @click="emit('saveFolderName')"
      >
        {{ buttonLabel ?? "Save Folder" }}
      </button>
    </div>
  </section>
</template>
