export type UnknownRecord = Record<string, unknown>;

export function isRecord(value: unknown): value is UnknownRecord {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function readUnknownPath(source: unknown, path: string[]): unknown {
  let current = source;

  for (const key of path) {
    if (!isRecord(current) || !(key in current)) {
      return undefined;
    }

    current = current[key];
  }

  return current;
}

export function readStringPath(source: unknown, path: string[]): string {
  const value = readUnknownPath(source, path);

  return typeof value === "string" ? value.trim() : "";
}

export function readStringArrayPath(source: unknown, path: string[]): string[] {
  const value = readUnknownPath(source, path);

  return Array.isArray(value)
    ? value.filter((entry): entry is string => typeof entry === "string")
    : [];
}

export function readNumberFromPaths(source: unknown, paths: string[][], fallback = 0): number {
  return readOptionalNumberFromPaths(source, paths) ?? fallback;
}

export function readOptionalNumberFromPaths(source: unknown, paths: string[][]): null | number {
  for (const path of paths) {
    const value = Number(readUnknownPath(source, path));

    if (Number.isFinite(value)) {
      return value;
    }
  }

  return null;
}

export function readBooleanFromPaths(
  source: unknown,
  paths: string[][],
  fallback = false,
): boolean {
  for (const path of paths) {
    const value = readUnknownPath(source, path);

    if (typeof value === "boolean") {
      return value;
    }
  }

  return fallback;
}

export function toStringList(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value.flatMap(toStringList);
  }

  if (typeof value === "string") {
    return value
      .split(/[\n\r,;]/)
      .map((entry) => entry.trim())
      .filter(Boolean);
  }

  if (isRecord(value)) {
    return Object.values(value).flatMap(toStringList);
  }

  return [];
}

export function setObjectPath(source: UnknownRecord, path: string[], value: unknown): void {
  let current = source;

  for (const key of path.slice(0, -1)) {
    const next = current[key];

    if (!isRecord(next)) {
      current[key] = {};
    }

    current = current[key] as UnknownRecord;
  }

  current[path[path.length - 1] ?? ""] = value;
}
