import type { Component } from "vue";

import WorkbenchApp from "../../../view/apps/workbench/WorkbenchApp.vue";
import { MODULE_ID, MODULE_TITLE } from "../../constants";
import { DaisyExampleApplication } from "../daisy-example/DaisyExampleApplication";
import { NpcBuilderApplication } from "../npc-builder/NpcBuilderApplication";
import { openEffectBuilders } from "../effect-builders/open";
import { openSpeciesTableEditor } from "../species-table/SpeciesTableApplication";
import { FoundryVueApplication } from "../FoundryVueApplication";

export class WorkbenchApplication extends FoundryVueApplication {
  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    id: `${MODULE_ID}-workbench`,
    classes: [MODULE_ID, "wfrp4e-customizer-workbench"],
    position: {
      height: 530,
      width: 640,
    },
    window: {
      icon: "fa-solid fa-screwdriver-wrench",
      title: MODULE_TITLE,
    },
  };

  protected override getVueComponent(): Component {
    return WorkbenchApp;
  }

  protected override getVueProps(): Record<string, unknown> {
    return {
      openDaisyProbe: () => new DaisyExampleApplication().render(true),
      openNpcBuilder: () => new NpcBuilderApplication().render(true),
      openEffectBuilders,
      openSpeciesTableEditor,
    };
  }
}
