import { isRecord, readStringPath, readUnknownPath } from "../../shared/object-readers";

import {
  GENERATED_CAREER_TABLE_FLAG,
  serializeSpeciesCareerTableSource,
  type GeneratedCareerTableIdentity,
} from "./career-tables";

export interface ExistingCareerTableSource {
  id: string;
  source: Record<string, unknown>;
}

export interface CareerTableSyncEntry {
  action: "create" | "skip" | "update";
  existingId?: string;
  source: Record<string, unknown>;
}

export interface CareerTableSyncPlan {
  entries: CareerTableSyncEntry[];
  obsoleteIds: string[];
}

export function planCareerTableSync(
  desiredSources: Record<string, unknown>[],
  existingTables: ExistingCareerTableSource[],
  flagScope: string,
  force: boolean,
): CareerTableSyncPlan {
  const available = new Map<string, ExistingCareerTableSource[]>();
  const unidentifiedIds: string[] = [];

  for (const existing of existingTables) {
    const identity = readGeneratedCareerTableIdentity(existing.source, flagScope);

    if (identity) {
      const key = careerTableIdentityKey(identity);
      available.set(key, [...(available.get(key) ?? []), existing]);
    } else {
      unidentifiedIds.push(existing.id);
    }
  }

  const entries = desiredSources.map((source): CareerTableSyncEntry => {
    const identity = readGeneratedCareerTableIdentity(source, flagScope);
    const matches = identity ? available.get(careerTableIdentityKey(identity)) : undefined;
    const existing = matches?.shift();

    if (!existing) {
      return { action: "create", source };
    }

    const current =
      serializeSpeciesCareerTableSource(existing.source, flagScope) ===
      serializeSpeciesCareerTableSource(source, flagScope);

    return {
      action: force || !current ? "update" : "skip",
      existingId: existing.id,
      source,
    };
  });

  return {
    entries,
    obsoleteIds: [
      ...unidentifiedIds,
      ...[...available.values()].flatMap((matches) => matches.map((existing) => existing.id)),
    ],
  };
}

export function readGeneratedCareerTableIdentity(
  source: unknown,
  flagScope: string,
): GeneratedCareerTableIdentity | undefined {
  const flag = readUnknownPath(source, ["flags", flagScope, GENERATED_CAREER_TABLE_FLAG]);

  if (!isRecord(flag)) {
    return undefined;
  }

  const speciesKey = readStringPath(flag, ["speciesKey"]);

  return speciesKey
    ? {
        speciesKey,
        subspeciesKey: readStringPath(flag, ["subspeciesKey"]),
      }
    : undefined;
}

function careerTableIdentityKey(identity: GeneratedCareerTableIdentity): string {
  return `${identity.speciesKey}\u0000${identity.subspeciesKey}`;
}
