import type { NpcBaseActorSummary } from "../../../../../types/npc-builder";

import { toActorSummary } from "../actors";

export function listMountActors(): NpcBaseActorSummary[] {
  return game.actors.contents
    .map(toActorSummary)
    .sort((left, right) => left.name.localeCompare(right.name));
}
