<script setup lang="ts">
import { storeToRefs } from "pinia";
import { computed, ref, useId, watch } from "vue";

import type { NpcBuilderBridge } from "../../../../types/npc-builder";

import {
  calculateCombinedProfile,
  NPC_ACTOR_SIZE_LABELS,
} from "../../../../functions/npc-builder/combined-profile";
import { useNpcBuilderStore } from "../../../../state/npc-builder";
import DocumentDrop from "../../../components/DocumentDrop.vue";
import { toErrorMessage } from "../NpcBuilderApp/errors";
import NpcBuilderSection from "./NpcBuilderSection.vue";
import CombinedProfilePreview from "./NpcBuilderMountTab/CombinedProfilePreview.vue";

const props = defineProps<{
  bridge: NpcBuilderBridge;
}>();

const store = useNpcBuilderStore();
const {
  baseActorCombatProfile,
  mountActorProfile,
  mountActors,
  selectedBaseActorUuid,
  selectedMountActorUuid,
} = storeToRefs(store);
const actorFilter = ref("");
const errorMessage = ref("");
const isLoadingMount = ref(false);
const fieldId = useId();
let mountLoadId = 0;

const filteredMountActors = computed(() => {
  const query = actorFilter.value.trim().toLocaleLowerCase();

  return mountActors.value.filter((actor) => {
    return (
      actor.uuid !== selectedBaseActorUuid.value &&
      (!query || actor.name.toLocaleLowerCase().includes(query))
    );
  });
});
const selectedMountActor = computed(() => {
  return mountActors.value.find((actor) => actor.uuid === selectedMountActorUuid.value) ?? null;
});
const combinedProfile = computed(() => {
  if (!baseActorCombatProfile.value || !mountActorProfile.value) {
    return null;
  }

  return calculateCombinedProfile(baseActorCombatProfile.value, mountActorProfile.value);
});

watch(
  selectedMountActorUuid,
  async (uuid) => {
    const loadId = ++mountLoadId;
    errorMessage.value = "";

    if (!uuid) {
      store.hydrateMountActorProfile(null);
      isLoadingMount.value = false;
      return;
    }

    if (uuid === selectedBaseActorUuid.value) {
      store.clearMountSelection();
      errorMessage.value = "The rider and mount must be different Actors.";
      return;
    }

    isLoadingMount.value = true;

    try {
      const profile = await props.bridge.loadActorCombatProfile(uuid);

      if (loadId === mountLoadId) {
        store.hydrateMountActorProfile(profile);
      }
    } catch (error) {
      if (loadId === mountLoadId) {
        store.hydrateMountActorProfile(null);
        errorMessage.value = toErrorMessage(error);
      }
    } finally {
      if (loadId === mountLoadId) {
        isLoadingMount.value = false;
      }
    }
  },
  { immediate: true },
);

function handleMountChange(event: Event): void {
  const select = event.target as HTMLSelectElement | null;

  store.selectMountActorUuid(select?.value ?? "");
}

async function handleMountDrop(data: string): Promise<void> {
  errorMessage.value = "";

  try {
    const actor = await props.bridge.resolveActorDrop(data);

    if (actor.uuid === selectedBaseActorUuid.value) {
      throw new Error("The rider and mount must be different Actors.");
    }

    store.selectMountActor(actor);
  } catch (error) {
    errorMessage.value = toErrorMessage(error);
  }
}
</script>

<template>
  <div class="app:grid app:gap-3">
    <p class="dui-alert dui-alert-info">
      Mounts are optional. A selected mount is folded into one simplified NPC profile during build.
    </p>

    <NpcBuilderSection
      description="Choose any world Actor as the mount. This selection does not create a live WFRP mount relationship."
      number="1"
      title="Mount Actor"
    >
      <div class="app:grid app:gap-3 md:app:grid-cols-2">
        <fieldset class="dui-fieldset">
          <legend class="dui-fieldset-legend">Search mounts</legend>
          <label class="dui-label" :for="`${fieldId}-filter`">Actor name</label>
          <input
            :id="`${fieldId}-filter`"
            v-model="actorFilter"
            aria-label="Filter mount actors by name"
            class="dui-input dui-input-sm"
            placeholder="Filter world actors"
            type="search"
          />
        </fieldset>

        <fieldset class="dui-fieldset">
          <legend class="dui-fieldset-legend">Selected mount</legend>
          <label class="dui-label" :for="`${fieldId}-mount`">Mount statblock</label>
          <select
            :id="`${fieldId}-mount`"
            aria-label="Selected mount actor"
            class="dui-select dui-select-sm"
            :disabled="!selectedBaseActorUuid"
            :value="selectedMountActorUuid"
            @change="handleMountChange"
          >
            <option value="">No combined mount</option>
            <option v-for="actor in filteredMountActors" :key="actor.uuid" :value="actor.uuid">
              {{ actor.name }}
            </option>
          </select>
        </fieldset>
      </div>

      <DocumentDrop
        :disabled="!selectedBaseActorUuid"
        description="Drop a world Actor to use as the mount."
        title="Drop Mount Actor"
        variant="compact"
        @drop-data="handleMountDrop"
      />

      <div v-if="selectedMountActorUuid" class="dui-card-actions">
        <button
          class="dui-btn dui-btn-ghost dui-btn-sm"
          type="button"
          @click="store.clearMountSelection"
        >
          Clear Mount
        </button>
      </div>

      <p v-if="!selectedBaseActorUuid" class="dui-alert dui-alert-warning">
        Choose the rider on the Build tab before selecting a mount.
      </p>
      <p v-else-if="errorMessage" class="dui-alert dui-alert-error" role="alert">
        {{ errorMessage }}
      </p>
      <p v-else-if="isLoadingMount" aria-live="polite" class="dui-alert" role="status">
        Loading mount profile...
      </p>

      <article v-else-if="selectedMountActor && mountActorProfile" class="dui-alert">
        <div v-if="selectedMountActor.img" class="dui-avatar">
          <div class="app:size-16 app:shrink-0 app:rounded-lg">
            <img
              :src="selectedMountActor.img"
              alt=""
              class="app:h-full app:w-full app:object-cover"
              height="64"
              width="64"
            />
          </div>
        </div>
        <div>
          <strong>{{ selectedMountActor.name }}</strong>
          <span>
            Movement {{ mountActorProfile.movement }} | Wounds {{ mountActorProfile.wounds }} |
            {{ NPC_ACTOR_SIZE_LABELS[mountActorProfile.size] }}
          </span>
        </div>
      </article>
    </NpcBuilderSection>

    <CombinedProfilePreview
      v-if="combinedProfile && baseActorCombatProfile && mountActorProfile"
      :mount="mountActorProfile"
      :plan="combinedProfile"
      :rider="baseActorCombatProfile"
    />
  </div>
</template>
