import type { Component } from "vue";
import type { EffectBuilderKind } from "../../../types/effect-builders";
import type { GrantItemReference } from "../../../types/item-grants";
import { EFFECT_BUILDERS } from "../../../functions/effect-builders/catalogue";
import { useEffectBuilderStore } from "../../../state/effect-builders";
import { pinia } from "../../../state/pinia";
import EffectBuilderApp from "../../../view/apps/effect-builders/EffectBuilderApp.vue";
import { MODULE_ID } from "../../constants";
import { FoundryVueApplication } from "../FoundryVueApplication";
import { effectBuilderBridge } from "./bridge";

let builderSequence = 0;

export class EffectBuilderApplication extends FoundryVueApplication {
  readonly kind: EffectBuilderKind;
  readonly destination: GrantItemReference | null;
  readonly storeId: string;

  constructor(kind: EffectBuilderKind, destination: GrantItemReference | null = null) {
    const id = `${MODULE_ID}-effect-${++builderSequence}`;
    super({
      id,
      window: {
        title: `${EFFECT_BUILDERS.find((entry) => entry.kind === kind)!.title} Effect Builder`,
      },
    });
    this.kind = kind;
    this.destination = destination;
    this.storeId = id;
  }

  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    classes: [MODULE_ID],
    position: { height: 780, width: 620 },
    window: { icon: "fa-solid fa-wand-magic-sparkles", resizable: true },
  };

  protected override getVueComponent(): Component {
    return EffectBuilderApp;
  }
  protected override getVueProps(): Record<string, unknown> {
    return {
      id: this.storeId,
      kind: this.kind,
      destination: this.destination,
      bridge: effectBuilderBridge,
      close: () => this.close(),
    };
  }
  protected override async _preClose(
    options: foundry.applications.types.ApplicationRenderOptions,
  ): Promise<void> {
    const store = useEffectBuilderStore(this.storeId);
    await super._preClose(options);
    store.$dispose();
    delete pinia.state.value[`effect-builder:${this.storeId}`];
  }
}
