import type {
  NpcCombinedProfilePlan,
  NpcMountTraitContribution,
} from "../../../../../types/npc-builder";

import { isArmourTraitName } from "../../../../../functions/npc-builder/combined-profile";
import { setObjectPath } from "../../../../../shared/object-readers";
import { MODULE_ID } from "../../../../constants";

const GENERATED_MOUNT_TRAIT_FLAG = "generatedMountTrait";

export function buildMountTraitSources(
  mount: FoundryActorDocument,
  plan: NpcCombinedProfilePlan,
): FoundryItemSource[] {
  return plan.traits.flatMap((contribution) => {
    if (!contribution.included || isArmourTraitName(contribution.name)) {
      return [];
    }

    const sourceItem = findMountTrait(mount, contribution);

    if (!sourceItem) {
      return [];
    }

    const source = sourceItem.toObject();

    delete source._id;
    source["name"] = contribution.outputName;
    setObjectPath(source, ["system", "disabled"], false);
    setObjectPath(source, ["flags", MODULE_ID, GENERATED_MOUNT_TRAIT_FLAG], {
      mountUuid: mount.uuid,
      sourceTraitUuid: contribution.sourceUuid,
    });

    if (contribution.fixedDamage !== null) {
      freezeMountAttack(source, contribution.fixedDamage);
    }

    return [source];
  });
}

export function findMountTrait(
  mount: FoundryActorDocument,
  contribution: NpcMountTraitContribution,
): FoundryItemDocument | null {
  return (
    mount.items?.contents.find((item) => {
      return item.type === "trait" && item.uuid === contribution.sourceUuid;
    }) ?? null
  );
}

function freezeMountAttack(source: FoundryItemSource, fixedDamage: number): void {
  setObjectPath(source, ["system", "specification", "value"], String(fixedDamage));
  setObjectPath(source, ["system", "rollable", "bonusCharacteristic"], "");
  setObjectPath(source, ["system", "rollable", "rollCharacteristic"], "ws");
  setObjectPath(source, ["system", "rollable", "skill"], "");
}
