import { compileWoundFormula } from "./compiler";
import {
  buildAttributeHelperLines,
  buildAttributeReferenceLines,
  buildKeywordLines,
} from "./script-lines";

export function buildCompiledWoundFormulaScriptLines(formula: string): string[] {
  const compiledFormula = compileWoundFormula(formula);

  return [
    ...buildKeywordLines(compiledFormula.usedKeywords),
    ...buildAttributeHelperLines(compiledFormula.references),
    ...buildAttributeReferenceLines(compiledFormula.references),
    "",
    `args.wounds = ${compiledFormula.expression};`,
  ];
}
