export type NpcBuilderBuildPage = "build-actor" | "build-careers" | "build-quick";

export type NpcBuilderDetailedPage =
  | "detail-characteristics"
  | "detail-skills"
  | "detail-spells"
  | "detail-talents"
  | "mount"
  | "traits"
  | "trappings";

export type NpcBuilderSettingsPage =
  | "settings-advancement"
  | "settings-folders"
  | "settings-resolution"
  | "settings-suggestions";

export type NpcBuilderActiveTab =
  | NpcBuilderBuildPage
  | NpcBuilderDetailedPage
  | NpcBuilderSettingsPage
  | "automatic-xp";

export type NpcBuilderActivePage = NpcBuilderActiveTab;

export type NpcBuilderAdvancementPage =
  | "automatic-xp"
  | "detail-characteristics"
  | "detail-skills"
  | "detail-talents";

export function isBuildPage(page: NpcBuilderActivePage): page is NpcBuilderBuildPage {
  return page === "build-actor" || page === "build-careers" || page === "build-quick";
}

export function isSettingsPage(page: NpcBuilderActivePage): page is NpcBuilderSettingsPage {
  return (
    page === "settings-advancement" ||
    page === "settings-folders" ||
    page === "settings-resolution" ||
    page === "settings-suggestions"
  );
}

export function isAdvancementPage(page: NpcBuilderActivePage): page is NpcBuilderAdvancementPage {
  return (
    page === "automatic-xp" ||
    page === "detail-characteristics" ||
    page === "detail-skills" ||
    page === "detail-talents"
  );
}

export function isDetailedPage(page: NpcBuilderActivePage): page is NpcBuilderDetailedPage {
  return (
    page === "detail-characteristics" ||
    page === "detail-skills" ||
    page === "detail-spells" ||
    page === "detail-talents" ||
    page === "mount" ||
    page === "traits" ||
    page === "trappings"
  );
}

export function getPageLabel(page: NpcBuilderActivePage): string {
  const labels: Record<NpcBuilderActivePage, string> = {
    "automatic-xp": "Automatic XP Advancement",
    "build-actor": "Choose Actor",
    "build-careers": "Queue Careers",
    "build-quick": "Quick Build",
    "detail-characteristics": "Characteristics",
    "detail-skills": "Skills",
    "detail-spells": "Spells",
    "detail-talents": "Talents",
    "mount": "Combined Profile",
    "settings-advancement": "Advancement Settings",
    "settings-folders": "Folder Settings",
    "settings-resolution": "Resolution Settings",
    "settings-suggestions": "Suggestion Settings",
    "traits": "Traits",
    "trappings": "Trappings",
  };

  return labels[page];
}
