import type { SpeciesEffectSource } from "../../../../types/species-builder/species-item";
import { copySpeciesEffect } from "../../../../functions/species-builder/items/effect-carriers";
import { readSpeciesEffectSources } from "./effect-sources";

export async function syncCarrierEffects(
  carrier: FoundryItemDocument,
  effects: SpeciesEffectSource[],
): Promise<void> {
  if (
    !carrier.createEmbeddedDocuments ||
    !carrier.updateEmbeddedDocuments ||
    !carrier.deleteEmbeddedDocuments
  )
    throw new Error("The species carrier does not support embedded Active Effects.");
  const current = readSpeciesEffectSources(carrier.toObject()["effects"]);
  const wantedIds = new Set(effects.map((effect) => effect._id));
  const removed = current
    .filter((effect) => !wantedIds.has(effect._id))
    .map((effect) => effect._id);
  const added = effects.filter((effect) => !current.some((entry) => entry._id === effect._id));
  const changed = effects.filter((effect) => {
    const existing = current.find((entry) => entry._id === effect._id);
    return existing && JSON.stringify(copySpeciesEffect(existing)) !== JSON.stringify(effect);
  });
  if (removed.length) await carrier.deleteEmbeddedDocuments("ActiveEffect", removed);
  if (changed.length)
    await carrier.updateEmbeddedDocuments("ActiveEffect", changed, { recursive: false });
  if (added.length) await carrier.createEmbeddedDocuments("ActiveEffect", added, { keepId: true });
}
