import { buildCompiledWoundFormulaScriptLines } from "../species-builder/wound-formula/index";

const CAPTURE_LINES = [
  'const storageKey = "__wfrp4eCustomizerWoundFormulaArgs";',
  "const sourceId = this.effect.id;",
];

export function buildWoundFormulaEffect(name: string, formula: string): Record<string, unknown> {
  return {
    changes: [],
    disabled: false,
    img: "icons/svg/regen.svg",
    name,
    transfer: true,
    system: {
      transferData: { documentType: "Actor", type: "document" },
      scriptData: [
        {
          label: `${name} Capture`,
          trigger: "preWoundCalc",
          // Retain the shared args object so other preWoundCalc effects can still modify bonuses.
          script: [
            ...CAPTURE_LINES,
            "this.actor[storageKey] ||= {};",
            "this.actor[storageKey][sourceId] = args;",
          ].join("\n"),
        },
        {
          label: name,
          trigger: "woundCalc",
          script: [
            ...CAPTURE_LINES,
            "const preWoundArgs = this.actor[storageKey][sourceId];",
            "const actor = this.actor;",
            ...buildCompiledWoundFormulaScriptLines(formula),
          ].join("\n"),
        },
      ],
    },
  };
}
