<script setup lang="ts">
import { useId } from "vue";
import { useEffectBuilderStore } from "../../../state/effect-builders";
const props = defineProps<{ id: string }>();
const store = useEffectBuilderStore(props.id);
const fieldId = `${props.id}-${useId()}`;
</script>

<template>
  <fieldset class="dui-fieldset">
    <legend class="dui-fieldset-legend">Granted Items</legend>
    <label :for="`${fieldId}-lifetime`" class="dui-label">When the effect is removed</label>
    <select
      :id="`${fieldId}-lifetime`"
      aria-label="When the effect is removed"
      class="dui-select app:w-full"
      :value="store.draft.recipe.lifetime"
      @change="
        store.setLifetime(
          ($event.target as HTMLSelectElement).value as 'detached' | 'linked-to-effect',
        )
      "
    >
      <option value="linked-to-effect">Remove the granted Items too</option>
      <option value="detached">Keep the granted Items</option>
    </select>
    <label v-if="store.draft.recipe.lifetime === 'detached'" class="dui-label">
      <input
        v-model="store.draft.recipe.ownerAction"
        type="checkbox"
        class="dui-checkbox"
        true-value="delete-after-grant"
        false-value="keep"
      />
      Remove the source Item after a successful grant
    </label>
  </fieldset>
</template>
