import type {
  SpeciesItemRecord,
  SpeciesItemReference,
  SpeciesItemTableData,
} from "../../../../types/species-builder/species-item";
import { careerTableFromDocument } from "../runtime-species/career-table";
import { isRecord } from "../../../../shared/object-readers";
import { findImportedReference } from "./imported-references";

export async function resolveSpeciesItemTables(
  record: SpeciesItemRecord,
): Promise<SpeciesItemTableData> {
  const data: SpeciesItemTableData = {};
  const talentTable = resolveTable(record.system.tables.talents);
  if (talentTable) {
    const key = talentTable.getFlag("wfrp4e", "key");
    if (typeof key !== "string" || !key.trim())
      throw new Error(`${record.name}: the random Talent table needs a WFRP table key.`);
    data.randomTalentKey = key;
  }
  const reference = record.system.tables.career;
  // Career tables are projected into world columns, so their sources can stay in a locked pack.
  const careerTable = reference.uuid.startsWith("Compendium.")
    ? (findImportedReference(reference, game.tables?.contents ?? []) ??
      (await fromUuid(reference.uuid)))
    : resolveTable(reference);
  if (
    reference.uuid.startsWith("Compendium.") &&
    (!isRecord(careerTable) || careerTable["documentName"] !== "RollTable")
  )
    throw new Error(`${record.name}: the referenced Career RollTable could not be resolved.`);
  if (careerTable) {
    const definition = careerTableFromDocument(careerTable);
    if (!definition)
      throw new Error(`${record.name}: the referenced Career table has no usable rows.`);
    data.careerTable = definition;
  }
  return data;
}

function resolveTable(reference: SpeciesItemReference): FoundryRollTableDocument | undefined {
  if (!reference.uuid && !reference.id) return undefined;
  const table = findImportedReference(reference, game.tables?.contents ?? []);
  if (!table)
    throw new Error(
      `Import the referenced RollTable ${reference.name || reference.uuid || reference.id} into the world and relink it.`,
    );
  return table;
}
