<script setup lang="ts">
import { storeToRefs } from "pinia";
import { computed, ref, watch } from "vue";

import {
  getNpcAutoAdvanceStrategy,
  listNpcAutoAdvanceStrategies,
} from "../../../../functions/npc-builder/auto-advance";
import { useNpcBuilderStore } from "../../../../state/npc-builder";
import type { NpcBuilderAdvancementPage } from "../NpcBuilderApp/types";
import AdvancementRowsPanel from "./NpcBuilderAdvancementsTab/AdvancementRowsPanel.vue";
import AutoAdvancePanel from "./NpcBuilderAdvancementsTab/AutoAdvancePanel.vue";
import TalentRowsPanel from "./NpcBuilderAdvancementsTab/TalentRowsPanel.vue";

defineProps<{
  page: NpcBuilderAdvancementPage;
}>();

const store = useNpcBuilderStore();
const { advancements, estimatedNpcXp, maximizableTalentCount } = storeToRefs(store);
const autoAdvanceStrategies = listNpcAutoAdvanceStrategies();
const selectedAutoAdvanceStrategyId = ref("skill-master");
const autoAdvanceTargetXp = ref(0);

const characteristics = computed(() =>
  advancements.value.filter((entry) => entry.kind === "characteristic"),
);

const skills = computed(() => advancements.value.filter((entry) => entry.kind === "skill"));

const talents = computed(() => advancements.value.filter((entry) => entry.kind === "talent"));

const manualAdvanceCount = computed(() => {
  return advancements.value.filter((entry) => entry.current !== entry.careerValue).length;
});

const selectedAutoAdvanceStrategy = computed(() => {
  return (
    getNpcAutoAdvanceStrategy(selectedAutoAdvanceStrategyId.value) ??
    autoAdvanceStrategies[0] ??
    null
  );
});

const canRunAutoAdvance = computed(() => {
  return (
    selectedAutoAdvanceStrategy.value !== null &&
    autoAdvanceTargetXp.value > estimatedNpcXp.value.total
  );
});

watch(
  () => estimatedNpcXp.value.total,
  (total) => {
    if (autoAdvanceTargetXp.value < total) {
      autoAdvanceTargetXp.value = total;
    }
  },
  { immediate: true },
);

function runAutoAdvance(): void {
  const strategy = selectedAutoAdvanceStrategy.value;

  if (!strategy) {
    return;
  }

  store.applyAutoAdvance(strategy, autoAdvanceTargetXp.value);
}
</script>

<template>
  <section>
    <AdvancementRowsPanel
      v-if="page === 'detail-characteristics'"
      :entries="characteristics"
      :estimated-npc-xp="estimatedNpcXp"
      :manual-advance-count="manualAdvanceCount"
      section-number=""
      title="Characteristics"
      @adjust-current="store.adjustAdvancementCurrent"
      @remove-custom="store.removeCustomAdvancement"
      @reset-all="store.resetAllAdvancementCurrents"
      @reset-current="store.resetAdvancementCurrent"
      @total-change="store.setAdvancementTotal"
    />

    <AdvancementRowsPanel
      v-else-if="page === 'detail-skills'"
      :entries="skills"
      section-number=""
      show-skill-specialization-badges
      title="Skills"
      @adjust-current="store.adjustAdvancementCurrent"
      @remove-custom="store.removeCustomAdvancement"
      @reset-current="store.resetAdvancementCurrent"
      @total-change="store.setAdvancementTotal"
    />

    <TalentRowsPanel
      v-else-if="page === 'detail-talents'"
      :maximizable-talent-count="maximizableTalentCount"
      :talents="talents"
      @adjust-current="store.adjustAdvancementCurrent"
      @maximize-talents="store.maximizeTalents"
      @remove-custom="store.removeCustomAdvancement"
      @reset-current="store.resetAdvancementCurrent"
      @total-change="store.setAdvancementTotal"
    />

    <AutoAdvancePanel
      v-else
      :auto-advance-strategies="autoAdvanceStrategies"
      :can-run-auto-advance="canRunAutoAdvance"
      :selected-auto-advance-strategy="selectedAutoAdvanceStrategy"
      :selected-auto-advance-strategy-id="selectedAutoAdvanceStrategyId"
      :target-xp="autoAdvanceTargetXp"
      @run-auto-advance="runAutoAdvance"
      @strategy-change="selectedAutoAdvanceStrategyId = $event"
      @target-xp-change="autoAdvanceTargetXp = $event"
    />
  </section>
</template>
