export const DEFAULT_WFRP_CHARACTERISTIC_ROLL_FORMULA = "2d10";

export function getWfrpCharacteristicRollExpression(formula: string | undefined): string {
  const rollExpression = formula?.split("+")[0]?.trim();

  if (!rollExpression) {
    return DEFAULT_WFRP_CHARACTERISTIC_ROLL_FORMULA;
  }

  return normalizeWfrpCharacteristicRollExpression(rollExpression);
}

export function canSwapWfrpCharacteristicRollFormulas(
  firstFormula: string | undefined,
  secondFormula: string | undefined,
): boolean {
  return (
    getWfrpCharacteristicRollExpression(firstFormula) ===
    getWfrpCharacteristicRollExpression(secondFormula)
  );
}

function normalizeWfrpCharacteristicRollExpression(expression: string): string {
  return expression.replaceAll(/\s+/g, "").toLocaleLowerCase();
}
