import type {
  SpeciesBuilderItemReferenceType,
  SpeciesBuilderLinkedItemName,
  SpeciesBuilderTalentGrant,
} from "../../types/species-builder/species-builder";

import { isRecord } from "../../shared/object-readers";
import { normalizeLinkedItemName } from "./replacement-row-normalization";

export function normalizeLinkedItemNames(
  value: unknown,
  itemType: SpeciesBuilderItemReferenceType,
): SpeciesBuilderLinkedItemName[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }

  const rows = value.flatMap((entry) => {
    const normalized = normalizeLinkedItemName(entry, itemType);

    return normalized.name ? [normalized] : [];
  });

  return rows.length > 0 ? rows : undefined;
}

export function normalizeLinkedTalentGrants(
  value: unknown,
): SpeciesBuilderTalentGrant[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }

  const grants = value.flatMap((entry) => {
    if (!isRecord(entry) || !Array.isArray(entry["choices"])) {
      return [];
    }

    const choices = entry["choices"].flatMap((choice) => {
      const normalized = normalizeLinkedItemName(choice, "talent");

      return normalized.name ? [normalized] : [];
    });

    return choices.length > 0 ? [{ choices }] : [];
  });

  return grants.length > 0 ? grants : undefined;
}
