import type { NpcBuilderApplicationDrop } from "../../../../types/npc-builder";

import { assertFoundryItem } from "../../../foundry/document-guards";
import { parseDropData } from "../../../foundry/drop-data";
import { readDroppedAdvancement } from "./advancements";
import { resolveActorDrop } from "./actors";
import { resolveCareerDrop } from "./careers";
import { resolveSpellDrop } from "./magic";
import { resolveTraitDrop } from "./traits";
import { getTrappingItemTypes, resolveTrappingDrop } from "./trappings";

export async function resolveApplicationDrop(data: string): Promise<NpcBuilderApplicationDrop> {
  const dropData = parseDropData(data);

  if (dropData.type === "Actor") {
    return {
      actor: await resolveActorDrop(data),
      kind: "actor",
    };
  }

  if (dropData.type !== "Item" || !dropData.uuid) {
    throw new Error("Drop a Foundry Actor or WFRP Item.");
  }

  const item = assertFoundryItem(await fromUuid(dropData.uuid), "Drop a Foundry Item.");

  if (item.type === "career") {
    return {
      career: await resolveCareerDrop(data),
      kind: "career",
    };
  }

  if (item.type === "skill" || item.type === "talent") {
    return {
      advancement: readDroppedAdvancement(item),
      kind: "advancement",
    };
  }

  if (item.type === "trait") {
    return {
      kind: "trait",
      trait: await resolveTraitDrop(data),
    };
  }

  if (item.type === "spell") {
    return {
      kind: "spell",
      spell: await resolveSpellDrop(data),
    };
  }

  if (getTrappingItemTypes().includes(item.type)) {
    return {
      kind: "trapping",
      trapping: await resolveTrappingDrop(data),
    };
  }

  throw new Error("Drop an Actor, Career, Skill, Talent, Trait, Trapping, or Spell Item.");
}
