import { MAX_ENTRIES_LIMIT } from "./constants";
import { clampInteger, isObject, normalizeName } from "./utils";

type PathToken =
  | {
      args: string[];
      name: string;
      type: "method";
    }
  | {
      index: number | string;
      type: "index";
    }
  | {
      key: string;
      type: "property";
    };

interface ResolvedPath {
  root: string;
  tokens: PathToken[];
}

export function resolveFoundryPath(path: string): unknown {
  const parsed = parsePath(path);
  let current = readProperty(globalThis, parsed.root);

  for (const token of parsed.tokens) {
    if (token.type === "property") {
      current = readProperty(current, token.key);
      continue;
    }

    if (token.type === "index") {
      current = readProperty(current, String(token.index));
      continue;
    }

    current = applyMethod(current, token.name, token.args);
  }

  return current;
}

export function readProperty(source: unknown, key: string): unknown {
  if (!isObject(source) && typeof source !== "function") {
    return undefined;
  }

  try {
    return (source as Record<string, unknown>)[key];
  } catch {
    return undefined;
  }
}

function applyMethod(source: unknown, name: string, args: string[]): unknown {
  if (name === "at") {
    const index = Number(args[0] ?? 0);
    const safeIndex = Number.isFinite(index) ? index : 0;
    const list = toArrayLike(source);

    return list.at(safeIndex);
  }

  if (name === "findByName") {
    const target = normalizeName(args[0] ?? "");
    const list = toArrayLike(source);

    return list.find((entry) => normalizeName(readProperty(entry, "name")) === target);
  }

  if (name === "findByType") {
    const target = normalizeName(args[0] ?? "");
    const list = toArrayLike(source);

    return list.find((entry) => normalizeName(readProperty(entry, "type")) === target);
  }

  if (name === "get") {
    const key = args[0] ?? "";

    if (source instanceof Map) {
      return source.get(key);
    }

    const getter = readProperty(source, "get");

    if (typeof getter === "function") {
      return getter.call(source, key);
    }
  }

  if (name === "sample") {
    const count = clampInteger(args[0], 3, MAX_ENTRIES_LIMIT);

    return toArrayLike(source).slice(0, count);
  }

  throw new Error(`Unsupported path method "${name}".`);
}

function parseArguments(source: string): string[] {
  if (!source.trim()) {
    return [];
  }

  return source
    .split(",")
    .map((argument) => parseLiteral(argument.trim()))
    .map(String);
}

function parseIndex(source: string): number | string {
  const trimmed = source.trim();

  if (/^-?\d+$/.test(trimmed)) {
    return Number(trimmed);
  }

  return parseLiteral(trimmed);
}

function parseLiteral(source: string): string {
  const quoted = /^["'](?<value>.*)["']$/.exec(source);

  if (quoted?.groups) {
    return quoted.groups["value"] ?? "";
  }

  return source;
}

function parsePath(path: string): ResolvedPath {
  const rootMatch = /^(?<root>[$A-Z_a-z][\w$]*)/.exec(path.trim());

  if (!rootMatch?.groups) {
    throw new Error(`Debug path "${path}" does not start with a root name.`);
  }

  const root = rootMatch.groups["root"];

  if (!root) {
    throw new Error(`Debug path "${path}" does not start with a root name.`);
  }

  const tokens: PathToken[] = [];
  let remaining = path.trim().slice(root.length);

  while (remaining) {
    // The probe language is intentionally tiny: dot properties, bracket
    // indexes, and a handful of whitelisted method helpers from applyMethod.
    const methodMatch = /^\.(?<name>[$A-Z_a-z][\w$]*)\((?<args>[^)]*)\)/.exec(remaining);

    if (methodMatch?.groups) {
      const name = methodMatch.groups["name"];

      if (!name) {
        throw new Error(`Could not parse debug path near "${remaining}".`);
      }

      tokens.push({
        args: parseArguments(methodMatch.groups["args"] ?? ""),
        name,
        type: "method",
      });
      remaining = remaining.slice(methodMatch[0].length);
      continue;
    }

    const propertyMatch = /^\.(?<key>[$A-Z_a-z][\w$]*)/.exec(remaining);

    if (propertyMatch?.groups) {
      const key = propertyMatch.groups["key"];

      if (!key) {
        throw new Error(`Could not parse debug path near "${remaining}".`);
      }

      tokens.push({
        key,
        type: "property",
      });
      remaining = remaining.slice(propertyMatch[0].length);
      continue;
    }

    const indexMatch = /^\[(?<index>[^\]]+)]/.exec(remaining);

    if (indexMatch?.groups) {
      const index = indexMatch.groups["index"];

      if (!index) {
        throw new Error(`Could not parse debug path near "${remaining}".`);
      }

      tokens.push({
        index: parseIndex(index),
        type: "index",
      });
      remaining = remaining.slice(indexMatch[0].length);
      continue;
    }

    throw new Error(`Could not parse debug path near "${remaining}".`);
  }

  return { root, tokens };
}

function toArrayLike(source: unknown): unknown[] {
  if (Array.isArray(source)) {
    return source;
  }

  const contents = readProperty(source, "contents");

  if (Array.isArray(contents)) {
    return contents;
  }

  return [];
}
