import type { NpcCareerQueueEntry, NpcCareerSummary } from "../../../../types/npc-builder";

import { normalizeQuantity } from "../../../../functions/npc-builder/draft-helpers";
import { setObjectPath } from "../../../../shared/object-readers";
import { assertFoundryItemType } from "../../../foundry/document-guards";
import { parseDropData } from "../../../foundry/drop-data";
import { toCareerSummary } from "../../../wfrp4e/career-summary";

export async function resolveCareerDrop(data: string): Promise<NpcCareerSummary> {
  const dropData = parseDropData(data);

  if (dropData.type !== "Item" || !dropData.uuid) {
    throw new Error("Drop a WFRP Career item here.");
  }

  return toCareerSummary(
    assertFoundryItemType(await fromUuid(dropData.uuid), "career", "Drop a WFRP Career item here."),
  );
}

export async function prepareCompletedCareerSources(
  careers: NpcCareerQueueEntry[],
): Promise<FoundryItemSource[]> {
  const sources: FoundryItemSource[] = [];

  for (const career of careers) {
    const item = assertFoundryItemType(
      await fromUuid(career.uuid),
      "career",
      `Career “${career.name}” is no longer available.`,
    );

    for (let occurrence = 0; occurrence < normalizeQuantity(career.quantity); occurrence += 1) {
      const source = item.toObject();

      delete source._id;
      setObjectPath(source, ["system", "complete", "value"], true);
      setObjectPath(source, ["system", "current", "value"], false);
      sources.push(source);
    }
  }

  return sources;
}

export async function embedCompletedCareers(
  actor: FoundryActorDocument,
  sources: FoundryItemSource[],
): Promise<void> {
  if (sources.length) {
    await actor.createEmbeddedDocuments("Item", sources);
  }
}
