<script setup lang="ts">
import type { NpcSpellDraftEntry } from "../../../../../types/npc-builder";

import DocumentDrop from "../../../../components/DocumentDrop.vue";
import NpcBuilderSection from "../NpcBuilderSection.vue";
import { getSpellSourceLabel } from "./labels";

defineProps<{
  ambiguousGrantCount: number;
  errorMessage: string;
  isLoadingSpells: boolean;
  resolvedGrantCount: number;
  selectedSpellCount: number;
  spells: NpcSpellDraftEntry[];
}>();

const emit = defineEmits<{
  refreshSpells: [];
  removeCustomSpell: [key: string];
  spellDrop: [data: string];
  spellSelectedChange: [spell: NpcSpellDraftEntry, event: Event];
}>();
</script>

<template>
  <NpcBuilderSection
    description="Select detected Lore spells or drop specific Spell Items."
    number="2"
    title="Spells"
  >
    <DocumentDrop
      description="Add a specific Spell item regardless of detected Lores."
      title="Drop Spell Items"
      @drop-data="emit('spellDrop', $event)"
    />

    <div class="dui-card-actions">
      <button
        class="dui-btn dui-btn-sm"
        :disabled="isLoadingSpells || !resolvedGrantCount"
        type="button"
        @click="emit('refreshSpells')"
      >
        {{ isLoadingSpells ? "Finding spells..." : "Refresh Spells" }}
      </button>
      <span>{{ selectedSpellCount }} selected / {{ spells.length }} found</span>
    </div>

    <p v-if="errorMessage" class="dui-alert dui-alert-error" role="alert">
      {{ errorMessage }}
    </p>

    <p v-if="ambiguousGrantCount" class="dui-alert dui-alert-error" role="alert">
      {{ ambiguousGrantCount }} magic grant{{ ambiguousGrantCount === 1 ? "" : "s" }}
      still need Lore resolution. You can still drop specific spells for now.
    </p>

    <ul v-if="spells.length" class="dui-list">
      <li v-for="spell in spells" :key="spell.key" class="dui-list-row">
        <input
          :aria-label="`Use ${spell.name}`"
          class="dui-checkbox dui-checkbox-sm"
          :checked="spell.selected"
          type="checkbox"
          @change="emit('spellSelectedChange', spell, $event)"
        />
        <div class="dui-list-col-grow">
          <div v-if="spell.img" class="dui-avatar">
            <div><img :src="spell.img" alt="" /></div>
          </div>
          <strong>{{ spell.name }}</strong>
          <span>{{ spell.loreName || "Unknown Lore" }} · {{ getSpellSourceLabel(spell) }}</span>
        </div>
        <button
          v-if="spell.source === 'custom'"
          class="dui-btn dui-btn-sm"
          type="button"
          @click="emit('removeCustomSpell', spell.key)"
        >
          Remove
        </button>
      </li>
    </ul>

    <p v-else class="dui-alert">
      No matching spells found yet. Drop specific spells here, or resolve a non-ambiguous magic
      Lore.
    </p>
  </NpcBuilderSection>
</template>
