import type {
  SpeciesBuilderCareerTableDefinition,
  SpeciesBuilderCareerTableRow,
} from "../../types/species-builder/species-builder";

import { assignIfPresent } from "../../shared/assign-if-present";
import { isRecord } from "../../shared/object-readers";

export function normalizeCareerTable(
  value: unknown,
): SpeciesBuilderCareerTableDefinition | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const rows =
    normalizeCareerTableRows(value["rows"]) ?? careerRowsFromLegacyNames(value["careers"]);

  return rows ? { rows } : undefined;
}

function normalizeCareerTableRows(value: unknown): SpeciesBuilderCareerTableRow[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }

  const rows = value.flatMap((entry) => {
    if (!isRecord(entry)) {
      return [];
    }

    const name = normalizeString(entry["name"]);

    if (!name) {
      return [];
    }

    const row: SpeciesBuilderCareerTableRow = { name };

    assignIfPresent(row, "journalUuid", normalizeString(entry["journalUuid"]));

    return [row];
  });

  return rows.length > 0 ? rows : undefined;
}

function careerRowsFromLegacyNames(value: unknown): SpeciesBuilderCareerTableRow[] | undefined {
  const careers = normalizeStringArray(value);

  return careers?.map((name) => ({ name }));
}

function normalizeStringArray(value: unknown): string[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }

  const entries = value.flatMap((entry) => {
    const normalized = normalizeString(entry);

    return normalized ? [normalized] : [];
  });

  return entries.length > 0 ? entries : undefined;
}

function normalizeString(value: unknown): string | undefined {
  if (typeof value !== "string") {
    return undefined;
  }

  const trimmed = value.trim();

  return trimmed || undefined;
}
