import type { NpcAdvancementSourceSummary } from "../../../types/npc-builder";

export function createExtraTimeSources(
  careerName: string,
  count: number,
): NpcAdvancementSourceSummary[] {
  if (count <= 0) {
    return [];
  }

  return [
    {
      count,
      kind: "career",
      label: `${careerName} extra time`,
    },
  ];
}

export function limitSourcesToCount(
  sources: NpcAdvancementSourceSummary[],
  count: number,
): NpcAdvancementSourceSummary[] {
  let remainingCount = Math.max(0, Math.floor(count));
  const limitedSources: NpcAdvancementSourceSummary[] = [];

  for (const source of sources) {
    if (remainingCount <= 0) {
      break;
    }

    const sourceCount = Math.min(source.count, remainingCount);

    if (sourceCount > 0) {
      limitedSources.push({
        ...source,
        count: sourceCount,
      });
    }

    remainingCount -= sourceCount;
  }

  return limitedSources;
}
