import type { NpcAdvancementDraftEntry } from "../../../../../types/npc-builder";

import { getAmbiguousSkillGrant } from "../../../../../functions/npc-builder/skill-specialization";
import { calculateAdvancementXp } from "../../../../../functions/npc-builder/xp-cost";

export function formatSources(entry: NpcAdvancementDraftEntry): string {
  const manualDelta = entry.current - entry.careerValue;
  const sources = [...entry.sources]
    .sort((left, right) => {
      return getSourceOrder(left.kind) - getSourceOrder(right.kind);
    })
    .map((source) => formatSource(source));

  if (manualDelta !== 0) {
    sources.push(`Manual ${formatSignedNumber(manualDelta)}`);
  }

  if (!sources.length) {
    return entry.includedFromBase ? "Base actor" : "-";
  }

  return sources.join(", ");
}

function formatSource(source: NpcAdvancementDraftEntry["sources"][number]): string {
  if (source.kind === "custom" && source.count === 0) {
    return source.label;
  }

  return `${source.label} ${formatSignedNumber(source.count)}`;
}

export function needsSkillSpecialization(name: string): boolean {
  return getAmbiguousSkillGrant(name) !== null;
}

export function getAdvancementStep(entry: NpcAdvancementDraftEntry): number {
  return entry.kind === "talent" ? 1 : 5;
}

export function getAdvancementTotal(entry: NpcAdvancementDraftEntry): number {
  return Math.max(entry.minimumTotal, entry.baseValue + entry.current);
}

export function getTalentRanks(entry: NpcAdvancementDraftEntry): number {
  return getAdvancementTotal(entry);
}

export function getTalentMaximum(entry: NpcAdvancementDraftEntry): string {
  return entry.talentMaximumLabel ?? "Unknown";
}

export function isTalentOverMaximum(entry: NpcAdvancementDraftEntry): boolean {
  const maximum = entry.talentMaximumValue;

  return typeof maximum === "number" && getTalentRanks(entry) > maximum;
}

export function canMaximizeTalent(entry: NpcAdvancementDraftEntry): boolean {
  const maximum = entry.talentMaximumValue;

  return typeof maximum === "number" && getTalentRanks(entry) < maximum;
}

export function getAdvancementXp(entry: NpcAdvancementDraftEntry): number {
  return calculateAdvancementXp(entry);
}

function getSourceOrder(sourceKind: NpcAdvancementDraftEntry["sources"][number]["kind"]): number {
  if (sourceKind === "characteristic") {
    return 0;
  }

  if (sourceKind === "career") {
    return 1;
  }

  return 2;
}

function formatSignedNumber(value: number): string {
  return value > 0 ? `+${value}` : `${value}`;
}
