<script setup lang="ts">
import { useId } from "vue";
import { EFFECT_BUILDERS } from "../../../functions/effect-builders/catalogue";
import { useEffectBuilderStore } from "../../../state/effect-builders";
import type { EffectBuilderBridge, EffectBuilderKind } from "../../../types/effect-builders";
import type { GrantItemReference } from "../../../types/item-grants";
import ApplicationShell from "../../components/ApplicationShell.vue";
import DocumentDrop from "../../components/DocumentDrop.vue";
import ChoiceOptions from "./ChoiceOptions.vue";
import GrantOptions from "./GrantOptions.vue";
import SourceItems from "./SourceItems.vue";
import WoundFormula from "./WoundFormula.vue";
const props = defineProps<{
  id: string;
  kind: EffectBuilderKind;
  destination: GrantItemReference | null;
  bridge: EffectBuilderBridge;
  close: () => void;
}>();
const store = useEffectBuilderStore(props.id);
store.configure(props.kind, props.bridge, props.destination);
const fieldId = `${props.id}-${useId()}`;
const builder = EFFECT_BUILDERS.find((entry) => entry.kind === props.kind)!;
</script>

<template>
  <ApplicationShell :title="`${builder.title} Effect Builder`" :description="builder.description">
    <div v-if="store.error" role="alert" class="dui-alert dui-alert-error">{{ store.error }}</div>
    <div v-if="store.message" role="status" class="dui-alert dui-alert-success">
      {{ store.message }}
    </div>
    <fieldset class="dui-fieldset" :disabled="store.busy || store.created">
      <DocumentDrop
        title="Destination Item"
        description="Drop the Item that will receive this effect."
        :documents="store.destination ? [store.destination] : []"
        show-documents
        variant="compact"
        @drop-data="store.dropDestination"
      />
      <label :for="`${fieldId}-name`" class="dui-label">Effect name</label>
      <input
        :id="`${fieldId}-name`"
        v-model="store.draft.name"
        aria-label="Effect name"
        class="dui-input app:w-full"
      />
      <WoundFormula v-if="kind === 'wounds'" :id="id" />
      <SourceItems
        v-else-if="kind === 'grant'"
        title="Items to grant"
        :items="store.draft.items"
        @drop-data="store.dropItem($event)"
        @remove="store.removeItem($event)"
      />
      <fieldset v-else-if="kind === 'random'" class="dui-fieldset">
        <legend class="dui-fieldset-legend">Random selection</legend>
        <DocumentDrop
          title="Grant RollTable"
          description="Use document results pointing to Items or nested RollTables."
          :documents="store.draft.table ? [store.draft.table] : []"
          show-documents
          variant="compact"
          @drop-data="store.dropTable"
        />
        <label :for="`${fieldId}-rolls`" class="dui-label">Number of rolls</label>
        <input
          :id="`${fieldId}-rolls`"
          v-model.number="store.draft.count"
          aria-label="Number of rolls"
          type="number"
          min="1"
          max="100"
          step="1"
          class="dui-input"
        />
        <p>
          Rolls leave results available for future rolls. An Item may be granted more than once.
        </p>
      </fieldset>
      <ChoiceOptions v-else :id="id" />
      <GrantOptions v-if="kind !== 'wounds'" :id="id" />
    </fieldset>
    <ul
      v-if="!store.created && store.problems.length"
      class="dui-list"
      aria-label="To finish this effect"
    >
      <li v-for="problem in store.problems" :key="problem">{{ problem }}</li>
    </ul>
    <div class="app:flex app:flex-wrap app:gap-2">
      <button
        v-if="!store.created"
        type="button"
        class="dui-btn dui-btn-primary"
        :disabled="!store.ready"
        @click="store.create"
      >
        {{ store.busy ? "Working…" : "Add effect to Item" }}
      </button>
      <button v-if="store.destination" type="button" class="dui-btn" @click="store.openDestination">
        Open destination Item
      </button>
      <button type="button" class="dui-btn dui-btn-ghost" :disabled="store.busy" @click="close">
        {{ store.created ? "Done" : "Cancel" }}
      </button>
    </div>
  </ApplicationShell>
</template>
