import type { SpeciesItemSheetBridge } from "../../../types/species-builder/species-item";

export function speciesNotesEditors(item: FoundryItemDocument) {
  const editors = new Map<string, foundry.applications.elements.HTMLProseMirrorElement>();
  const mount: SpeciesItemSheetBridge["mountNotes"] = (host, field, value, editable, changed) => {
    let editor: foundry.applications.elements.HTMLProseMirrorElement | undefined;
    let disposed = false;
    const update = () => {
      if (editor) changed(editor.value);
    };
    const mountEditor = async () => {
      const enriched = await foundry.applications.ux.TextEditor.implementation.enrichHTML(value, {
        secrets: game.user?.isGM === true,
        relativeTo: item,
      });
      // Resolving compendium links can outlast a sheet reload or close.
      if (disposed) return;
      editor = new foundry.applications.elements.HTMLProseMirrorElement({
        value,
        enriched,
        toggled: true,
      });
      editor.name = `system.${field}.value`;
      editor.disabled = !editable;
      editor.addEventListener("input", update);
      editor.addEventListener("change", update);
      editors.set(field, editor);
      host.append(editor);
    };
    void mountEditor().catch((error: unknown) => {
      if (!disposed) ui.notifications?.error(`Could not display Species notes: ${String(error)}`);
    });
    return () => {
      disposed = true;
      if (!editor) return;
      editor.removeEventListener("input", update);
      editor.removeEventListener("change", update);
      editor.remove();
      if (editors.get(field) === editor) editors.delete(field);
    };
  };
  return {
    mount,
    edit(field: string) {
      editors.get(field)?.setAttribute("open", "");
    },
    flush() {
      // Foundry's toggled editor throws when save() is called before it has been opened.
      for (const editor of editors.values()) {
        if (editor.classList.contains("active")) editor.save();
      }
    },
  };
}
