<script setup lang="ts">
import type { NpcCareerQueueEntry } from "../../../../../types/npc-builder";

import NpcBuilderSection from "../NpcBuilderSection.vue";
import { summarizeCareerGrants, summarizeGrantNames, toInitials } from "./labels";

const props = defineProps<{
  careers: NpcCareerQueueEntry[];
  draggedCareerIndex: null | number;
  dragOverCareerIndex: null | number;
}>();

const emit = defineEmits<{
  careerDragEnd: [];
  careerDragEnter: [index: number];
  careerDragOver: [index: number, event: DragEvent];
  careerDragStart: [index: number, event: DragEvent];
  careerDropOnRow: [index: number, event: DragEvent];
  careerQuantityInput: [index: number, event: Event];
  moveCareer: [index: number, direction: -1 | 1];
  removeCareer: [index: number];
}>();

function getDropPlacement(index: number): "after" | "before" | null {
  if (
    props.draggedCareerIndex === null ||
    props.draggedCareerIndex === index ||
    props.dragOverCareerIndex !== index
  ) {
    return null;
  }

  return props.draggedCareerIndex < index ? "after" : "before";
}
</script>

<template>
  <NpcBuilderSection
    description="Careers are applied in this order. Drag rows or use the buttons to reorder them."
    number="2"
    title="Career Queue"
  >
    <ol v-if="careers.length" class="dui-list app:gap-1">
      <li
        v-for="(career, index) in careers"
        :key="career.uuid"
        :class="[
          'dui-list-row app:grid-cols-[auto_auto_minmax(0,1fr)_auto] app:items-center app:gap-2 app:rounded-md app:px-2 app:py-2',
          {
            'app:border-t-2 app:border-dashed app:border-info':
              getDropPlacement(index) === 'before',
            'app:border-b-2 app:border-dashed app:border-info': getDropPlacement(index) === 'after',
            'app:opacity-60': draggedCareerIndex === index,
          },
        ]"
        @dragenter.prevent.stop="emit('careerDragEnter', index)"
        @dragover="emit('careerDragOver', index, $event)"
        @drop="emit('careerDropOnRow', index, $event)"
      >
        <span
          aria-hidden="true"
          :class="[
            'dui-badge dui-badge-ghost dui-badge-sm app:cursor-grab',
            { 'app:cursor-grabbing': draggedCareerIndex === index },
          ]"
          draggable="true"
          title="Drag to reorder"
          @dragend="emit('careerDragEnd')"
          @dragstart="emit('careerDragStart', index, $event)"
        >
          Drag
        </span>
        <div v-if="career.img" class="dui-avatar">
          <div class="app:size-10 app:rounded-md">
            <img
              :src="career.img"
              alt=""
              class="app:h-full app:w-full app:object-cover"
              height="40"
              width="40"
            />
          </div>
        </div>
        <span v-else class="dui-badge dui-badge-sm">{{ toInitials(career.name) }}</span>
        <div class="dui-list-col-grow app:min-w-0">
          <div class="app:flex app:min-w-0 app:flex-wrap app:items-center app:gap-1">
            <strong class="app:truncate">{{ career.name }}</strong>
            <span v-if="draggedCareerIndex === index" class="dui-badge dui-badge-info dui-badge-xs">
              Dragging
            </span>
            <span v-else-if="getDropPlacement(index)" class="dui-badge dui-badge-info dui-badge-xs">
              Place {{ getDropPlacement(index) }}
            </span>
          </div>
          <div class="app:flex app:min-w-0 app:items-center app:gap-2 app:text-xs">
            <span class="app:shrink-0">
              {{ career.careerGroup || "Career" }}
              <template v-if="career.level !== null"> level {{ career.level }}</template>
            </span>
            <small
              class="dui-badge dui-badge-ghost dui-badge-sm app:min-w-0 app:truncate"
              :title="
                [
                  `Characteristics: ${summarizeGrantNames(career.grants.characteristics)}`,
                  `Skills: ${summarizeGrantNames(career.grants.skills)}`,
                  `Talents: ${summarizeGrantNames(career.grants.talents)}`,
                  `Trappings: ${summarizeGrantNames(career.grants.trappings)}`,
                ].join('\n')
              "
            >
              {{ summarizeCareerGrants(career) }}
            </small>
          </div>
        </div>
        <div class="app:flex app:items-center app:justify-end app:gap-1">
          <label class="app:flex app:items-center app:gap-1 app:text-xs">
            Qty
            <input
              class="dui-input dui-input-xs app:w-14"
              :value="career.quantity"
              min="1"
              type="number"
              @input="emit('careerQuantityInput', index, $event)"
            />
          </label>
          <div class="dui-join">
            <button
              class="dui-join-item dui-btn dui-btn-xs"
              :disabled="index === 0"
              title="Move career earlier"
              type="button"
              @click="emit('moveCareer', index, -1)"
            >
              Up
            </button>
            <button
              class="dui-join-item dui-btn dui-btn-xs"
              :disabled="index === careers.length - 1"
              title="Move career later"
              type="button"
              @click="emit('moveCareer', index, 1)"
            >
              Down
            </button>
            <button
              class="dui-join-item dui-btn dui-btn-xs"
              type="button"
              @click="emit('removeCareer', index)"
            >
              Remove
            </button>
          </div>
        </div>
      </li>
    </ol>

    <p v-else class="dui-alert">No careers queued yet.</p>
  </NpcBuilderSection>
</template>
