import type {
  PortraitCandidate,
  PortraitSearchProgressHandler,
  PortraitSearchRequest,
} from "../../../types/portrait-gallery";
import type { PortraitSearchState } from "./types";

import { emitPortraitSearchProgress } from "./candidate-utils";
import { collectDigDownPortraitCandidates } from "./dig-down";
import {
  collectCompendiumPortraitCandidates,
  collectWorldDocumentPortraitCandidates,
} from "./documents";
import { collectPriorityFolderPortraitCandidates } from "./priority-folders";

export { getPortraitSearchAvailability } from "./dig-down";
export { filterExcludedPortraitCandidates } from "./exclusions";

export async function listFoundryPortraitCandidates(
  request: PortraitSearchRequest,
  onProgress?: PortraitSearchProgressHandler,
): Promise<PortraitCandidate[]> {
  if (!request.searchTerms.length) {
    return [];
  }

  const state: PortraitSearchState = {
    candidates: [],
    maxDirectoryBudget: 0,
    mustExcludeTerms: request.mustExcludeTerms,
    mustIncludeTerms: request.mustIncludeTerms,
    searchTerms: request.searchTerms,
    seenPaths: new Set(),
    visitedDirectories: 0,
  };

  await collectPriorityFolderPortraitCandidates(state, request.priorityFolderPaths, onProgress);

  if (request.includeCompendiumAssets) {
    await collectCompendiumPortraitCandidates(state, onProgress);
    collectWorldDocumentPortraitCandidates(state, onProgress);
  }

  if (request.includeFilePickerAssets) {
    collectDigDownPortraitCandidates(state, onProgress);
  }

  emitPortraitSearchProgress(onProgress, state, {
    currentLocation: "Portrait search complete",
    maxDirectories: state.maxDirectoryBudget,
    phase: "ready",
  });

  return state.candidates;
}
