import type { CustomizerModuleApi } from "../../types/module/customizer-module-api";

import {
  listNpcAutoAdvanceStrategies,
  registerNpcAutoAdvanceStrategy,
} from "../../functions/npc-builder/auto-advance";
import { DaisyExampleApplication } from "../apps/daisy-example/DaisyExampleApplication";
import { openActorPortraitGallery } from "../apps/actor-portrait-gallery/open";
import { NpcBuilderApplication } from "../apps/npc-builder/NpcBuilderApplication";
import { estimateNpcXp } from "../apps/npc-builder/estimated-xp";
import {
  openEffectBuilders,
  openWoundFormulaEffectBuilder,
  openItemGrantEffectBuilder,
  openRandomItemEffectBuilder,
  openItemChoiceEffectBuilder,
} from "../apps/effect-builders/open";
import { createBuiltEffect } from "../apps/effect-builders/bridge";
import { syncSpeciesBuilderCareerTables } from "../apps/species-builder/career-tables";
import { WorkbenchApplication } from "../apps/workbench/WorkbenchApplication";
import { openSpeciesTableEditor } from "../apps/species-table/SpeciesTableApplication";
import { speciesTableBridge } from "../apps/species-table/bridge";
import {
  clearDebugShapeProbes,
  getDebugShapeProbes,
  inspectFoundryPath,
  setDebugShapeProbes,
} from "../debug/shape-inspector";

export function createModuleApi(): CustomizerModuleApi {
  return {
    clearDebugShapeProbes,
    estimateNpcXp,
    getDebugShapeProbes,
    inspectPath: inspectFoundryPath,
    listNpcAutoAdvanceStrategies,
    openActorPortraitGallery,
    async openDaisyExample() {
      await new DaisyExampleApplication().render(true);
    },
    async openNpcBuilder() {
      await new NpcBuilderApplication().render(true);
    },
    createBuiltEffect,
    openEffectBuilders,
    openWoundFormulaEffectBuilder,
    openItemGrantEffectBuilder,
    openRandomItemEffectBuilder,
    openItemChoiceEffectBuilder,
    openSpeciesTableEditor,
    speciesTable: speciesTableBridge,
    async openWorkbench() {
      await new WorkbenchApplication().render(true);
    },
    rebuildSpeciesCareerTables: async () =>
      await syncSpeciesBuilderCareerTables(undefined, { force: true }),
    registerNpcAutoAdvanceStrategy,
    setDebugShapeProbes,
  };
}
