import type {
  SpeciesBuilderCareerTableRow,
  SpeciesBuilderDefinition,
  SpeciesBuilderSettings,
  SpeciesBuilderSubspeciesDefinition,
} from "../../types/species-builder/species-builder";

import { isRecord, readUnknownPath } from "../../shared/object-readers";
import { buildSpeciesDefinitionPlans } from "./definition-plans";
import {
  COMBAT_FAMILIAR_CAREER_UUID,
  createFamiliarCorrectionDefinition,
  FAMILIAR_NAME,
  SPELL_FAMILIAR_CAREER_UUID,
} from "./familiar-correction";
import { getSpeciesCareerTableColumn, getSubspeciesCareerTableColumn } from "./species-config";

export { COMBAT_FAMILIAR_CAREER_UUID, SPELL_FAMILIAR_CAREER_UUID } from "./familiar-correction";

export const GENERATED_CAREER_TABLE_FLAG = "generatedSpeciesCareerTable";
export const GENERATED_CAREER_TABLE_SCHEMA_VERSION = 1;
export const FALLBACK_CAREER_JOURNAL_UUID =
  "Compendium.wfrp4e-core.journals.JournalEntry.wczCPcuHT4VQDLpL";
export const ANIMAL_FAMILIAR_CAREER_JOURNAL_UUID =
  "Compendium.wfrp4e-archives3.journals.JournalEntry.jnN5JqDCI8T1epzs.JournalEntryPage.yByG9MMGFjml7sRQ";

export interface SpeciesCareerTableSpec {
  column: string;
  name: string;
  rows: SpeciesBuilderCareerTableRow[];
  sourceFormula?: string;
  speciesKey: string;
  subspeciesKey?: string;
}

export interface CareerTableSourceInput {
  fallbackJournalUuid?: string;
  flagScope: string;
  speciesItemBridge?: boolean;
  spec: SpeciesCareerTableSpec;
}

export interface GeneratedCareerTableIdentity {
  speciesKey: string;
  subspeciesKey: string;
}

export function buildSpeciesCareerTableSpecs(
  settings: SpeciesBuilderSettings,
  runtimeParents: SpeciesBuilderDefinition[] = [],
): SpeciesCareerTableSpec[] {
  const authoredSpecs = buildSpeciesDefinitionPlans(settings, runtimeParents).flatMap((plan) => [
    ...(plan.emitBaseDefinition ? buildSpeciesTableSpecs(plan.definition) : []),
    ...buildSubspeciesTableSpecs(plan.definition, plan.subspecies),
  ]);

  return [
    ...authoredSpecs,
    ...buildAnimalFamiliarCareerSpec(settings, runtimeParents),
    ...buildFamiliarCareerSpecs(settings, runtimeParents),
  ];
}

export function buildSpeciesCareerTableSource({
  fallbackJournalUuid = FALLBACK_CAREER_JOURNAL_UUID,
  flagScope,
  speciesItemBridge,
  spec,
}: CareerTableSourceInput): Record<string, unknown> {
  const identity: GeneratedCareerTableIdentity = {
    speciesKey: spec.speciesKey,
    subspeciesKey: spec.subspeciesKey ?? "",
  };
  const source: Record<string, unknown> = {
    displayRoll: true,
    flags: {
      wfrp4e: {
        column: spec.column,
        key: "career",
      },
      [flagScope]: {
        [GENERATED_CAREER_TABLE_FLAG]: identity,
      },
    },
    formula: spec.sourceFormula ?? `1d${spec.rows.length}`,
    img: "systems/wfrp4e/ui/buttons/d10.webp",
    name: spec.name,
    replacement: true,
    results: spec.rows.map((row, index) => ({
      description: careerDescription(row, fallbackJournalUuid),
      drawn: false,
      img: "icons/svg/d20-grey.svg",
      name: row.name,
      range: row.sourceRange ? [...row.sourceRange] : [index + 1, index + 1],
      type: "text",
      weight: row.sourceWeight ?? 1,
    })),
  };

  const generatedFlag = source["flags"] as Record<string, Record<string, unknown>>;
  generatedFlag[flagScope]![GENERATED_CAREER_TABLE_FLAG] = {
    ...identity,
    ...(speciesItemBridge ? { speciesItemBridge: true } : {}),
    fingerprint: fingerprintSpeciesCareerTableSource(source, flagScope),
    schemaVersion: GENERATED_CAREER_TABLE_SCHEMA_VERSION,
  };

  return source;
}

export function fingerprintSpeciesCareerTableSource(source: unknown, flagScope: string): string {
  const canonical = serializeSpeciesCareerTableSource(source, flagScope);
  let hash = 2166136261;

  for (let index = 0; index < canonical.length; index += 1) {
    hash ^= canonical.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }

  return (hash >>> 0).toString(16).padStart(8, "0");
}

export function serializeSpeciesCareerTableSource(source: unknown, flagScope: string): string {
  return JSON.stringify(canonicalCareerTableSource(source, flagScope));
}

export function fingerprintSpeciesCareerTableResult(source: Record<string, unknown>): string {
  return JSON.stringify(canonicalCareerTableResult(source));
}

function buildSpeciesTableSpecs(definition: SpeciesBuilderDefinition): SpeciesCareerTableSpec[] {
  if (!definition.careerTable?.rows.length) {
    return [];
  }

  return [
    {
      column: getSpeciesCareerTableColumn(definition),
      name: `Career - ${definition.name}`,
      ...definition.careerTable,
      speciesKey: definition.key,
    },
  ];
}

function buildAnimalFamiliarCareerSpec(
  settings: SpeciesBuilderSettings,
  runtimeParents: SpeciesBuilderDefinition[],
): SpeciesCareerTableSpec[] {
  if (!settings.correctExistingWfrpSpecies) {
    return [];
  }

  const animalFamiliar = runtimeParents.find(
    (definition) => definition.name.trim() === "Animal Familiar",
  );

  return animalFamiliar
    ? [
        {
          column: animalFamiliar.key,
          name: "Career - Animal Familiar",
          rows: [
            {
              journalUuid: ANIMAL_FAMILIAR_CAREER_JOURNAL_UUID,
              name: "Power Familiar",
            },
          ],
          speciesKey: animalFamiliar.key,
        },
      ]
    : [];
}

function buildFamiliarCareerSpecs(
  settings: SpeciesBuilderSettings,
  runtimeParents: SpeciesBuilderDefinition[],
): SpeciesCareerTableSpec[] {
  if (!settings.correctExistingWfrpSpecies) {
    return [];
  }

  const runtimeFamiliar = runtimeParents.find(
    (definition) => definition.name.trim() === FAMILIAR_NAME,
  );

  if (!runtimeFamiliar) {
    return [];
  }

  const familiar = createFamiliarCorrectionDefinition(runtimeFamiliar.key);

  return [
    ...buildSpeciesTableSpecs(familiar),
    ...buildSubspeciesTableSpecs(familiar, familiar.subspecies ?? []),
  ];
}

export function isFamiliarCorrectionCareerUuid(value: string | undefined): boolean {
  return value === COMBAT_FAMILIAR_CAREER_UUID || value === SPELL_FAMILIAR_CAREER_UUID;
}

function buildSubspeciesTableSpecs(
  definition: SpeciesBuilderDefinition,
  subspeciesDefinitions: SpeciesBuilderSubspeciesDefinition[],
): SpeciesCareerTableSpec[] {
  return subspeciesDefinitions.flatMap((subspecies) => {
    if (!subspecies.careerTable?.rows.length) {
      return [];
    }

    return [
      {
        column: getSubspeciesCareerTableColumn(definition, subspecies),
        name: `Career - ${definition.name} / ${subspecies.name}`,
        ...subspecies.careerTable,
        speciesKey: definition.key,
        subspeciesKey: subspecies.key,
      },
    ];
  });
}

function careerDescription(row: SpeciesBuilderCareerTableRow, fallbackJournalUuid: string): string {
  const journalUuid = row.journalUuid?.trim() || fallbackJournalUuid;

  return `@UUID[${journalUuid}]{${formatCareerLinkLabel(row.name)}}`;
}

function formatCareerLinkLabel(value: string): string {
  return value.replaceAll("{", "").replaceAll("}", "").trim();
}

function canonicalCareerTableSource(source: unknown, flagScope: string): unknown {
  const results = readUnknownPath(source, ["results"]);

  return {
    displayRoll: readUnknownPath(source, ["displayRoll"]),
    flags: {
      generated: {
        speciesKey: readUnknownPath(source, [
          "flags",
          flagScope,
          GENERATED_CAREER_TABLE_FLAG,
          "speciesKey",
        ]),
        subspeciesKey: readUnknownPath(source, [
          "flags",
          flagScope,
          GENERATED_CAREER_TABLE_FLAG,
          "subspeciesKey",
        ]),
      },
      wfrp4e: {
        column: readUnknownPath(source, ["flags", "wfrp4e", "column"]),
        key: readUnknownPath(source, ["flags", "wfrp4e", "key"]),
      },
    },
    formula: readUnknownPath(source, ["formula"]),
    img: readUnknownPath(source, ["img"]),
    name: readUnknownPath(source, ["name"]),
    replacement: readUnknownPath(source, ["replacement"]),
    results: Array.isArray(results) ? results.filter(isRecord).map(canonicalCareerTableResult) : [],
  };
}

function canonicalCareerTableResult(source: Record<string, unknown>): unknown {
  return {
    description: source["description"],
    drawn: source["drawn"],
    img: source["img"],
    name: source["name"],
    range: source["range"],
    type: source["type"],
    weight: source["weight"],
  };
}
