import type {
  SpeciesEffectSource,
  SpeciesItemRecord,
} from "../../../types/species-builder/species-item";

export const SPECIES_EFFECT_CARRIER_FLAG = "speciesEffectCarrier";

export function speciesEffectCarrierName(item: Pick<SpeciesItemRecord, "id">): string {
  // Current chargen looks Traits up by name. The Item ID avoids renames and display-name collisions.
  return `__Species Effects ${item.id}__`;
}

export function copySpeciesEffect(effect: SpeciesEffectSource): SpeciesEffectSource {
  const copy = structuredClone(effect);
  // A generated document has its own creation/update history; all authored effect data is retained.
  delete copy["_stats"];
  return copy;
}

export function buildSpeciesEffectCarrier(item: SpeciesItemRecord, flagScope: string) {
  return {
    type: "trait",
    name: speciesEffectCarrierName(item),
    img: item.img,
    effects: item.effects.map(copySpeciesEffect),
    system: {
      description: {
        value: `<p>Temporary species effects carrier for @UUID[${item.uuid}]. Edit the effects on the Species Item; this Trait is regenerated for legacy character creation.</p>`,
      },
    },
    flags: { [flagScope]: { [SPECIES_EFFECT_CARRIER_FLAG]: { speciesUuid: item.uuid } } },
  };
}
