export function summarizeCareerGrants(career: NpcCareerQueueEntry): string {
  return [
    `Ch ${career.grants.characteristics.length}`,
    `Sk ${career.grants.skills.length}`,
    `Ta ${career.grants.talents.length}`,
    `Tr ${career.grants.trappings.length}`,
  ].join(" / ");
}

export function summarizeGrantNames(values: string[]): string {
  const visible = values.slice(0, 3).join(", ");
  const remaining = values.length - 3;

  if (!values.length) {
    return "-";
  }

  return remaining > 0 ? `${visible}, +${remaining}` : visible;
}

export function toInitials(name: string): string {
  return name
    .split(/\s+/)
    .map((part) => part.at(0))
    .filter(Boolean)
    .slice(0, 2)
    .join("")
    .toLocaleUpperCase();
}
