import type { SpeciesBuilderSettings } from "../../types/species-builder/species-builder";
import { registerNpcBuilderActorDirectoryButton } from "../apps/npc-builder/register-actor-directory-button";
import { registerActorPortraitGallerySheetHooks } from "../apps/actor-portrait-gallery/register-actor-sheet-button";
import { registerNpcEstimatedXpSheetHooks } from "../apps/npc-builder/estimated-xp";
import { applySpeciesItemConfig } from "../apps/species-builder/apply-species-config";
import { syncSpeciesBuilderCareerTables } from "../apps/species-builder/career-tables";
import { registerSpeciesBuilderChargenSwapGuard } from "../apps/species-builder/chargen-roll-swap-guard";
import {
  captureRuntimeSpeciesConfig,
  finalizeRuntimeSpeciesConfig,
} from "../apps/species-builder/runtime-species";
import { registerSpeciesItemSheet } from "../apps/species-item/SpeciesItemApplication";
import { registerSpeciesItemModel } from "../apps/species-builder/items/model";
import {
  hasNativeSpeciesSupport,
  migrateSpeciesItemsToNative,
} from "../apps/species-builder/items/migration";
import { loadSpeciesItemSettings } from "../apps/species-builder/items/repository";
import { syncSpeciesEffectCarriers } from "../apps/species-builder/items/effect-carriers";
import { MODULE_ID, WFRP4E_SYSTEM_ID } from "../constants";
import { registerDebugShapeProbeHooks } from "../debug/shape-inspector";
import { logInfo, logWarning } from "../logging";
import { registerModuleMenus } from "../register-module-menus";
import { registerModuleSettings } from "../register-module-settings";
import { startCareerIndexing } from "../wfrp4e/career-index";
import { registerWfrpItemEffectDropHooks } from "../wfrp4e/item-effect-drops";
import { startSkillSpecializationIndexing } from "../wfrp4e/skill-specializations";
import { registerModuleApi } from "../api/register-module-api";

export function registerModuleHooks(): void {
  registerDebugShapeProbeHooks();

  Hooks.once("init", () => {
    logInfo(`${MODULE_ID} | Initializing`);
    registerModuleSettings();

    if (game.system.id === WFRP4E_SYSTEM_ID) {
      captureRuntimeSpeciesConfig();
      registerSpeciesItemModel();
      registerSpeciesItemSheet();
      registerActorPortraitGallerySheetHooks();
      registerNpcEstimatedXpSheetHooks();
      if (!hasNativeSpeciesSupport()) registerSpeciesBuilderChargenSwapGuard();
      registerWfrpItemEffectDropHooks();
    }

    registerModuleMenus();
    registerNpcBuilderActorDirectoryButton();
  });

  Hooks.once("ready", () => {
    if (game.system.id !== WFRP4E_SYSTEM_ID) {
      logWarning(
        `${MODULE_ID} | Loaded outside ${WFRP4E_SYSTEM_ID}; skipping module API registration.`,
      );
      return;
    }

    void completeWfrpReadyLifecycle();
  });
}

async function completeWfrpReadyLifecycle(): Promise<void> {
  // Let Foundry finish calling synchronous ready listeners before taking the final runtime snapshot.
  await Promise.resolve();

  let itemSettings: SpeciesBuilderSettings | undefined;
  try {
    await migrateSpeciesItemsToNative();
    await finalizeRuntimeSpeciesConfig([]);
    if (!hasNativeSpeciesSupport()) {
      itemSettings = await loadSpeciesItemSettings();
      await syncSpeciesEffectCarriers();
      await applySpeciesItemConfig(itemSettings);
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : "Unknown runtime adaptation error.";

    logWarning(`${MODULE_ID} | Runtime species catalog could not be prepared: ${message}`);
    ui.notifications?.warn?.(`Species Items could not be applied: ${message}`);
    itemSettings = undefined;
  }

  registerModuleApi();
  void startCareerIndexing();
  void startSkillSpecializationIndexing();
  if (
    itemSettings &&
    game.user?.isGM &&
    (!game.users?.activeGM || game.users.activeGM.id === game.user.id)
  ) {
    void syncSpeciesBuilderCareerTables(itemSettings).catch((error: unknown) =>
      logWarning(String(error)),
    );
  }
  logInfo(`${MODULE_ID} | Ready`);
}
