import type { NpcMountTraitContribution, NpcMountTraitSummary } from "../../../types/npc-builder";

const EXCLUDED_MOUNT_TRAIT_NAMES = new Set(["bestial", "skittish"]);

export function planMountTraitContributions(
  traits: NpcMountTraitSummary[],
): NpcMountTraitContribution[] {
  const hasSkittish = traits.some((trait) => isNamedTrait(trait, "skittish"));
  const hasWarTraining = traits.some((trait) => isTraitWithSpecification(trait, "trained", "war"));
  const weaponTraits = traits.filter((trait) => isNamedTrait(trait, "weapon"));
  const selectedWeaponUuid = selectStrongestWeaponUuid(weaponTraits);

  return traits.map((trait) => {
    const normalizedName = normalizeTraitName(trait.name);

    if (EXCLUDED_MOUNT_TRAIT_NAMES.has(normalizedName)) {
      return excludedContribution(trait, `${trait.name} is removed from combined mounts.`);
    }

    if (normalizedName === "weapon") {
      if (!hasWarTraining || hasSkittish) {
        return excludedContribution(
          trait,
          "Weapon requires Trained (War) and a mount that was not Skittish.",
        );
      }

      if (trait.uuid !== selectedWeaponUuid) {
        return excludedContribution(
          trait,
          "Only the strongest Weapon trait is retained for the combined profile.",
        );
      }

      return includedContribution(trait, "Weapon (Mount)");
    }

    return includedContribution(trait, trait.damage ? mountAttackName(trait.name) : trait.name);
  });
}

export function isArmourTraitName(name: string): boolean {
  return normalizeTraitName(name) === "armour";
}

export function normalizeTraitName(name: string): string {
  return name
    .trim()
    .replace(/\s*\(mount\)\s*$/i, "")
    .toLocaleLowerCase();
}

function includedContribution(
  trait: NpcMountTraitSummary,
  outputName: string,
): NpcMountTraitContribution {
  return {
    fixedDamage: trait.fixedDamage,
    included: true,
    name: trait.name,
    outputName,
    reason: "",
    sourceUuid: trait.uuid,
  };
}

function excludedContribution(
  trait: NpcMountTraitSummary,
  reason: string,
): NpcMountTraitContribution {
  return {
    fixedDamage: trait.fixedDamage,
    included: false,
    name: trait.name,
    outputName: "",
    reason,
    sourceUuid: trait.uuid,
  };
}

function isNamedTrait(trait: NpcMountTraitSummary, name: string): boolean {
  return normalizeTraitName(trait.name) === name;
}

function isTraitWithSpecification(
  trait: NpcMountTraitSummary,
  name: string,
  specification: string,
): boolean {
  if (isNamedTrait(trait, name)) {
    return trait.specification.trim().toLocaleLowerCase() === specification;
  }

  return trait.name.trim().toLocaleLowerCase() === `${name} (${specification})`;
}

function mountAttackName(name: string): string {
  return /\(mount\)\s*$/i.test(name.trim()) ? name.trim() : `${name.trim()} (Mount)`;
}

function selectStrongestWeaponUuid(traits: NpcMountTraitSummary[]): string {
  return (
    [...traits].sort((left, right) => {
      const damageDifference = (right.fixedDamage ?? 0) - (left.fixedDamage ?? 0);

      return damageDifference || left.uuid.localeCompare(right.uuid);
    })[0]?.uuid ?? ""
  );
}
