import { assertFoundryActor } from "../../foundry/document-guards";
import { ActorPortraitGalleryApplication } from "./ActorPortraitGalleryApplication";

export async function openActorPortraitGallery(actorUuid: string): Promise<void> {
  const actor = assertFoundryActor(
    await fromUuid(actorUuid),
    "The requested Actor could not be opened in the portrait gallery.",
  );

  await new ActorPortraitGalleryApplication(actor).render(true);
}

export async function openActorPortraitGalleryForDocument(
  actor: FoundryActorDocument,
): Promise<void> {
  await new ActorPortraitGalleryApplication(actor).render(true);
}
