import type {
  DebugShapeInspectOptions,
  DebugShapeProbeConfig,
  DebugShapeProbeHook,
  DebugShapeProbeSummary,
} from "../../../types/module/debug-shape-inspector";

import { MODULE_ID } from "../../constants";
import { logInfo, logWarning } from "../../logging";
import {
  DEFAULT_MAX_DEPTH,
  DEFAULT_MAX_ENTRIES,
  MAX_DEPTH_LIMIT,
  MAX_ENTRIES_LIMIT,
  STORAGE_KEY,
} from "./constants";
import { resolveFoundryPath } from "./path-resolver";
import { hasUrlProbeRequest, normalizeProbe, readConfiguredProbes } from "./probe-config";
import { summarizeValue } from "./summary";
import { clampInteger } from "./utils";

export function clearDebugShapeProbes(): void {
  localStorage.removeItem(STORAGE_KEY);
  logInfo(`${MODULE_ID} | Cleared debug shape probes.`);
}

export function getDebugShapeProbes(): DebugShapeProbeConfig[] {
  return readConfiguredProbes();
}

export function inspectFoundryPath(
  path: string,
  options: DebugShapeInspectOptions = {},
): DebugShapeProbeSummary {
  const summary = createShapeSummary(path, options);

  logShapeSummary(summary);

  return summary;
}

export function registerDebugShapeProbeHooks(): void {
  const probes = readConfiguredProbes();

  for (const hook of ["init", "setup"] satisfies DebugShapeProbeHook[]) {
    const hookProbes = probes.filter((probe) => probe.hook === hook);

    if (!hookProbes.length) {
      continue;
    }

    Hooks.once(hook, () => {
      for (const probe of hookProbes) {
        inspectProbe(probe, hook);
      }
    });
  }

  Hooks.once("ready", () => {
    const readyProbes = readConfiguredProbes().filter(
      (probe) => (probe.hook ?? "ready") === "ready",
    );

    if (hasUrlProbeRequest()) {
      logInfo(
        `${MODULE_ID} | Debug shape ready probes discovered: ${readyProbes.length}`,
        window.location.href,
      );
    }

    for (const probe of readyProbes) {
      inspectProbe(probe, "ready");
    }
  });
}

export function setDebugShapeProbes(probes: DebugShapeProbeConfig[]): void {
  const normalized = probes.map(normalizeProbe);

  localStorage.setItem(STORAGE_KEY, JSON.stringify(normalized));
  logInfo(
    `${MODULE_ID} | Stored ${normalized.length} debug shape probe(s). Reload Foundry to run init/setup probes.`,
  );
}

function createShapeSummary(
  path: string,
  options: DebugShapeInspectOptions = {},
  hook?: DebugShapeProbeHook,
): DebugShapeProbeSummary {
  const maxDepth = clampInteger(options.maxDepth, DEFAULT_MAX_DEPTH, MAX_DEPTH_LIMIT);
  const maxEntries = clampInteger(options.maxEntries, DEFAULT_MAX_ENTRIES, MAX_ENTRIES_LIMIT);
  const value = resolveFoundryPath(path);
  const summary: DebugShapeProbeSummary = {
    inspectedAt: new Date().toISOString(),
    label: options.label || path,
    maxDepth,
    maxEntries,
    path,
    value: summarizeValue(value, {
      maxDepth,
      maxEntries,
      seen: new WeakSet(),
    }),
  };

  if (hook) {
    summary.hook = hook;
  }

  return summary;
}

function inspectProbe(probe: DebugShapeProbeConfig, hook: DebugShapeProbeHook): void {
  try {
    const summary = createShapeSummary(probe.path, probe, hook);
    logShapeSummary(summary);
  } catch (error) {
    logWarning(`${MODULE_ID} | Debug shape probe failed for "${probe.path}".`, error);
  }
}

function logShapeSummary(summary: DebugShapeProbeSummary): void {
  logInfo(`${MODULE_ID} | Debug shape probe: ${summary.label}`, JSON.stringify(summary, null, 2));
}
