import type { Ref } from "vue";

import type { NpcActorCombatProfile, NpcBaseActorSummary } from "../../types/npc-builder";

interface MountStoreSliceContext {
  baseActorCombatProfile: Ref<NpcActorCombatProfile | null>;
  mountActorProfile: Ref<NpcActorCombatProfile | null>;
  mountActors: Ref<NpcBaseActorSummary[]>;
  selectedMountActorUuid: Ref<string>;
}

export function createMountStoreSlice(context: MountStoreSliceContext) {
  const { baseActorCombatProfile, mountActorProfile, mountActors, selectedMountActorUuid } =
    context;

  function clearMountSelection(): void {
    selectedMountActorUuid.value = "";
    mountActorProfile.value = null;
  }

  function hydrateBaseActorCombatProfile(profile: NpcActorCombatProfile | null): void {
    baseActorCombatProfile.value = profile;
  }

  function hydrateMountActorProfile(profile: NpcActorCombatProfile | null): void {
    mountActorProfile.value = profile;
  }

  function hydrateMountActors(actors: NpcBaseActorSummary[]): void {
    mountActors.value = [...actors].sort((left, right) => left.name.localeCompare(right.name));

    if (
      selectedMountActorUuid.value &&
      !mountActors.value.some((actor) => actor.uuid === selectedMountActorUuid.value)
    ) {
      clearMountSelection();
    }
  }

  function selectMountActor(actor: NpcBaseActorSummary): void {
    if (!mountActors.value.some((entry) => entry.uuid === actor.uuid)) {
      mountActors.value = [...mountActors.value, actor].sort((left, right) =>
        left.name.localeCompare(right.name),
      );
    }

    selectMountActorUuid(actor.uuid);
  }

  function selectMountActorUuid(uuid: string): void {
    selectedMountActorUuid.value = uuid;
    mountActorProfile.value = null;
  }

  return {
    clearMountSelection,
    hydrateBaseActorCombatProfile,
    hydrateMountActorProfile,
    hydrateMountActors,
    selectMountActor,
    selectMountActorUuid,
  };
}
