import type { GrantItemReference } from "../../../types/item-grants";

import { assertFoundryItem } from "../../foundry/document-guards";
import { parseDropData } from "../../foundry/drop-data";

export function getDroppedItemData(event: DragEvent): null | string {
  const rawData = event.dataTransfer?.getData("text/plain") ?? "";

  if (!rawData) {
    return null;
  }

  try {
    const dropData = parseDropData(rawData);

    return dropData.type === "Item" ? rawData : null;
  } catch {
    return null;
  }
}

export async function resolveDroppedItem(data: string): Promise<FoundryItemDocument> {
  const dropData = parseDropData(data);

  if (!dropData.uuid) {
    throw new Error("Drop an Item with a resolvable UUID.");
  }

  return assertFoundryItem(await fromUuid(dropData.uuid), "The dropped Item was not found.");
}

export function createGrantItemReference(item: FoundryItemDocument): GrantItemReference {
  const reference: GrantItemReference = {
    name: item.name,
    uuid: item.uuid,
  };

  if (item.img) {
    reference.img = item.img;
  }

  return reference;
}
