import {
  speciesItemHasParent,
  speciesItemKey,
} from "../../../functions/species-builder/items/identity";
import { isRecord } from "../../../shared/object-readers";
import type { SpeciesTableDrop, SpeciesTableOption } from "../../../types/species-table";
import type { SpeciesItemReference } from "../../../types/species-builder/species-item";
import { assertFoundryItem } from "../../foundry/document-guards";
import { isSpeciesItem, readSpeciesItem } from "../species-builder/items/adapter";
import { findImportedReference } from "../species-builder/items/imported-references";
import { worldSpeciesItems } from "../species-builder/items/repository";

export function requireSpeciesTableGm(): void {
  if (!game.user?.isGM) throw new Error("Only a GM can edit the world's Species table.");
}

export function speciesTableOptions(): SpeciesTableOption[] {
  const config = game.wfrp4e?.config?.["species"];
  const options = new Map<string, SpeciesTableOption>();
  if (isRecord(config)) {
    for (const [key, label] of Object.entries(config)) {
      if (typeof label === "string" && label.trim()) options.set(key, { key, label });
    }
  }
  const seen = new Set<string>();
  for (const document of worldSpeciesItems()) {
    const item = readSpeciesItem(document);
    if (speciesItemHasParent(item)) continue;
    const key = speciesItemKey(item);
    if (seen.has(key))
      throw new Error(
        `Multiple world Species Items use the key “${key}”. Give them distinct keys first.`,
      );
    seen.add(key);
    // Installed names must match exactly: current chargen looks them up in config.species.
    options.set(key, { key, label: options.get(key)?.label ?? item.name, itemUuid: item.uuid });
  }
  return [...options.values()].sort((a, b) => a.label.localeCompare(b.label));
}

export async function resolveSpeciesReference(
  reference: SpeciesItemReference,
): Promise<FoundryItemDocument> {
  const documents = worldSpeciesItems();
  const existing = findImportedReference(reference, documents);
  const source = assertFoundryItem(
    existing ?? (await fromUuid(reference.uuid || `Item.${reference.id}`)),
    `Species Item “${reference.name || reference.uuid || reference.id}” is unavailable.`,
  );
  // Legacy compendium UUIDs omit the document type. Resolve them before matching import origins.
  const item =
    existing ??
    findImportedReference({ uuid: source.uuid, id: source.id, name: source.name }, documents) ??
    source;
  if (!isSpeciesItem(item)) throw new Error("Drop a Species Item into this editor.");
  if (!item.compendium && !worldSpeciesItems().some((entry) => entry.uuid === item.uuid))
    throw new Error("Use a world or compendium Species Item, rather than an Item on an Actor.");
  return item;
}

export async function resolveSpeciesSource(uuid: string): Promise<FoundryItemDocument> {
  return resolveSpeciesReference({ uuid, id: "", name: "" });
}

export async function speciesSourceFamily(uuid: string): Promise<FoundryItemDocument[]> {
  const item = await resolveSpeciesSource(uuid);
  const record = readSpeciesItem(item);
  if (!speciesItemHasParent(record)) return [item];
  const parent = await resolveSpeciesReference(record.system.subspeciesOf);
  if (speciesItemHasParent(readSpeciesItem(parent)))
    throw new Error(
      `${item.name}: nested or cyclic subspecies cannot be used by WFRP's current Species table.`,
    );
  return [parent, item];
}

export async function resolveSpeciesTableDrop(data: string): Promise<SpeciesTableDrop> {
  requireSpeciesTableGm();
  const payload: unknown = JSON.parse(data);
  if (!isRecord(payload) || typeof payload["uuid"] !== "string")
    throw new Error("Drop a Species Item or enter its UUID.");
  const family = await speciesSourceFamily(payload["uuid"]);
  const base = family[0]!;
  const key = speciesItemKey(readSpeciesItem(base));
  const existing = speciesTableOptions().find((option) => option.key === key);
  if (existing?.itemUuid && existing.itemUuid !== base.uuid)
    throw new Error(
      `A different world Species Item already uses the key “${key}”. Use that Item or change the duplicate key first.`,
    );
  const imports = family.filter((item) => item.compendium);
  const messages =
    family.length > 1
      ? [
          `Added ${base.name}; ${family[1]!.name} is a subspecies chosen after the base species roll.`,
        ]
      : [`Added ${base.name}.`];
  if (imports.length)
    messages.push(
      `${imports.map((item) => item.name).join(", ")} will be imported on Save. Reload the world afterward to activate newly imported species.`,
    );
  return {
    option: { key, label: existing?.label ?? base.name, itemUuid: base.uuid },
    sources: family.map((item) => ({ uuid: item.uuid, name: item.name })),
    message: messages.join(" "),
  };
}

export async function importSpeciesSource(uuid: string): Promise<FoundryItemDocument> {
  const family = await speciesSourceFamily(uuid);
  let parent: FoundryItemDocument | undefined;
  for (const source of family) {
    const item = await resolveSpeciesSource(source.uuid);
    if (!item.compendium) {
      parent = item;
      continue;
    }
    const update = parent
      ? { "system.subspeciesOf": { uuid: parent.uuid, id: parent.id, name: parent.name } }
      : {};
    const imported = await game.items!.importFromCompendium(item.compendium, item.id, update, {
      renderSheet: false,
    });
    if (!imported)
      throw new Error(
        `Foundry did not import ${item.name}. Any Items already imported remain available; retrying reuses them.`,
      );
    parent = imported;
  }
  return parent!;
}
