import type {
  SpeciesBuilderHeightDefinition,
  SpeciesBuilderSubspeciesDefinition,
} from "../../../../types/species-builder/species-builder";
import type { WfrpCharacteristicKey } from "../../../../types/wfrp4e/characteristics";

import { assignIfPresent } from "../../../../shared/assign-if-present";
import { isRecord } from "../../../../shared/object-readers";
import { WfrpCharacteristicKey as CharacteristicKey } from "../../../../types/wfrp4e/characteristics";

const CHARACTERISTIC_KEYS = Object.values(CharacteristicKey);

export interface RuntimeTalentValues {
  randomTalentCount?: number;
  talents: string[];
}

export interface RuntimeListDelta {
  added?: string[];
  removed?: string[];
}

export function readRuntimeString(value: unknown): string | undefined {
  if (typeof value !== "string") {
    return undefined;
  }

  return value.trim() || undefined;
}

export function readRuntimeNumber(value: unknown): number | undefined {
  return typeof value === "number" && Number.isFinite(value) ? value : undefined;
}

export function readRuntimeStringArray(value: unknown): string[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }

  return value.flatMap((entry) => {
    const normalized = readRuntimeString(entry);

    return normalized ? [normalized] : [];
  });
}

export function readRuntimeTalentValues(value: unknown): RuntimeTalentValues | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }

  let randomTalentCount: number | undefined;
  const talents: string[] = [];

  for (const entry of value) {
    const count = readRuntimeNumericValue(entry);

    if (count !== undefined) {
      randomTalentCount = count;
      continue;
    }

    const talent = readRuntimeString(entry);

    if (talent) {
      talents.push(talent);
    }
  }

  return randomTalentCount === undefined ? { talents } : { randomTalentCount, talents };
}

function readRuntimeNumericValue(value: unknown): number | undefined {
  if (typeof value === "number") {
    return readRuntimeNumber(value);
  }

  if (typeof value !== "string" || !value.trim()) {
    return undefined;
  }

  const numberValue = Number(value);

  return Number.isFinite(numberValue) ? numberValue : undefined;
}

export function readRuntimeStringRecord(value: unknown): Record<string, string> | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  return Object.fromEntries(
    Object.entries(value).flatMap(([key, entry]) => {
      const normalizedKey = readRuntimeString(key);
      const normalizedValue = readRuntimeString(entry);

      return normalizedKey && normalizedValue ? [[normalizedKey, normalizedValue]] : [];
    }),
  );
}

export function readRuntimeNumberRecord(value: unknown): Record<string, number> | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  return Object.fromEntries(
    Object.entries(value).flatMap(([key, entry]) => {
      const normalizedKey = readRuntimeString(key);
      const normalizedValue = readRuntimeNumericValue(entry);

      return normalizedKey && normalizedValue !== undefined
        ? [[normalizedKey, normalizedValue]]
        : [];
    }),
  );
}

export function readRuntimeStringArrayRecord(value: unknown): Record<string, string[]> | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  return Object.fromEntries(
    Object.entries(value).flatMap(([key, entry]) => {
      const normalizedKey = readRuntimeString(key);
      const normalizedValue = readRuntimeStringArray(entry);

      return normalizedKey && normalizedValue ? [[normalizedKey, normalizedValue]] : [];
    }),
  );
}

export function readRuntimeCharacteristics(
  value: unknown,
): Partial<Record<WfrpCharacteristicKey, string>> | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const entries = CHARACTERISTIC_KEYS.flatMap((key) => {
    const formula = readRuntimeString(value[key]);

    return formula ? [[key, formula] as const] : [];
  });

  return entries.length > 0 ? Object.fromEntries(entries) : {};
}

export function readRuntimeHeight(value: unknown): SpeciesBuilderHeightDefinition | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const height: SpeciesBuilderHeightDefinition = {};

  assignIfPresent(height, "die", readRuntimeString(value["die"]));
  assignIfPresent(height, "feet", readRuntimeNumber(value["feet"]));
  assignIfPresent(height, "inches", readRuntimeNumber(value["inches"]));

  return Object.keys(height).length > 0 ? height : {};
}

export function mergeRuntimeRandomTalents(
  configured: Record<string, number> | undefined,
  numericTalentCount: number | undefined,
  inherited: Record<string, number> | undefined = undefined,
): Record<string, number> | undefined {
  if (!configured && numericTalentCount === undefined) {
    return undefined;
  }

  const merged = { ...(configured ?? inherited) };

  if (numericTalentCount !== undefined) {
    merged["talents"] = numericTalentCount;
  }

  return merged;
}

export function runtimeListDelta(parent: string[], child: string[]): RuntimeListDelta {
  const added = child.filter((entry) => !parent.includes(entry));
  const removed = parent.filter((entry) => !child.includes(entry));
  const delta: RuntimeListDelta = {};

  assignIfPresent(delta, "added", added.length > 0 ? added : undefined);
  assignIfPresent(delta, "removed", removed.length > 0 ? removed : undefined);

  return delta;
}

export function changedRuntimeCharacteristics(
  parent: Partial<Record<WfrpCharacteristicKey, string>> | undefined,
  child: Partial<Record<WfrpCharacteristicKey, string>>,
): Partial<Record<WfrpCharacteristicKey, string>> | undefined {
  const changed = Object.fromEntries(
    Object.entries(child).filter(
      ([key, formula]) => parent?.[key as WfrpCharacteristicKey] !== formula,
    ),
  );

  return Object.keys(changed).length > 0 ? changed : undefined;
}

export function runtimeRecordsEqual(
  left: Record<string, string | number> | undefined,
  right: Record<string, string | number> | undefined,
): boolean {
  const leftEntries = Object.entries(left ?? {});
  const rightEntries = Object.entries(right ?? {});

  return (
    leftEntries.length === rightEntries.length &&
    leftEntries.every(([key, value]) => right?.[key] === value)
  );
}

export function assignChangedRuntimeNumber(
  definition: SpeciesBuilderSubspeciesDefinition,
  field: "extra" | "fate" | "movement" | "resilience",
  parent: number | undefined,
  value: unknown,
): void {
  const numberValue = readRuntimeNumber(value);

  if (numberValue !== undefined && numberValue !== parent) {
    definition[field] = numberValue;
  }
}
