import { DaisyExampleApplication } from "./apps/daisy-example/DaisyExampleApplication";
import { NpcBuilderApplication } from "./apps/npc-builder/NpcBuilderApplication";
import { EffectBuildersApplication } from "./apps/effect-builders/EffectBuildersApplication";
import { WorkbenchApplication } from "./apps/workbench/WorkbenchApplication";
import { MODULE_ID, MODULE_TITLE } from "./constants";

export function registerModuleMenus(): void {
  game.settings.registerMenu(MODULE_ID, "workbench", {
    hint: `Open the ${MODULE_TITLE} workbench.`,
    icon: "fa-solid fa-screwdriver-wrench",
    label: "Open Workbench",
    name: MODULE_TITLE,
    restricted: true,
    type: WorkbenchApplication,
  });

  game.settings.registerMenu(MODULE_ID, "npc-builder", {
    hint: "Build a WFRP4e NPC from a base Actor and Career items.",
    icon: "fa-solid fa-user-plus",
    label: "Open NPC Builder",
    name: "WFRP4e NPC Builder",
    restricted: true,
    type: NpcBuilderApplication,
  });

  game.settings.registerMenu(MODULE_ID, "effect-builders", {
    hint: "Create native WFRP effects on your Items.",
    icon: "fa-solid fa-wand-magic-sparkles",
    label: "Open Effect Builders",
    name: "Effect Builders",
    restricted: false,
    type: EffectBuildersApplication,
  });

  game.settings.registerMenu(MODULE_ID, "daisy-example", {
    hint: "Open a small isolated DaisyUI component probe.",
    icon: "fa-solid fa-flask",
    label: "Open Daisy Probe",
    name: "WFRP4e Daisy Probe",
    restricted: true,
    type: DaisyExampleApplication,
  });
}
