export interface EmbeddedItemChanges {
  creates: FoundryItemSource[];
  deletes: string[];
  updates: Array<Record<string, unknown>>;
}

export function createEmptyEmbeddedItemChanges(): EmbeddedItemChanges {
  return {
    creates: [],
    deletes: [],
    updates: [],
  };
}

export async function applyEmbeddedItemChanges(
  actor: FoundryActorDocument,
  changes: EmbeddedItemChanges,
): Promise<void> {
  if (changes.deletes.length && actor.deleteEmbeddedDocuments) {
    await actor.deleteEmbeddedDocuments("Item", changes.deletes);
  }

  if (changes.updates.length && actor.updateEmbeddedDocuments) {
    await actor.updateEmbeddedDocuments("Item", changes.updates);
  }

  if (changes.creates.length) {
    await actor.createEmbeddedDocuments("Item", changes.creates);
  }
}
