import type { NpcSkillCharacteristicSummary } from "../../types/npc-builder";

import {
  getConcreteSkillGrant,
  normalizeSkillGrantText,
} from "../../functions/npc-builder/skill-specialization";
import { readStringPath } from "../../shared/object-readers";
import {
  isWfrpCharacteristicKey,
  WFRP_CHARACTERISTIC_NAMES,
} from "../../types/wfrp4e/characteristics";
import {
  isItemCompendiumPack,
  readCompendiumIndexEntries,
  yieldToFoundry,
} from "../foundry/compendiums";
import { logWarning } from "../logging";

type SkillSpecializationIndexState = "error" | "idle" | "indexing" | "ready";

const skillIndexFields = ["name", "type", "system.characteristic.value"];

const skillSpecializationIndex = new Map<string, Set<string>>();
const skillCharacteristicIndex = new Map<string, NpcSkillCharacteristicSummary>();
const baseSkillCharacteristicIndex = new Map<string, NpcSkillCharacteristicSummary>();
let indexState: SkillSpecializationIndexState = "idle";
let indexingPromise: null | Promise<void> = null;

export async function listWfrpSkillSpecializations(baseName: string): Promise<string[]> {
  const normalizedBaseName = normalizeSkillGrantText(baseName);

  if (!normalizedBaseName) {
    return [];
  }

  if (indexState === "idle") {
    void startSkillSpecializationIndexing();
  }

  if (indexingPromise) {
    await indexingPromise;
  }

  return [...(skillSpecializationIndex.get(normalizedBaseName) ?? [])].sort((left, right) =>
    left.localeCompare(right),
  );
}

export async function listWfrpSkillCharacteristics(
  skillNames: string[],
): Promise<NpcSkillCharacteristicSummary[]> {
  if (indexState === "idle") {
    void startSkillSpecializationIndexing();
  }

  if (indexingPromise) {
    await indexingPromise;
  }

  return skillNames.flatMap((skillName) => {
    const characteristic = findIndexedSkillCharacteristic(skillName);

    return characteristic
      ? [
          {
            ...characteristic,
            skillName,
          },
        ]
      : [];
  });
}

export function startSkillSpecializationIndexing(): Promise<void> {
  if (indexingPromise) {
    return indexingPromise;
  }

  indexState = "indexing";
  skillSpecializationIndex.clear();
  skillCharacteristicIndex.clear();
  baseSkillCharacteristicIndex.clear();

  indexingPromise = buildSkillSpecializationIndex()
    .then(() => {
      indexState = "ready";
    })
    .catch((error: unknown) => {
      indexState = "error";
      logWarning("wfrp4e-customizer-apps | Skill specialization indexing failed.", error);
    });

  return indexingPromise;
}

async function buildSkillSpecializationIndex(): Promise<void> {
  indexWorldSkillSpecializations();
  await yieldToFoundry();

  for (const pack of game.packs ?? []) {
    if (!isItemCompendiumPack(pack) || !pack.getIndex) {
      continue;
    }

    const index = await pack.getIndex({ fields: skillIndexFields });

    for (const entry of readCompendiumIndexEntries(index)) {
      indexSkillSpecializationFromIndex(entry);
    }

    await yieldToFoundry();
  }
}

function indexSkillSpecialization(item: FoundryItemDocument): void {
  if (item.type !== "skill") {
    return;
  }

  indexSkillCharacteristic(item);

  const skillGrant = getConcreteSkillGrant(item.name);

  if (!skillGrant) {
    return;
  }

  const normalizedBaseName = normalizeSkillGrantText(skillGrant.baseName);
  const specializations = skillSpecializationIndex.get(normalizedBaseName) ?? new Set<string>();

  specializations.add(skillGrant.specialization);
  skillSpecializationIndex.set(normalizedBaseName, specializations);
}

function indexSkillSpecializationFromIndex(entry: FoundryCompendiumIndexEntry): void {
  if (entry.type !== "skill" || !entry.name) {
    return;
  }

  indexSkillCharacteristicFromIndex(entry);

  const skillGrant = getConcreteSkillGrant(entry.name);

  if (!skillGrant) {
    return;
  }

  const normalizedBaseName = normalizeSkillGrantText(skillGrant.baseName);
  const specializations = skillSpecializationIndex.get(normalizedBaseName) ?? new Set<string>();

  specializations.add(skillGrant.specialization);
  skillSpecializationIndex.set(normalizedBaseName, specializations);
}

function indexSkillCharacteristic(item: FoundryItemDocument): void {
  const characteristicKey = readStringPath(item.system, ["characteristic", "value"]);

  if (!isWfrpCharacteristicKey(characteristicKey)) {
    return;
  }

  const summary: NpcSkillCharacteristicSummary = {
    characteristicKey,
    characteristicName: WFRP_CHARACTERISTIC_NAMES[characteristicKey],
    skillName: item.name,
  };
  const normalizedName = normalizeSkillGrantText(item.name);
  const skillGrant = getConcreteSkillGrant(item.name);
  const normalizedBaseName = normalizeSkillGrantText(skillGrant?.baseName ?? item.name);

  skillCharacteristicIndex.set(normalizedName, summary);

  if (!baseSkillCharacteristicIndex.has(normalizedBaseName)) {
    baseSkillCharacteristicIndex.set(normalizedBaseName, summary);
  }
}

function indexSkillCharacteristicFromIndex(entry: FoundryCompendiumIndexEntry): void {
  const characteristicKey = readStringPath(entry, ["system", "characteristic", "value"]);

  if (!isWfrpCharacteristicKey(characteristicKey) || !entry.name) {
    return;
  }

  const summary: NpcSkillCharacteristicSummary = {
    characteristicKey,
    characteristicName: WFRP_CHARACTERISTIC_NAMES[characteristicKey],
    skillName: entry.name,
  };
  const normalizedName = normalizeSkillGrantText(entry.name);
  const skillGrant = getConcreteSkillGrant(entry.name);
  const normalizedBaseName = normalizeSkillGrantText(skillGrant?.baseName ?? entry.name);

  skillCharacteristicIndex.set(normalizedName, summary);

  if (!baseSkillCharacteristicIndex.has(normalizedBaseName)) {
    baseSkillCharacteristicIndex.set(normalizedBaseName, summary);
  }
}

function findIndexedSkillCharacteristic(skillName: string): NpcSkillCharacteristicSummary | null {
  const normalizedName = normalizeSkillGrantText(skillName);
  const skillGrant = getConcreteSkillGrant(skillName);
  const normalizedBaseName = normalizeSkillGrantText(skillGrant?.baseName ?? skillName);

  return (
    skillCharacteristicIndex.get(normalizedName) ??
    baseSkillCharacteristicIndex.get(normalizedBaseName) ??
    null
  );
}

function indexWorldSkillSpecializations(): void {
  for (const item of game.items?.contents ?? []) {
    indexSkillSpecialization(item);
  }
}
