import type { SpeciesBuilderHeightDefinition } from "../../../types/species-builder/species-builder";
import type { WfrpCharacteristicKey } from "../../../types/wfrp4e/characteristics";

import { assignIfPresent } from "../../../shared/assign-if-present";
import { isRecord } from "../../../shared/object-readers";
import { WfrpCharacteristicKey as CharacteristicKey } from "../../../types/wfrp4e/characteristics";
import { createSpeciesConfigKey } from "../config-keys";

const WFRP_CHARACTERISTIC_KEYS = Object.values(CharacteristicKey);

export function normalizeConfigKey(value: unknown): string {
  if (typeof value !== "string") {
    return "";
  }

  return createSpeciesConfigKey(value);
}

export function normalizeString(value: unknown): string | undefined {
  if (typeof value !== "string") {
    return undefined;
  }

  const trimmed = value.trim();

  return trimmed || undefined;
}

export function normalizeNumber(value: unknown): number | undefined {
  const numberValue = Number(value);

  return Number.isFinite(numberValue) ? numberValue : undefined;
}

export function normalizeStringArray(value: unknown): string[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }

  const entries = value.flatMap((entry) => {
    const normalized = normalizeString(entry);

    return normalized ? [normalized] : [];
  });

  return entries.length > 0 ? entries : undefined;
}

export function normalizeStringRecord(value: unknown): Record<string, string> | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const entries = Object.entries(value).flatMap(([key, entry]) => {
    const normalizedKey = normalizeString(key);
    const normalizedValue = normalizeString(entry);

    return normalizedKey && normalizedValue ? [[normalizedKey, normalizedValue] as const] : [];
  });

  return entries.length > 0 ? Object.fromEntries(entries) : undefined;
}

export function normalizeNumberRecord(value: unknown): Record<string, number> | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const entries = Object.entries(value).flatMap(([key, entry]) => {
    const normalizedKey = normalizeString(key);
    const normalizedValue = normalizeNumber(entry);

    return normalizedKey && normalizedValue !== undefined
      ? [[normalizedKey, normalizedValue] as const]
      : [];
  });

  return entries.length > 0 ? Object.fromEntries(entries) : undefined;
}

export function normalizeStringArrayRecord(value: unknown): Record<string, string[]> | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const entries = Object.entries(value).flatMap(([key, entry]) => {
    const normalizedKey = normalizeString(key);
    const normalizedValue = normalizeStringArray(entry);

    return normalizedKey && normalizedValue ? [[normalizedKey, normalizedValue] as const] : [];
  });

  return entries.length > 0 ? Object.fromEntries(entries) : undefined;
}

export function normalizeCharacteristics(
  value: unknown,
): Partial<Record<WfrpCharacteristicKey, string>> | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const entries = WFRP_CHARACTERISTIC_KEYS.flatMap((key) => {
    const formula = normalizeString(value[key]);

    return formula ? [[key, formula] as const] : [];
  });

  return entries.length > 0 ? Object.fromEntries(entries) : undefined;
}

export function normalizeHeight(value: unknown): SpeciesBuilderHeightDefinition | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const height: SpeciesBuilderHeightDefinition = {};

  assignIfPresent(height, "die", normalizeString(value["die"]));
  assignIfPresent(height, "feet", normalizeNumber(value["feet"]));
  assignIfPresent(height, "inches", normalizeNumber(value["inches"]));

  return Object.keys(height).length > 0 ? height : undefined;
}

export function normalizeWoundFormula(value: unknown): undefined | { formula: string } {
  if (!isRecord(value)) {
    return undefined;
  }

  const formula = normalizeString(value["formula"]);

  return formula ? { formula } : undefined;
}
