<script setup lang="ts">
import NpcBuilderSection from "../NpcBuilderSection.vue";

defineProps<{
  autoSelectGrantedSpells: boolean;
}>();

const emit = defineEmits<{
  autoSelectGrantedSpellsChange: [value: boolean];
}>();

function handleAutoSelectChange(event: Event): void {
  const input = event.target as HTMLInputElement | null;

  emit("autoSelectGrantedSpellsChange", Boolean(input?.checked));
}
</script>

<template>
  <NpcBuilderSection number="6" title="Magic and Spells">
    <label class="dui-label">
      <input
        class="dui-toggle dui-toggle-sm"
        :checked="autoSelectGrantedSpells"
        type="checkbox"
        @change="handleAutoSelectChange"
      />
      <span>Select detected Lore spells by default</span>
    </label>
  </NpcBuilderSection>
</template>
