import { storeToRefs } from "pinia";
import { computed, ref, watch } from "vue";

import type { NpcBuilderBridge, NpcPortraitSearchAvailability } from "../../../types/npc-builder";

import { createDefaultNpcBuilderSettings } from "../../../functions/npc-builder/default-npc-builder-settings";
import { getPortraitSearchStatusLabel } from "../../../functions/npc-builder/settings/portrait-search-status";
import { createSettingsSavePayload } from "../../../functions/npc-builder/settings/settings-payload";
import { useNpcBuilderStore } from "..";

export function createNpcBuilderSettingsWorkflow(bridge: NpcBuilderBridge) {
  const store = useNpcBuilderStore();
  const { actorFolders, itemFolders, settings } = storeToRefs(store);

  const baseActorFolderName = ref("");
  const errorMessage = ref("");
  const isBusy = ref(false);
  const outputActorFolderName = ref("");
  const portraitSearchAvailability = ref<NpcPortraitSearchAvailability | null>(null);
  const quickTraitFolderName = ref("");
  const settingsMessage = ref("");

  const canUseDigDownPortraitSearch = computed(
    () => portraitSearchAvailability.value?.digDownActive ?? true,
  );
  const portraitSearchStatusLabel = computed(() =>
    getPortraitSearchStatusLabel(portraitSearchAvailability.value),
  );

  watch(portraitSearchAvailability, (availability) => {
    if (availability && !availability.digDownActive) {
      settings.value.searchFoundryPortraitAssets = false;
    }
  });

  async function saveBaseActorFolderName(): Promise<void> {
    await ensureFolderForSetting({
      ensureFolder: bridge.ensureActorFolder,
      name: baseActorFolderName.value,
      refresh: refreshActorFolders,
      setFolderUuid: (uuid) => {
        settings.value.baseActorFolderUuid = uuid;
      },
    });
  }

  async function saveOutputActorFolderName(): Promise<void> {
    await ensureFolderForSetting({
      ensureFolder: bridge.ensureActorFolder,
      name: outputActorFolderName.value,
      refresh: refreshActorFolders,
      setFolderUuid: (uuid) => {
        settings.value.outputActorFolderUuid = uuid;
      },
    });
  }

  async function saveQuickTraitFolderName(): Promise<void> {
    await ensureFolderForSetting({
      ensureFolder: bridge.ensureItemFolder,
      name: quickTraitFolderName.value,
      refresh: refreshItemFolders,
      setFolderUuid: (uuid) => {
        settings.value.quickTraitFolderUuid = uuid;
      },
    });

    store.hydrateQuickTraits(await bridge.listQuickTraits(settings.value));
  }

  async function ensureFolderForSetting(options: {
    ensureFolder: (name: string) => Promise<{ name: string; uuid: string }>;
    name: string;
    refresh: () => Promise<void>;
    setFolderUuid: (uuid: string) => void;
  }): Promise<void> {
    await runSettingsAction(async () => {
      const folder = await options.ensureFolder(options.name);

      await options.refresh();
      options.setFolderUuid(folder.uuid);
      store.hydrateSettings(await bridge.saveSettings(getSavePayload()));
      settingsMessage.value = `Using folder "${folder.name}".`;
    });
  }

  async function refreshActorFolders(): Promise<void> {
    store.hydrateActorFolders(await bridge.listActorFolders());
  }

  async function refreshItemFolders(): Promise<void> {
    store.hydrateItemFolders(await bridge.listItemFolders());
  }

  async function refreshPortraitSearchAvailability(): Promise<void> {
    portraitSearchAvailability.value = await bridge.getPortraitSearchAvailability();
  }

  async function importRecommendedQuickTraits(): Promise<void> {
    await runSettingsAction(async () => {
      store.hydrateSettings(await bridge.saveSettings(getSavePayload()));
      store.hydrateQuickTraits(await bridge.importRecommendedQuickTraits(settings.value));
      settingsMessage.value = "Recommended quick traits imported.";
    });
  }

  async function saveSettings(): Promise<void> {
    await runSettingsAction(async () => {
      store.hydrateSettings(await bridge.saveSettings(getSavePayload()));
      await refreshDraftSources();
      settingsMessage.value = "Settings saved.";
    });
  }

  async function resetSettingsToDefaults(): Promise<void> {
    await runSettingsAction(async () => {
      store.hydrateSettings(await bridge.saveSettings(createDefaultNpcBuilderSettings()));
      await refreshDraftSources();
      settingsMessage.value = "Settings reset to defaults.";
    });
  }

  async function runSettingsAction(action: () => Promise<void>): Promise<void> {
    isBusy.value = true;
    errorMessage.value = "";
    settingsMessage.value = "";

    try {
      await action();
    } catch (error) {
      errorMessage.value = toWorkflowErrorMessage(error);
    } finally {
      isBusy.value = false;
    }
  }

  async function refreshDraftSources(): Promise<void> {
    const [baseActors, quickTraits] = await Promise.all([
      bridge.listBaseActors(settings.value),
      bridge.listQuickTraits(settings.value),
    ]);

    store.hydrateBaseActors(baseActors);
    store.hydrateQuickTraits(quickTraits);
  }

  function getSavePayload() {
    return createSettingsSavePayload({
      canUseDigDownPortraitSearch: canUseDigDownPortraitSearch.value,
      settings: settings.value,
    });
  }

  return {
    actorFolders,
    baseActorFolderName,
    canUseDigDownPortraitSearch,
    errorMessage,
    importRecommendedQuickTraits,
    isBusy,
    itemFolders,
    outputActorFolderName,
    portraitSearchStatusLabel,
    quickTraitFolderName,
    refreshPortraitSearchAvailability,
    resetSettingsToDefaults,
    saveBaseActorFolderName,
    saveOutputActorFolderName,
    saveQuickTraitFolderName,
    saveSettings,
    settings,
    settingsMessage,
  };
}

function toWorkflowErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : "The NPC Builder could not finish that action.";
}
