<script setup lang="ts">
import { useId } from "vue";
import { useEffectBuilderStore } from "../../../state/effect-builders";
import SourceItems from "./SourceItems.vue";
const props = defineProps<{ id: string }>();
const store = useEffectBuilderStore(props.id);
const fieldId = `${props.id}-${useId()}`;
</script>

<template>
  <fieldset class="dui-fieldset">
    <legend class="dui-fieldset-legend">Player choices</legend>
    <label :for="`${fieldId}-count`" class="dui-label">Number of options to choose</label>
    <input
      :id="`${fieldId}-count`"
      v-model.number="store.draft.count"
      aria-label="Number of options to choose"
      type="number"
      min="1"
      :max="store.draft.groups.length || 1"
      step="1"
      class="dui-input"
    />
    <p>Each option can grant one Item or a whole package.</p>
    <fieldset v-for="(group, index) in store.draft.groups" :key="index" class="dui-fieldset">
      <legend class="dui-fieldset-legend">Option {{ index + 1 }}</legend>
      <label :for="`${fieldId}-${index}`" class="dui-label">Option name</label>
      <input
        :id="`${fieldId}-${index}`"
        v-model="group.name"
        aria-label="Option name"
        class="dui-input app:w-full"
      />
      <SourceItems
        :items="group.items"
        :title="`Items for option ${index + 1}`"
        @drop-data="store.dropItem($event, index)"
        @remove="store.removeItem($event, index)"
      />
      <button
        type="button"
        class="dui-btn dui-btn-sm dui-btn-ghost"
        @click="store.draft.groups.splice(index, 1)"
      >
        Remove option
      </button>
    </fieldset>
    <button type="button" class="dui-btn" @click="store.addGroup">Add option</button>
  </fieldset>
</template>
