import type { SpellResolutionInput } from "./types";

import {
  getCompendiumIndexEntryUuid,
  isItemCompendiumPack,
  readCompendiumIndexEntries,
} from "../../../../foundry/compendiums";
import { isFoundryItem } from "../../../../foundry/document-guards";
import { spellItemType } from "./constants";
import { logSpellLookupDebug, readPackDebugLabel } from "./debug";
import { readSpellLoreTerms, readSpellNameLoreSuffix } from "./lore-profiles";
import { toSpellResolutionInput } from "./spell-input-conversion";

export async function listSpellInputsFromIndex(
  pack: FoundryCompendiumCollection,
): Promise<SpellResolutionInput[]> {
  logSpellLookupDebug("Compendium index scan start", {
    pack: readPackDebugLabel(pack),
  });

  if (!pack.getIndex) {
    logSpellLookupDebug("Compendium has no index; loading documents", {
      pack: readPackDebugLabel(pack),
    });

    return await listSpellInputsFromDocuments(pack);
  }

  const index = await pack.getIndex({
    // Do not request both a parent field (`system`) and one of its dotted
    // children (`system.lore.value`). Foundry's index projection builder treats
    // the parent as a numeric marker, then fails when it tries to assign the
    // nested child path under that number.
    fields: ["name", "type", "img", "system.lore.value"],
  });
  const entries = readCompendiumIndexEntries(index);

  logSpellLookupDebug("Compendium index loaded", {
    entries: entries.length,
    pack: readPackDebugLabel(pack),
    samples: entries.slice(0, 5).map((entry) => ({
      hasLoreTerms: readSpellLoreTerms(entry).length > 0,
      name: entry.name,
      type: entry.type,
      uuid: getCompendiumIndexEntryUuid(pack, entry),
    })),
  });

  if (!entries.length) {
    logSpellLookupDebug("Compendium index empty; loading documents", {
      pack: readPackDebugLabel(pack),
    });

    return await listSpellInputsFromDocuments(pack);
  }

  const spellEntries = entries.filter(isSpellIndexEntry);

  logSpellLookupDebug("Compendium index spell candidates", {
    pack: readPackDebugLabel(pack),
    spellEntries: spellEntries.length,
  });

  const indexInputs = spellEntries
    .filter((entry) => entry.name)
    .map((entry) => toSpellResolutionInputFromIndex(pack, entry));

  if (indexInputs.length || !isTrustedSpellDocumentPack(pack)) {
    return indexInputs;
  }

  // Foundry indexes do not always expose WFRP Spell lore fields, even when the
  // fields are requested. Loading every Item pack can trigger WFRP migration
  // side effects in unrelated modules, so full document loading is limited to
  // the official spell packs needed for the current arcane magic slice.
  return await listSpellInputsFromDocuments(pack);
}

export function isItemPack(pack: FoundryCompendiumCollection): boolean {
  return isItemCompendiumPack(pack);
}

function isSpellIndexEntry(entry: FoundryCompendiumIndexEntry): boolean {
  if (entry.type === spellItemType) {
    return true;
  }

  // Some Foundry indexes omit `type` even when specific fields are requested.
  // For spell discovery, lore data or a final lore suffix is enough to keep the
  // entry as a candidate without loading the full document and triggering WFRP
  // migration side effects.
  return Boolean(
    entry.name && (readSpellLoreTerms(entry).length || readSpellNameLoreSuffix(entry.name)),
  );
}

async function listSpellInputsFromDocuments(
  pack: FoundryCompendiumCollection,
): Promise<SpellResolutionInput[]> {
  if (!pack.getDocuments) {
    logSpellLookupDebug("Compendium has no document loader", {
      pack: readPackDebugLabel(pack),
    });

    return [];
  }

  logSpellLookupDebug("Compendium document load start", {
    pack: readPackDebugLabel(pack),
  });

  const documents = await pack.getDocuments();
  const spellDocuments = documents.filter((document): document is FoundryItemDocument => {
    return isFoundryItem(document) && document.type === spellItemType;
  });

  logSpellLookupDebug("Compendium document load complete", {
    documents: documents.length,
    pack: readPackDebugLabel(pack),
    spellDocuments: spellDocuments.length,
    spellSamples: spellDocuments.slice(0, 5).map((item) => ({
      loreTerms: readSpellLoreTerms(item.system),
      name: item.name,
      uuid: item.uuid,
    })),
  });

  return spellDocuments.map((item) => toSpellResolutionInput(item, pack.title ?? "Compendium"));
}

function isTrustedSpellDocumentPack(pack: FoundryCompendiumCollection): boolean {
  return pack.collection === "wfrp4e-core.items" || pack.collection === "wfrp4e-wom.items";
}

function toSpellResolutionInputFromIndex(
  pack: FoundryCompendiumCollection,
  entry: FoundryCompendiumIndexEntry,
): SpellResolutionInput {
  return {
    img: entry.img ?? entry.thumb ?? "",
    name: entry.name ?? "",
    sourceLabel: pack.title ?? "Compendium",
    system: entry,
    uuid: getCompendiumIndexEntryUuid(pack, entry),
  };
}
