interface RollTableResultChanges {
  creates: Record<string, unknown>[];
  deletedIds: string[];
  updates: Record<string, unknown>[];
}

export async function applyRollTableResultChanges(
  table: FoundryRollTableDocument,
  changes: RollTableResultChanges,
): Promise<void> {
  if (changes.updates.length > 0) {
    await table.updateEmbeddedDocuments("TableResult", changes.updates);
  }
  if (changes.creates.length > 0) {
    await table.createEmbeddedDocuments("TableResult", changes.creates);
  }
  if (changes.deletedIds.length > 0) {
    await table.deleteEmbeddedDocuments("TableResult", changes.deletedIds);
  }
}
