import type {
  NpcAdvancementDraftEntry,
  NpcMagicGrant,
  NpcTraitDraftEntry,
} from "../../../types/npc-builder";

import { parseMagicGrantName, resolveMagicGrantLore } from "../magic-grants";

export function deriveMagicGrants(options: {
  advancements: NpcAdvancementDraftEntry[];
  loreResolutions: Record<string, string>;
  traits: NpcTraitDraftEntry[];
}): NpcMagicGrant[] {
  const grants = new Map<string, NpcMagicGrant>();

  for (const advancement of options.advancements) {
    if (advancement.kind !== "talent" || advancement.baseAdvances + advancement.current <= 0) {
      continue;
    }

    addResolvedGrant(grants, parseMagicGrantName(advancement.name, "talent"), options);
  }

  for (const trait of options.traits) {
    addResolvedGrant(grants, parseMagicGrantName(trait.name, "trait"), options);
  }

  return [...grants.values()];
}

function addResolvedGrant(
  grants: Map<string, NpcMagicGrant>,
  grant: NpcMagicGrant | null,
  options: { loreResolutions: Record<string, string> },
): void {
  if (!grant) {
    return;
  }

  const lore = options.loreResolutions[grant.resolutionKey];

  grants.set(grant.resolutionKey, lore ? resolveMagicGrantLore(grant, lore) : grant);
}
