import type { SpeciesBuilderSettings } from "../../../types/species-builder/species-builder";

import { createDefaultSpeciesBuilderSettings } from "../../../functions/species-builder/default-species-builder-settings";
import { normalizeSpeciesBuilderSettings } from "../../../functions/species-builder/species-settings-normalization";
import {
  defineFoundryObjectSetting,
  loadObjectSetting,
  registerObjectSetting,
  saveObjectSetting,
} from "../../settings/foundry-setting-adapter";

const SPECIES_BUILDER_SETTINGS_KEY = "speciesBuilderSettings";

const speciesBuilderSettingsDefinition = defineFoundryObjectSetting({
  defaultValue: createDefaultSpeciesBuilderSettings(),
  key: SPECIES_BUILDER_SETTINGS_KEY,
  name: "Species Builder Settings",
  normalize: normalizeSpeciesBuilderSettings,
});

export function registerSpeciesBuilderSettings(): void {
  registerObjectSetting(speciesBuilderSettingsDefinition);
}

export function loadSpeciesBuilderSettings(): SpeciesBuilderSettings {
  return loadObjectSetting(speciesBuilderSettingsDefinition);
}

export async function saveSpeciesBuilderSettings(
  settings: SpeciesBuilderSettings,
): Promise<SpeciesBuilderSettings> {
  return await saveObjectSetting(speciesBuilderSettingsDefinition, settings);
}
