import type { SpeciesBuilderDefinition } from "../../../../types/species-builder/species-builder";

import {
  captureRuntimeSpeciesSnapshot,
  mergeRuntimeSpeciesSnapshots,
  type RuntimeSpeciesConfigSnapshot,
} from "./config-snapshot";
import { resolveRuntimeCareerTable } from "./career-table";
import { adaptRuntimeSpeciesDefinitions } from "./definition-adapter";

let capturedConfig: RuntimeSpeciesConfigSnapshot | undefined;
let runtimeDefinitions: SpeciesBuilderDefinition[] = [];

export function captureRuntimeSpeciesConfig(): void {
  capturedConfig = captureRuntimeSpeciesSnapshot(game.wfrp4e?.config);
  runtimeDefinitions = [];
}

export async function finalizeRuntimeSpeciesConfig(
  authoredBaseKeys: string[],
  removedTopLevelSpeciesKeys: string[] = [],
): Promise<void> {
  const captured = capturedConfig ?? captureRuntimeSpeciesSnapshot(undefined);
  const current = captureRuntimeSpeciesSnapshot(game.wfrp4e?.config);
  const excludedKeys = new Set(authoredBaseKeys.map((key) => key.trim()).filter(Boolean));
  const merged = mergeRuntimeSpeciesSnapshots(captured, current, excludedKeys);

  for (const key of removedTopLevelSpeciesKeys) {
    delete merged.records.species[key];
  }

  runtimeDefinitions = adaptRuntimeSpeciesDefinitions(merged, {
    resolveCareerTable: resolveRuntimeCareerTable,
  });
}

export async function loadRuntimeSpecies(): Promise<SpeciesBuilderDefinition[]> {
  return structuredClone(runtimeDefinitions);
}
