// This const-object plus union type is our enum substitute while
// `erasableSyntaxOnly` is enabled; TypeScript enums emit runtime JS.
export const WfrpCharacteristicKey = {
  Agility: "ag",
  BallisticSkill: "bs",
  Dexterity: "dex",
  Fellowship: "fel",
  Initiative: "i",
  Intelligence: "int",
  Strength: "s",
  Toughness: "t",
  WeaponSkill: "ws",
  Willpower: "wp",
} as const;

export type WfrpCharacteristicKey =
  (typeof WfrpCharacteristicKey)[keyof typeof WfrpCharacteristicKey];

export const WFRP_CHARACTERISTIC_NAMES: Record<WfrpCharacteristicKey, string> = {
  [WfrpCharacteristicKey.Agility]: "Agility",
  [WfrpCharacteristicKey.BallisticSkill]: "Ballistic Skill",
  [WfrpCharacteristicKey.Dexterity]: "Dexterity",
  [WfrpCharacteristicKey.Fellowship]: "Fellowship",
  [WfrpCharacteristicKey.Initiative]: "Initiative",
  [WfrpCharacteristicKey.Intelligence]: "Intelligence",
  [WfrpCharacteristicKey.Strength]: "Strength",
  [WfrpCharacteristicKey.Toughness]: "Toughness",
  [WfrpCharacteristicKey.WeaponSkill]: "Weapon Skill",
  [WfrpCharacteristicKey.Willpower]: "Willpower",
};

export const WFRP_CHARACTERISTIC_KEY_BY_NAME: Record<string, WfrpCharacteristicKey> = {
  "agility": WfrpCharacteristicKey.Agility,
  "ballistic skill": WfrpCharacteristicKey.BallisticSkill,
  "dexterity": WfrpCharacteristicKey.Dexterity,
  "fellowship": WfrpCharacteristicKey.Fellowship,
  "initiative": WfrpCharacteristicKey.Initiative,
  "intelligence": WfrpCharacteristicKey.Intelligence,
  "strength": WfrpCharacteristicKey.Strength,
  "toughness": WfrpCharacteristicKey.Toughness,
  "weapon skill": WfrpCharacteristicKey.WeaponSkill,
  "willpower": WfrpCharacteristicKey.Willpower,
};

export function isWfrpCharacteristicKey(value: string): value is WfrpCharacteristicKey {
  return value in WFRP_CHARACTERISTIC_NAMES;
}
