<script setup lang="ts">
import type { BuildTraitOption } from "./types";

defineProps<{
  caption: string;
  title: string;
  traits: BuildTraitOption[];
}>();

const emit = defineEmits<{
  toggleTrait: [trait: BuildTraitOption];
}>();
</script>

<template>
  <fieldset v-if="traits.length" class="dui-fieldset">
    <legend class="dui-fieldset-legend">
      <span>{{ title }}</span>
      <span>{{ caption }}</span>
    </legend>
    <div class="dui-card-actions">
      <button
        v-for="trait in traits"
        :key="trait.uuid"
        :aria-pressed="trait.isSelected"
        class="dui-btn dui-btn-sm"
        :class="{ 'dui-btn-active': trait.isSelected }"
        type="button"
        @click="emit('toggleTrait', trait)"
      >
        {{ trait.name }}
      </button>
    </div>
  </fieldset>
</template>
