import { readStringPath } from "../../../../shared/object-readers";
import type { SpeciesItemReference } from "../../../../types/species-builder/species-item";

/** Foundry imports keep their compendium origin even when they receive a new world ID. */
export function findImportedReference<
  T extends {
    id: string;
    uuid: string;
    toObject: () => Record<string, unknown>;
  },
>(reference: SpeciesItemReference, documents: T[]): T | undefined {
  const direct = documents.find((document) =>
    reference.uuid ? document.uuid === reference.uuid : document.id === reference.id,
  );
  if (direct || !reference.uuid.startsWith("Compendium.")) return direct;
  const imported = documents.filter((document) => {
    const source = document.toObject();
    return [
      readStringPath(source, ["_stats", "compendiumSource"]),
      readStringPath(source, ["flags", "core", "sourceId"]),
    ].includes(reference.uuid);
  });
  if (imported.length > 1)
    throw new Error(
      `Multiple imported copies of ${reference.name || reference.uuid}; relink the reference to the intended world document.`,
    );
  return imported[0];
}
