import type {
  SpeciesBuilderLinkedItemName,
  SpeciesBuilderTalentGrant,
} from "../../types/species-builder/species-builder";

import { formatLinkedItemName } from "./item-reference-names";

export function linkedNamesFromRows(
  rows: SpeciesBuilderLinkedItemName[] | undefined,
): string[] | undefined {
  if (!rows || rows.length === 0) {
    return undefined;
  }

  const names = rows.map(formatLinkedItemName).filter((name) => name.length > 0);

  return names.length > 0 ? names : undefined;
}

export function talentNamesFromGrants(
  grants: SpeciesBuilderTalentGrant[] | undefined,
): string[] | undefined {
  if (!grants || grants.length === 0) {
    return undefined;
  }

  const names = grants.flatMap((grant) => {
    const choices = grant.choices.map(formatLinkedItemName).filter((choice) => choice.length > 0);

    return choices.length > 0 ? [choices.join(", ")] : [];
  });

  return names.length > 0 ? names : undefined;
}
