import type { SpeciesItemRecord } from "../../../types/species-builder/species-item";

export function speciesItemKey(item: SpeciesItemRecord): string {
  return item.system.keys[0] || `species${item.id.toLowerCase()}`;
}

export function speciesItemHasParent(item: SpeciesItemRecord): boolean {
  return Boolean(item.system.subspeciesOf.uuid || item.system.subspeciesOf.id);
}
