import {
  isWfrpCharacteristicKey,
  WFRP_CHARACTERISTIC_KEY_BY_NAME,
  type WfrpCharacteristicKey,
} from "../../../types/wfrp4e/characteristics";

export type AttributeReferenceKind = "bonus" | "total";
export type AttributeReferenceSource = "characteristic" | "skill";
export type FormulaKeyword =
  | "ablaze"
  | "advantage"
  | "age"
  | "bleeding"
  | "blinded"
  | "broken"
  | "corruption"
  | "deafened"
  | "entangled"
  | "fate"
  | "fatigued"
  | "fortune"
  | "height"
  | "poisoned"
  | "rank"
  | "resilience"
  | "resolve"
  | "sb"
  | "sbMultiplier"
  | "scale"
  | "sin"
  | "size"
  | "status"
  | "stunned"
  | "tb"
  | "tbMultiplier"
  | "weight"
  | "wpb"
  | "wpbMultiplier"
  | "xp";

export interface CompiledFormula {
  expression: string;
  references: AttributeReference[];
  usedKeywords: Set<FormulaKeyword>;
}

export interface AttributeReference {
  characteristicKey?: WfrpCharacteristicKey;
  characteristicOverride?: WfrpCharacteristicKey;
  kind: AttributeReferenceKind;
  name: string;
  source: AttributeReferenceSource;
  variableName: string;
}

export function compileWoundFormula(formula: string): CompiledFormula {
  const references: AttributeReference[] = [];
  const usedKeywords = new Set<FormulaKeyword>();
  let expression = formula.trim();

  expression = expression.replaceAll(/@([A-Za-z][\dA-Za-z]*)/g, (_match, keyword: string) => {
    const formulaKeyword = toFormulaKeyword(keyword);

    usedKeywords.add(formulaKeyword);

    return formulaKeyword;
  });

  expression = expression.replaceAll(/{([^{}]+)}/g, (_match, attribute: string) =>
    referenceVariableName(references, attribute, "total"),
  );
  expression = expression.replaceAll(/\[([^[\]]+)]/g, (_match, attribute: string) =>
    referenceVariableName(references, attribute, "bonus"),
  );

  return { expression, references, usedKeywords };
}

function toFormulaKeyword(value: string): FormulaKeyword {
  const keywords: FormulaKeyword[] = [
    "ablaze",
    "advantage",
    "age",
    "bleeding",
    "blinded",
    "broken",
    "corruption",
    "deafened",
    "entangled",
    "fate",
    "fatigued",
    "fortune",
    "height",
    "poisoned",
    "rank",
    "resilience",
    "resolve",
    "sb",
    "sbMultiplier",
    "scale",
    "sin",
    "size",
    "status",
    "stunned",
    "tb",
    "tbMultiplier",
    "weight",
    "wpb",
    "wpbMultiplier",
    "xp",
  ];

  if (keywords.includes(value as FormulaKeyword)) {
    return value as FormulaKeyword;
  }

  throw new Error(`Unknown wound formula keyword: @${value}`);
}

function referenceVariableName(
  references: AttributeReference[],
  attribute: string,
  kind: AttributeReferenceKind,
): string {
  const reference = createAttributeReference(attribute, kind, references);
  const existing = references.find((entry) => sameAttributeReference(entry, reference));

  if (existing) {
    return existing.variableName;
  }

  references.push(reference);

  return reference.variableName;
}

function createAttributeReference(
  attribute: string,
  kind: AttributeReferenceKind,
  references: AttributeReference[],
): AttributeReference {
  const [name, override] = splitAttributeReference(attribute);
  const characteristicKey = characteristicKeyFromName(name);
  const variableName = uniqueVariableName(baseVariableName(name, override, kind), references);

  if (characteristicKey && !override) {
    return {
      characteristicKey,
      kind,
      name,
      source: "characteristic",
      variableName,
    };
  }

  const reference: AttributeReference = {
    kind,
    name,
    source: "skill",
    variableName,
  };

  if (override) {
    reference.characteristicOverride = requiredCharacteristicKeyFromName(override);
  }

  return reference;
}

function sameAttributeReference(left: AttributeReference, right: AttributeReference): boolean {
  return (
    left.characteristicKey === right.characteristicKey &&
    left.characteristicOverride === right.characteristicOverride &&
    left.kind === right.kind &&
    left.name === right.name &&
    left.source === right.source
  );
}

function splitAttributeReference(attribute: string): [string, string | undefined] {
  const parts = attribute.split("|").map((part) => part.trim());

  if (parts.length > 2 || !parts[0]) {
    throw new Error(`Invalid wound formula attribute reference: ${attribute}`);
  }

  return [parts[0], parts[1]];
}

function characteristicKeyFromName(name: string): undefined | WfrpCharacteristicKey {
  const normalizedName = name.trim().toLocaleLowerCase();

  if (isWfrpCharacteristicKey(normalizedName)) {
    return normalizedName;
  }

  return WFRP_CHARACTERISTIC_KEY_BY_NAME[normalizedName] ?? characteristicAliases[normalizedName];
}

function requiredCharacteristicKeyFromName(name: string): WfrpCharacteristicKey {
  const key = characteristicKeyFromName(name);

  if (!key) {
    throw new Error(`Unknown wound formula characteristic: ${name}`);
  }

  return key;
}

const characteristicAliases: Record<string, WfrpCharacteristicKey> = {
  ag: "ag",
  bs: "bs",
  dex: "dex",
  fel: "fel",
  i: "i",
  int: "int",
  s: "s",
  t: "t",
  wp: "wp",
  ws: "ws",
};

function baseVariableName(
  name: string,
  override: string | undefined,
  kind: AttributeReferenceKind,
): string {
  const pieces = [name, override].flatMap((piece) =>
    piece ? (piece.match(/\d+|[A-Za-z]+/g) ?? []) : [],
  );
  const [first, ...rest] = pieces;
  const coreName = first
    ? [
        first.toLocaleLowerCase(),
        ...rest.map((piece) => piece.charAt(0).toLocaleUpperCase() + piece.slice(1)),
      ].join("")
    : "attribute";

  return kind === "bonus" ? `${coreName}Bonus` : coreName;
}

function uniqueVariableName(baseName: string, references: AttributeReference[]): string {
  const existingNames = new Set(references.map((reference) => reference.variableName));

  if (!existingNames.has(baseName)) {
    return baseName;
  }

  let index = 2;
  let candidate = `${baseName}${index}`;

  while (existingNames.has(candidate)) {
    index += 1;
    candidate = `${baseName}${index}`;
  }

  return candidate;
}
