import { storeToRefs } from "pinia";
import { computed, ref, type Ref } from "vue";

import type { NpcBuilderBridge } from "../../../../../types/npc-builder";

import { useNpcBuilderStore } from "../../../../../state/npc-builder";
import { toActorDropErrorMessage } from "./errors";

export function useBaseActorSelection(bridge: NpcBuilderBridge, errorMessage: Ref<string>) {
  const store = useNpcBuilderStore();
  const { baseActors, selectedBaseActorUuid } = storeToRefs(store);
  const actorFilter = ref("");

  const filteredActors = computed(() => {
    const query = actorFilter.value.trim().toLocaleLowerCase();

    if (!query) {
      return baseActors.value;
    }

    return baseActors.value.filter((actor) => actor.name.toLocaleLowerCase().includes(query));
  });

  const selectedBaseActorSelectValue = computed({
    get: () => selectedBaseActorUuid.value,
    set: (uuid: string) => {
      store.selectBaseActorUuid(uuid);
    },
  });

  async function handleActorDrop(data: string): Promise<void> {
    errorMessage.value = "";

    try {
      store.selectBaseActor(await bridge.resolveActorDrop(data));
    } catch (error) {
      errorMessage.value = toActorDropErrorMessage(error);
    }
  }

  return {
    actorFilter,
    filteredActors,
    handleActorDrop,
    selectedBaseActorSelectValue,
  };
}
