import { logWarning } from "../../logging";
import { NpcBuilderApplication } from "./NpcBuilderApplication";

const npcBuilderButtonClass = "wfrp4e-customizer-open-npc-builder";

export function registerNpcBuilderActorDirectoryButton(): void {
  Hooks.on("renderActorDirectory", (_application, html) => {
    const root = getRenderedElement(html);

    if (!root) {
      return;
    }

    addBuilderButtons(root);
  });
}

function addBuilderButtons(root: HTMLElement): void {
  const target = findActorDirectoryButtonContainer(root);

  if (!target) {
    logWarning("wfrp4e-customizer-apps | Could not find Actor Directory button container.");
    return;
  }

  addNpcBuilderButton(root, target);
}

function addNpcBuilderButton(root: HTMLElement, target: HTMLElement): void {
  if (root.querySelector(`.${npcBuilderButtonClass}`)) {
    return;
  }

  const button = document.createElement("button");

  button.classList.add(npcBuilderButtonClass, "wfrp4e-customizer-actor-directory-button");
  button.type = "button";
  button.innerHTML = '<i class="fa-solid fa-user-plus" inert></i><span>NPC Builder App</span>';
  button.addEventListener("click", () => {
    void new NpcBuilderApplication().render(true);
  });

  target.append(button);
}

function findActorDirectoryButtonContainer(root: HTMLElement): HTMLElement | null {
  return (
    root.querySelector<HTMLElement>(".directory-header .header-actions") ??
    root.querySelector<HTMLElement>(".directory-header .action-buttons") ??
    root.querySelector<HTMLElement>(".header-actions") ??
    root.querySelector<HTMLElement>(".action-buttons")
  );
}

function getRenderedElement(html: unknown): HTMLElement | null {
  if (html instanceof HTMLElement) {
    return html;
  }

  if (isJQueryLikeElement(html)) {
    return html[0] instanceof HTMLElement ? html[0] : null;
  }

  return null;
}

function isJQueryLikeElement(value: unknown): value is { 0?: unknown; length: number } {
  return typeof value === "object" && value !== null && "length" in value;
}
