import type {
  SpeciesBuilderDefinition,
  SpeciesBuilderSubspeciesDefinition,
} from "../../types/species-builder/species-builder";

import { linkedNamesFromRows, talentNamesFromGrants } from "./linked-grant-records";

export function skillsForDefinition(definition: SpeciesBuilderDefinition): string[] | undefined {
  return linkedNamesFromRows(definition.linkedSkills) ?? definition.skills;
}

export function skillsForSubspecies(
  definition: SpeciesBuilderDefinition,
  subspecies: SpeciesBuilderSubspeciesDefinition,
): string[] | undefined {
  return compileSubspeciesList(
    skillsForDefinition(definition),
    subspecies.skillsAdded,
    subspecies.skillsRemoved,
  );
}

export function previewSkillsForSubspecies(
  definition: SpeciesBuilderDefinition,
  subspecies: SpeciesBuilderSubspeciesDefinition,
): string[] {
  return skillsForSubspecies(definition, subspecies) ?? skillsForDefinition(definition) ?? [];
}

export function talentsForDefinition(definition: SpeciesBuilderDefinition): string[] | undefined {
  return talentNamesFromGrants(definition.linkedTalents) ?? definition.talents;
}

export function talentsForSubspecies(
  definition: SpeciesBuilderDefinition,
  subspecies: SpeciesBuilderSubspeciesDefinition,
): string[] | undefined {
  return compileSubspeciesList(
    talentsForDefinition(definition),
    subspecies.talentsAdded,
    subspecies.talentsRemoved,
  );
}

export function traitsForDefinition(
  definition: SpeciesBuilderDefinition,
  woundFormulaTraitName?: string,
): string[] | undefined {
  return appendUnique(
    linkedNamesFromRows(definition.linkedTraits) ?? definition.traits,
    woundFormulaTraitName,
  );
}

export interface SubspeciesWoundFormulaTraitNames {
  parent?: string;
  subspecies?: string;
}

export function traitsForSubspecies(
  definition: SpeciesBuilderDefinition,
  subspecies: SpeciesBuilderSubspeciesDefinition,
  woundFormulaTraitNames: SubspeciesWoundFormulaTraitNames = {},
): string[] | undefined {
  const activeWoundFormulaTraitName =
    woundFormulaTraitNames.subspecies ?? woundFormulaTraitNames.parent;
  const compiledTraits = compileSubspeciesList(
    traitsForDefinition(definition),
    subspecies.traitsAdded,
    subspecies.traitsRemoved,
  );

  if (compiledTraits) {
    return appendUnique(compiledTraits, activeWoundFormulaTraitName);
  }

  return woundFormulaTraitNames.subspecies
    ? appendUnique(traitsForDefinition(definition), woundFormulaTraitNames.subspecies)
    : undefined;
}

export function previewTraitsForSubspecies(
  definition: SpeciesBuilderDefinition,
  subspecies: SpeciesBuilderSubspeciesDefinition,
  woundFormulaTraitNames: SubspeciesWoundFormulaTraitNames = {},
): string[] {
  return (
    traitsForSubspecies(definition, subspecies, woundFormulaTraitNames) ??
    traitsForDefinition(definition, woundFormulaTraitNames.parent) ??
    []
  );
}

function appendUnique(
  values: string[] | undefined,
  value: string | undefined,
): string[] | undefined {
  if (!value) {
    return values;
  }

  const mergedValues = values ? [...values] : [];

  if (!mergedValues.includes(value)) {
    mergedValues.push(value);
  }

  return mergedValues;
}

function compileSubspeciesList(
  parentValues: string[] | undefined,
  addedValues: string[] | undefined,
  removedValues: string[] | undefined,
): string[] | undefined {
  if (!addedValues && !removedValues) {
    return undefined;
  }

  const removed = new Set(removedValues ?? []);
  const compiled = (parentValues ?? []).filter((value) => !removed.has(value));

  for (const value of addedValues ?? []) {
    if (!compiled.includes(value)) {
      compiled.push(value);
    }
  }

  return compiled;
}
