import type { Component } from "vue";
import { useSpeciesTableStore } from "../../../state/species-table";
import { pinia } from "../../../state/pinia";
import SpeciesTableApp from "../../../view/apps/species-table/SpeciesTableApp.vue";
import { MODULE_ID } from "../../constants";
import { FoundryVueApplication } from "../FoundryVueApplication";
import { speciesTableBridge } from "./bridge";
import { requireSpeciesTableGm } from "./items";

let sequence = 0;

export class SpeciesTableApplication extends FoundryVueApplication {
  readonly storeId: string;

  constructor() {
    const id = `${MODULE_ID}-species-table-${++sequence}`;
    super({ id });
    this.storeId = id;
  }

  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    classes: [MODULE_ID],
    position: { height: 740, width: 720 },
    window: { title: "Species Table Editor", icon: "fa-solid fa-dice", resizable: true },
  };

  protected override getVueComponent(): Component {
    return SpeciesTableApp;
  }
  protected override getVueProps(): Record<string, unknown> {
    return { id: this.storeId, bridge: speciesTableBridge, close: () => this.close() };
  }
  protected override async _preClose(
    options: foundry.applications.types.ApplicationRenderOptions,
  ): Promise<void> {
    const store = useSpeciesTableStore(this.storeId);
    await super._preClose(options);
    store.$dispose();
    delete pinia.state.value[`species-table:${this.storeId}`];
  }
}

export async function openSpeciesTableEditor(): Promise<void> {
  requireSpeciesTableGm();
  await new SpeciesTableApplication().render(true);
}
