<script setup lang="ts">
import type { NpcAdvancementDraftEntry } from "../../../../../types/npc-builder";

import {
  formatSources,
  getAdvancementXp,
  getTalentMaximum,
  getTalentRanks,
  isTalentOverMaximum,
} from "./advancement-display";
import AdvancementRowTailActions from "./AdvancementRowTailActions.vue";
import NpcBuilderSection from "../NpcBuilderSection.vue";

defineProps<{
  maximizableTalentCount: number;
  talents: NpcAdvancementDraftEntry[];
}>();

const emit = defineEmits<{
  adjustCurrent: [advancement: NpcAdvancementDraftEntry, direction: -1 | 1];
  maximizeTalents: [];
  removeCustom: [advancement: NpcAdvancementDraftEntry];
  resetCurrent: [advancement: NpcAdvancementDraftEntry];
  totalChange: [advancement: NpcAdvancementDraftEntry, total: number];
}>();

function handleRanksInput(advancement: NpcAdvancementDraftEntry, event: Event): void {
  const input = event.target as HTMLInputElement | null;

  if (input) {
    emit("totalChange", advancement, Number(input.value));
  }
}
</script>

<template>
  <NpcBuilderSection number="3" title="Talents">
    <div class="dui-card-actions">
      <span>{{ maximizableTalentCount }} below maximum</span>
      <button
        class="dui-btn dui-btn-sm"
        :disabled="maximizableTalentCount === 0"
        title="Raise talents with known maximums to their maximum ranks"
        type="button"
        @click="emit('maximizeTalents')"
      >
        Maximize Talents
      </button>
    </div>
    <ul class="dui-list">
      <li v-for="entry in talents" :key="`${entry.kind}:${entry.name}`" class="dui-list-row">
        <div class="dui-list-col-grow">
          <strong>{{ entry.name }}</strong>
          <span v-if="entry.current !== entry.careerValue" class="dui-badge dui-badge-info">
            Manual edit
          </span>
          <span>
            Ranks {{ getTalentRanks(entry) }} · Maximum {{ getTalentMaximum(entry) }} · XP
            {{ getAdvancementXp(entry) }}
          </span>
          <small>Sources: {{ formatSources(entry) }}</small>
          <span v-if="isTalentOverMaximum(entry)" class="dui-badge dui-badge-warning">
            Over maximum
          </span>
        </div>
        <div class="dui-join">
          <button
            class="dui-join-item dui-btn dui-btn-sm"
            :disabled="getTalentRanks(entry) <= entry.minimumTotal"
            title="Decrease by 1"
            type="button"
            @click="emit('adjustCurrent', entry, -1)"
          >
            -1
          </button>
          <input
            class="dui-join-item dui-input dui-input-sm"
            :aria-label="`Ranks ${entry.name}`"
            :value="getTalentRanks(entry)"
            min="0"
            type="number"
            @input="handleRanksInput(entry, $event)"
          />
          <button
            class="dui-join-item dui-btn dui-btn-sm"
            title="Increase by 1"
            type="button"
            @click="emit('adjustCurrent', entry, 1)"
          >
            +1
          </button>
          <AdvancementRowTailActions
            :entry="entry"
            @remove-custom="emit('removeCustom', entry)"
            @reset-current="emit('resetCurrent', entry)"
          />
        </div>
      </li>
    </ul>
    <p v-if="!talents.length" class="dui-alert">No talents to advance yet.</p>
  </NpcBuilderSection>
</template>
