<script setup lang="ts">
import NpcBuilderSection from "../NpcBuilderSection.vue";

defineProps<{
  canUseDigDownPortraitSearch: boolean;
  excludeFullyTransparentPortraitAssets: boolean;
  excludedPortraitReferenceImages: string[];
  prioritizedPortraitFolders: string[];
  searchCompendiumPortraitAssets: boolean;
  searchFoundryPortraitAssets: boolean;
  searchWebPortraitAssets: boolean;
  statusLabel: string;
}>();

const emit = defineEmits<{
  excludeFullyTransparentPortraitAssetsChange: [value: boolean];
  excludedPortraitReferenceImagesChange: [value: string[]];
  prioritizedPortraitFoldersChange: [value: string[]];
  searchCompendiumPortraitAssetsChange: [value: boolean];
  searchFoundryPortraitAssetsChange: [value: boolean];
}>();

function handleTransparentAssetsChange(event: Event): void {
  const input = event.target as HTMLInputElement | null;

  emit("excludeFullyTransparentPortraitAssetsChange", Boolean(input?.checked));
}

function handleExcludedReferencesChange(event: Event): void {
  const input = event.target as HTMLTextAreaElement | null;

  emit("excludedPortraitReferenceImagesChange", input?.value.split(/\r?\n/u) ?? []);
}

function handlePriorityFoldersChange(event: Event): void {
  const input = event.target as HTMLTextAreaElement | null;

  emit("prioritizedPortraitFoldersChange", input?.value.split(/\r?\n/u) ?? []);
}

function handleFoundrySearchChange(event: Event): void {
  const input = event.target as HTMLInputElement | null;

  emit("searchFoundryPortraitAssetsChange", Boolean(input?.checked));
}

function handleCompendiumSearchChange(event: Event): void {
  const input = event.target as HTMLInputElement | null;

  emit("searchCompendiumPortraitAssetsChange", Boolean(input?.checked));
}
</script>

<template>
  <NpcBuilderSection
    description="Choose which local Foundry sources can suggest portraits."
    number="4"
    title="Portrait Suggestions"
  >
    <label class="app:grid app:gap-1">
      <span class="dui-label app:justify-start app:gap-2 app:font-semibold">
        <i aria-hidden="true" class="fa-solid fa-folder-open" />
        Priority Foundry folders
      </span>
      <textarea
        aria-describedby="portrait-priority-folders-help"
        class="dui-textarea dui-textarea-sm app:min-h-20 app:w-full"
        placeholder="modules/my-art-module/portraits"
        rows="3"
        :value="prioritizedPortraitFolders.join('\n')"
        @input="handlePriorityFoldersChange"
      />
      <small id="portrait-priority-folders-help">
        One Foundry data path per line. These appear first, ahead of compendiums, world documents,
        and Dig Down results.
      </small>
    </label>
    <label class="dui-label">
      <input
        class="dui-toggle dui-toggle-sm"
        :checked="excludeFullyTransparentPortraitAssets"
        type="checkbox"
        @change="handleTransparentAssetsChange"
      />
      <span>Hide fully empty or transparent images</span>
    </label>
    <label class="app:grid app:gap-1">
      <span class="dui-label app:justify-start app:gap-2 app:font-semibold">
        <i aria-hidden="true" class="fa-solid fa-ban" />
        Excluded image references
      </span>
      <textarea
        aria-describedby="portrait-excluded-references-help"
        class="dui-textarea dui-textarea-sm app:min-h-20 app:w-full"
        placeholder="systems/wfrp4e/tokens/unknown.png"
        rows="3"
        :value="excludedPortraitReferenceImages.join('\n')"
        @input="handleExcludedReferencesChange"
      />
      <small id="portrait-excluded-references-help">
        One image path per line. Each listed image and its visual duplicates are hidden. Broken
        images are always hidden.
      </small>
    </label>
    <label class="dui-label">
      <input
        class="dui-toggle dui-toggle-sm"
        :checked="searchFoundryPortraitAssets"
        :disabled="!canUseDigDownPortraitSearch"
        type="checkbox"
        @change="handleFoundrySearchChange"
      />
      <span>Search Dig Down's file cache for portrait suggestions</span>
    </label>
    <p aria-live="polite" class="dui-alert" role="status">{{ statusLabel }}</p>
    <label class="dui-label">
      <input
        class="dui-toggle dui-toggle-sm"
        :checked="searchCompendiumPortraitAssets"
        type="checkbox"
        @change="handleCompendiumSearchChange"
      />
      <span>Search Actor and Item compendiums for portrait suggestions</span>
    </label>
    <label class="dui-label">
      <input
        class="dui-toggle dui-toggle-sm"
        :checked="searchWebPortraitAssets"
        disabled
        type="checkbox"
      />
      <span>Search the web for portrait suggestions (later)</span>
    </label>
  </NpcBuilderSection>
</template>
