import type { SpeciesItemDraft } from "../../../../types/species-builder/species-item";
import { buildSpeciesItemCatalog } from "../../../../functions/species-builder/items/catalog";
import { createDefaultSpeciesBuilderSettings } from "../../../../functions/species-builder/default-species-builder-settings";
import { resolveSpeciesItemTables } from "./table-references";
import { isRecord } from "../../../../shared/object-readers";
import { isSpeciesItem, readSpeciesItem, SPECIES_ITEM_TYPE } from "./adapter";
import { findImportedReference } from "./imported-references";

export function worldSpeciesItems(): FoundryItemDocument[] {
  return (game.items?.contents ?? []).filter(isSpeciesItem);
}

export async function loadSpeciesItemSettings() {
  const documents = worldSpeciesItems();
  const records = documents.map(readSpeciesItem);
  for (const record of records) {
    const reference = record.system.subspeciesOf;
    if (!reference.uuid && !reference.id) continue;
    const parent = findImportedReference(reference, documents);
    if (parent)
      record.system.subspeciesOf = { uuid: parent.uuid, id: parent.id, name: parent.name };
  }
  const tables = new Map(
    await Promise.all(
      records.map(async (record) => [record.uuid, await resolveSpeciesItemTables(record)] as const),
    ),
  );
  return { ...createDefaultSpeciesBuilderSettings(), ...buildSpeciesItemCatalog(records, tables) };
}

export async function createSpeciesItem(draft: SpeciesItemDraft): Promise<FoundryItemDocument> {
  requireSpeciesAuthor();
  const item = await Item.create({
    type: CONFIG.Item.dataModels["species"] ? "species" : SPECIES_ITEM_TYPE,
    name: draft.name,
    img: draft.img,
    system: draft.system,
    ownership: { default: 2 },
  });
  if (!item) throw new Error("Foundry did not create the Species Item.");
  return item;
}

export async function updateSpeciesItem(
  item: FoundryItemDocument,
  draft: SpeciesItemDraft,
): Promise<FoundryItemDocument> {
  requireSpeciesAuthor();
  // Only upstream fields are authored here. Other document data, including old flags, stays intact.
  const source = item.toObject();
  const oldSystem = isRecord(source["system"]) ? source["system"] : {};
  await item.update(
    { name: draft.name, img: draft.img, system: { ...oldSystem, ...draft.system } },
    { recursive: false },
  );
  return item;
}

function requireSpeciesAuthor(): void {
  if (!game.user?.isGM)
    throw new Error("Only a GM can change world Species Items through the Customizer.");
}
