import { storeToRefs } from "pinia";
import { computed, ref, watch } from "vue";

import type {
  NpcBuilderBridge,
  NpcMagicLoreOption,
  PendingMagicLoreResolutionPrompt,
} from "../../../types/npc-builder";

import {
  createMagicGrantSignature,
  createMagicLoreResolutionPrompt,
  getAmbiguousMagicGrants,
} from "../../../functions/npc-builder/magic-lore-resolution";
import { useNpcBuilderStore } from "..";

export function createNpcBuilderSpellsWorkflow(bridge: NpcBuilderBridge) {
  const store = useNpcBuilderStore();
  const { magicGrants, spells, selectedSpells } = storeToRefs(store);
  const errorMessage = ref("");
  const isLoadingLoreOptions = ref(false);
  const isLoadingSpells = ref(false);
  const magicLoreOptions = ref<NpcMagicLoreOption[]>([]);
  const pendingMagicLorePrompt = ref<null | PendingMagicLoreResolutionPrompt>(null);
  let activeSpellLoadId = 0;

  const ambiguousGrants = computed(() => getAmbiguousMagicGrants(magicGrants.value));
  const resolvedGrantCount = computed(
    () => magicGrants.value.length - ambiguousGrants.value.length,
  );

  watch(
    () => createMagicGrantSignature(magicGrants.value),
    () => {
      void loadDetectedSpells();
    },
  );

  function initialize(): void {
    void hydrateMagicLoreOptions();
    void loadDetectedSpells();
  }

  async function loadDetectedSpells(): Promise<void> {
    const loadId = activeSpellLoadId + 1;

    activeSpellLoadId = loadId;

    if (!magicGrants.value.length) {
      store.hydrateDetectedSpells([]);
      return;
    }

    isLoadingSpells.value = true;
    errorMessage.value = "";

    try {
      const detectedSpells = await bridge.listSpellsForMagicGrants(magicGrants.value);

      if (activeSpellLoadId === loadId) {
        store.hydrateDetectedSpells(detectedSpells);
      }
    } catch (error) {
      if (activeSpellLoadId === loadId) {
        errorMessage.value = toSpellWorkflowErrorMessage(error);
      }
    } finally {
      if (activeSpellLoadId === loadId) {
        isLoadingSpells.value = false;
      }
    }
  }

  async function hydrateMagicLoreOptions(): Promise<void> {
    if (magicLoreOptions.value.length || isLoadingLoreOptions.value) {
      return;
    }

    isLoadingLoreOptions.value = true;

    try {
      magicLoreOptions.value = await bridge.listMagicLoreOptions();
    } catch (error) {
      errorMessage.value = toSpellWorkflowErrorMessage(error);
    } finally {
      isLoadingLoreOptions.value = false;
    }
  }

  async function openMagicLorePrompt(): Promise<void> {
    errorMessage.value = "";
    await hydrateMagicLoreOptions();
    pendingMagicLorePrompt.value = createMagicLoreResolutionPrompt(
      magicGrants.value,
      magicLoreOptions.value,
    );
  }

  function confirmMagicLorePrompt(): void {
    const prompt = pendingMagicLorePrompt.value;

    if (!prompt) {
      return;
    }

    for (const row of prompt.rows) {
      store.setMagicGrantLoreResolution(row.resolutionKey, row.selectedLore);
    }

    pendingMagicLorePrompt.value = null;
    void loadDetectedSpells();
  }

  function dismissMagicLorePrompt(): void {
    pendingMagicLorePrompt.value = null;
  }

  async function handleSpellDrop(data: string): Promise<void> {
    errorMessage.value = "";

    try {
      store.addCustomSpell(await bridge.resolveSpellDrop(data));
    } catch (error) {
      errorMessage.value = toSpellWorkflowErrorMessage(error);
    }
  }

  function removeCustomSpell(key: string): void {
    store.removeCustomSpell(key);
  }

  function setSpellSelected(key: string, selected: boolean): void {
    store.setSpellSelected(key, selected);
  }

  return {
    ambiguousGrants,
    confirmMagicLorePrompt,
    dismissMagicLorePrompt,
    errorMessage,
    handleSpellDrop,
    initialize,
    isLoadingLoreOptions,
    isLoadingSpells,
    loadDetectedSpells,
    magicGrants,
    openMagicLorePrompt,
    pendingMagicLorePrompt,
    removeCustomSpell,
    resolvedGrantCount,
    selectedSpells,
    setSpellSelected,
    spells,
  };
}

function toSpellWorkflowErrorMessage(error: unknown): string {
  return error instanceof Error
    ? error.message
    : "The NPC Builder could not finish that spell action.";
}
