import type {
  SpeciesBuilderDefinition,
  SpeciesBuilderRuntimeSpeciesExtension,
  SpeciesBuilderSettings,
  SpeciesBuilderSubspeciesDefinition,
} from "../../types/species-builder/species-builder";
import { assignIfPresent } from "../../shared/assign-if-present";
import { isRecord } from "../../shared/object-readers";
import { normalizeCareerTable } from "./career-table-normalization";
import {
  normalizeLinkedItemNames,
  normalizeLinkedTalentGrants,
} from "./linked-grant-normalization";
import {
  normalizeCareerReplacementRows,
  normalizeTalentReplacementRows,
} from "./replacement-row-normalization";
import {
  normalizeCharacteristics,
  normalizeConfigKey,
  normalizeHeight,
  normalizeNumber,
  normalizeNumberRecord,
  normalizeString,
  normalizeStringArray,
  normalizeStringArrayRecord,
  normalizeStringRecord,
  normalizeWoundFormula,
} from "./settings-normalization/values";

export function normalizeSpeciesBuilderSettings(value: unknown): SpeciesBuilderSettings {
  if (!isRecord(value) || !Array.isArray(value["definitions"])) {
    return {
      autoRegisterSpeciesTable: false,
      correctExistingWfrpSpecies: false,
      definitions: [],
      runtimeSpeciesExtensions: [],
      showGeneratedConfigTab: false,
    };
  }

  return {
    autoRegisterSpeciesTable: value["autoRegisterSpeciesTable"] === true,
    correctExistingWfrpSpecies: value["correctExistingWfrpSpecies"] === true,
    definitions: value["definitions"].flatMap(normalizeSpeciesDefinition),
    runtimeSpeciesExtensions: normalizeRuntimeSpeciesExtensions(value["runtimeSpeciesExtensions"]),
    showGeneratedConfigTab: value["showGeneratedConfigTab"] === true,
  };
}

function normalizeRuntimeSpeciesExtensions(
  value: unknown,
): SpeciesBuilderRuntimeSpeciesExtension[] {
  if (!Array.isArray(value)) {
    return [];
  }

  return value.flatMap((entry) => {
    if (!isRecord(entry)) {
      return [];
    }

    const speciesKey = normalizeString(entry["speciesKey"]);
    const speciesName = normalizeString(entry["speciesName"]);
    const subspecies = normalizeSubspeciesDefinitions(entry["subspecies"]) ?? [];

    return speciesKey && speciesName && subspecies.length > 0
      ? [
          {
            speciesKey,
            speciesName,
            subspecies,
          },
        ]
      : [];
  });
}

function normalizeSpeciesDefinition(value: unknown): SpeciesBuilderDefinition[] {
  return normalizeNamedDefinition(value, (key, name, record) => ({
    includeInExtraSpecies: record["includeInExtraSpecies"] === true,
    key,
    name,
  })).map((definition) => {
    assignSpeciesGrantFields(definition, value);
    assignSpeciesOnlyFields(definition, value);

    return definition;
  });
}

function normalizeSubspeciesDefinitions(
  value: unknown,
): SpeciesBuilderSubspeciesDefinition[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }

  const subspecies = value.flatMap(normalizeSubspeciesDefinition);

  return subspecies.length > 0 ? subspecies : undefined;
}

function normalizeSubspeciesDefinition(value: unknown): SpeciesBuilderSubspeciesDefinition[] {
  return normalizeNamedDefinition(value, (key, name, record) => {
    const definition: SpeciesBuilderSubspeciesDefinition = { key, name };

    assignIfPresent(definition, "skillsAdded", normalizeStringArray(record["skillsAdded"]));
    assignIfPresent(definition, "skillsRemoved", normalizeStringArray(record["skillsRemoved"]));
    assignIfPresent(definition, "talentsAdded", normalizeStringArray(record["talentsAdded"]));
    assignIfPresent(definition, "talentsRemoved", normalizeStringArray(record["talentsRemoved"]));
    assignIfPresent(definition, "traitsAdded", normalizeStringArray(record["traitsAdded"]));
    assignIfPresent(definition, "traitsRemoved", normalizeStringArray(record["traitsRemoved"]));

    return definition;
  });
}

function normalizeNamedDefinition<
  TDefinition extends SpeciesBuilderDefinition | SpeciesBuilderSubspeciesDefinition,
>(
  value: unknown,
  createDefinition: (key: string, name: string, value: Record<string, unknown>) => TDefinition,
): TDefinition[] {
  if (!isRecord(value)) {
    return [];
  }

  const key = normalizeConfigKey(value["key"]);
  const name = normalizeString(value["name"]);

  if (!key || !name) {
    return [];
  }

  const definition = createDefinition(key, name, value);

  assignIfPresent(
    definition,
    "characteristics",
    normalizeCharacteristics(value["characteristics"]),
  );
  assignIfPresent(definition, "randomTalents", normalizeNumberRecord(value["randomTalents"]));
  assignIfPresent(
    definition,
    "talentReplacementRows",
    normalizeTalentReplacementRows(value["talentReplacementRows"]),
  );
  assignIfPresent(
    definition,
    "talentReplacements",
    normalizeStringRecord(value["talentReplacements"]),
  );
  assignIfPresent(definition, "movement", normalizeNumber(value["movement"]));
  assignIfPresent(definition, "fate", normalizeNumber(value["fate"]));
  assignIfPresent(definition, "resilience", normalizeNumber(value["resilience"]));
  assignIfPresent(definition, "extra", normalizeNumber(value["extra"]));
  assignIfPresent(definition, "woundFormula", normalizeWoundFormula(value["woundFormula"]));
  assignIfPresent(definition, "careerTable", normalizeCareerTable(value["careerTable"]));

  return [definition];
}

function assignSpeciesGrantFields(definition: SpeciesBuilderDefinition, value: unknown): void {
  if (!isRecord(value)) {
    return;
  }

  assignIfPresent(definition, "skills", normalizeStringArray(value["skills"]));
  assignIfPresent(
    definition,
    "linkedSkills",
    normalizeLinkedItemNames(value["linkedSkills"], "skill"),
  );
  assignIfPresent(definition, "talents", normalizeStringArray(value["talents"]));
  assignIfPresent(definition, "linkedTalents", normalizeLinkedTalentGrants(value["linkedTalents"]));
  assignIfPresent(definition, "traits", normalizeStringArray(value["traits"]));
  assignIfPresent(
    definition,
    "linkedTraits",
    normalizeLinkedItemNames(value["linkedTraits"], "trait"),
  );
}

function assignSpeciesOnlyFields(definition: SpeciesBuilderDefinition, value: unknown): void {
  if (!isRecord(value)) {
    return;
  }

  assignIfPresent(definition, "age", normalizeString(value["age"]));
  assignIfPresent(definition, "height", normalizeHeight(value["height"]));
  assignIfPresent(
    definition,
    "careerReplacements",
    normalizeStringArrayRecord(value["careerReplacements"]),
  );
  assignIfPresent(
    definition,
    "careerReplacementRows",
    normalizeCareerReplacementRows(value["careerReplacementRows"]),
  );
  assignIfPresent(definition, "subspecies", normalizeSubspeciesDefinitions(value["subspecies"]));
}
