export function createFallbackItemSource(name: string, type: string): FoundryItemSource {
  return {
    img: "systems/wfrp4e/icons/blank.png",
    name,
    system: {},
    type,
  };
}

export function createItemSourceFromMatch(
  sourceItem: FoundryItemDocument | null,
  fallbackName: string,
  fallbackType: string,
): FoundryItemSource {
  const itemData = sourceItem
    ? sourceItem.toObject()
    : createFallbackItemSource(fallbackName, fallbackType);

  // Item sources copied from world documents also carry their original `_id`.
  // Removing it lets Foundry assign a fresh embedded Item id on the new Actor.
  delete itemData._id;

  return itemData;
}

export function findActorItemByNameAndType(
  actor: FoundryActorDocument,
  name: string,
  type: string,
): FoundryItemDocument | null {
  return findActorItemsByNameAndType(actor, name, type)[0] ?? null;
}

export function findActorItemsByNameAndType(
  actor: FoundryActorDocument,
  name: string,
  type: string,
): FoundryItemDocument[] {
  return (
    actor.items?.contents.filter((item) => {
      return item.type === type && namesMatch(item.name, name);
    }) ?? []
  );
}

export function findActorItemByUuidOrName(
  actor: FoundryActorDocument,
  uuid: string,
  name: string,
): FoundryItemDocument | null {
  return (
    actor.items?.contents.find((item) => {
      if (uuid && item.uuid === uuid) {
        return true;
      }

      return namesMatch(item.name, name);
    }) ?? null
  );
}

export function findWorldItemByNameAndType(
  name: string,
  types: string[],
): FoundryItemDocument | null {
  return (
    game.items?.contents.find((item) => {
      return types.includes(item.type) && namesMatch(item.name, name);
    }) ?? null
  );
}

function namesMatch(left: string, right: string): boolean {
  return left.trim().toLocaleLowerCase() === right.trim().toLocaleLowerCase();
}
