<script setup lang="ts">
import { useId } from "vue";

import type { ManualDocumentType } from "../../../types/foundry/document-drop";

defineProps<{
  documentType: ManualDocumentType;
  documentValue: string;
  isPickingDocument: boolean;
}>();

const emit = defineEmits<{
  close: [];
  startPick: [];
  submit: [];
  updateDocumentType: [value: ManualDocumentType];
  updateDocumentValue: [value: string];
}>();

const documentTypeId = useId();
const documentValueId = useId();

function emitDocumentType(event: Event): void {
  const value = event.target instanceof HTMLSelectElement ? event.target.value : "auto";

  if (
    value === "Actor" ||
    value === "auto" ||
    value === "Item" ||
    value === "JournalEntry" ||
    value === "JournalEntryPage"
  ) {
    emit("updateDocumentType", value);
  }
}

function emitDocumentValue(event: Event): void {
  emit("updateDocumentValue", event.target instanceof HTMLInputElement ? event.target.value : "");
}
</script>

<template>
  <form class="dui-card dui-card-border dui-card-sm" @click.stop @submit.prevent="emit('submit')">
    <fieldset class="dui-card-body dui-fieldset">
      <legend class="dui-fieldset-legend">Manual document entry</legend>
      <label class="dui-label" :for="documentTypeId">Document type</label>
      <select
        :id="documentTypeId"
        class="dui-select"
        :value="documentType"
        @change="emitDocumentType"
      >
        <option value="auto">Auto</option>
        <option value="Item">Item</option>
        <option value="Actor">Actor</option>
        <option value="JournalEntry">Journal Entry</option>
        <option value="JournalEntryPage">Journal Page</option>
      </select>

      <label class="dui-label" :for="documentValueId">UUID or drop JSON</label>
      <input
        :id="documentValueId"
        class="dui-input"
        :value="documentValue"
        placeholder="Compendium.package.pack.id"
        type="text"
        @input="emitDocumentValue"
      />

      <div class="dui-card-actions">
        <button class="dui-btn dui-btn-primary" type="submit">Use</button>
        <button class="dui-btn" type="button" @click="emit('startPick')">
          {{ isPickingDocument ? "Waiting..." : "Pick Next Click" }}
        </button>
        <button class="dui-btn dui-btn-ghost" type="button" @click="emit('close')">Cancel</button>
      </div>
    </fieldset>
  </form>
</template>
