import type {
  SpeciesBuilderDefinition,
  SpeciesBuilderSettings,
  SpeciesBuilderSubspeciesDefinition,
  WfrpSpeciesConfig,
  WfrpSubspeciesConfigEntry,
} from "../../types/species-builder/species-builder";

import { assignIfPresent } from "../../shared/assign-if-present";
import {
  careerReplacementRecordFromRows,
  talentReplacementRecordFromRows,
} from "./replacement-row-records";
import {
  skillsForDefinition,
  skillsForSubspecies,
  talentsForDefinition,
  talentsForSubspecies,
  traitsForDefinition,
  traitsForSubspecies,
} from "./subspecies-list-fields";
import {
  getSpeciesWoundFormulaTraitName,
  getSubspeciesWoundFormulaTraitName,
} from "./wound-formula-traits";
import { buildSpeciesDefinitionPlans } from "./definition-plans";

export function buildWfrpSpeciesConfig(
  settings: SpeciesBuilderSettings,
  runtimeParents: SpeciesBuilderDefinition[] = [],
): WfrpSpeciesConfig {
  const config = createEmptyWfrpSpeciesConfig();

  for (const plan of buildSpeciesDefinitionPlans(settings, runtimeParents)) {
    if (plan.emitBaseDefinition) {
      addSpeciesDefinition(config, plan.definition);
    }
    addSubspeciesDefinitions(config, plan.definition, plan.subspecies);
  }

  return config;
}

function createEmptyWfrpSpeciesConfig(): WfrpSpeciesConfig {
  return {
    extraSpecies: [],
    species: {},
    speciesAge: {},
    speciesCareerReplacements: {},
    speciesCharacteristics: {},
    speciesExtra: {},
    speciesFate: {},
    speciesHeight: {},
    speciesMovement: {},
    speciesRandomTalents: {},
    speciesRes: {},
    speciesSkills: {},
    speciesTalentReplacement: {},
    speciesTalents: {},
    speciesTraits: {},
    subspecies: {},
  };
}

function addSpeciesDefinition(
  config: WfrpSpeciesConfig,
  definition: SpeciesBuilderDefinition,
): void {
  config.species[definition.key] = definition.name;

  assignIfPresent(config.speciesCharacteristics, definition.key, definition.characteristics);
  config.speciesSkills[definition.key] = skillsForDefinition(definition) ?? [];
  config.speciesTalents[definition.key] = talentsForDefinition(definition) ?? [];
  assignIfPresent(config.speciesRandomTalents, definition.key, definition.randomTalents);
  assignIfPresent(
    config.speciesTalentReplacement,
    definition.key,
    talentReplacementRecord(definition),
  );
  assignIfPresent(
    config.speciesTraits,
    definition.key,
    traitsForDefinition(
      definition,
      definition.woundFormula ? getSpeciesWoundFormulaTraitName(definition) : undefined,
    ),
  );
  assignIfPresent(config.speciesMovement, definition.key, definition.movement);
  assignIfPresent(config.speciesFate, definition.key, definition.fate);
  assignIfPresent(config.speciesRes, definition.key, definition.resilience);
  assignIfPresent(config.speciesExtra, definition.key, definition.extra);
  assignIfPresent(config.speciesAge, definition.key, definition.age);
  assignIfPresent(config.speciesHeight, definition.key, definition.height);
  assignIfPresent(
    config.speciesCareerReplacements,
    definition.key,
    careerReplacementRecord(definition),
  );

  if (definition.includeInExtraSpecies) {
    config.extraSpecies.push(definition.key);
  }
}

function addSubspeciesDefinitions(
  config: WfrpSpeciesConfig,
  definition: SpeciesBuilderDefinition,
  subspeciesDefinitions: SpeciesBuilderSubspeciesDefinition[],
): void {
  for (const subspecies of subspeciesDefinitions) {
    const speciesSubspecies = config.subspecies[definition.key] ?? {};
    const subspeciesWoundFormulaTraitName = subspecies.woundFormula
      ? getSubspeciesWoundFormulaTraitName(definition, subspecies)
      : undefined;
    const careerTableKey = subspecies.careerTable
      ? getSubspeciesCareerTableColumn(definition, subspecies)
      : undefined;

    speciesSubspecies[subspecies.key] = buildSubspeciesConfigEntry(
      definition,
      subspecies,
      subspeciesWoundFormulaTraitName,
      careerTableKey,
    );
    config.subspecies[definition.key] = speciesSubspecies;
  }
}

function buildSubspeciesConfigEntry(
  definition: SpeciesBuilderDefinition,
  subspecies: SpeciesBuilderSubspeciesDefinition,
  woundFormulaTraitName: string | undefined,
  careerTableKey: string | undefined,
): WfrpSubspeciesConfigEntry {
  const entry: WfrpSubspeciesConfigEntry = {
    name: subspecies.name,
  };

  assignIfPresent(
    entry,
    "characteristics",
    subspecies.characteristics
      ? { ...definition.characteristics, ...subspecies.characteristics }
      : undefined,
  );
  assignIfPresent(entry, "skills", skillsForSubspecies(definition, subspecies));
  assignIfPresent(entry, "talents", talentsForSubspecies(definition, subspecies));
  assignIfPresent(
    entry,
    "speciesTraits",
    traitsForSubspecies(definition, subspecies, {
      parent: definition.woundFormula ? getSpeciesWoundFormulaTraitName(definition) : undefined,
      subspecies: woundFormulaTraitName,
    }),
  );
  assignIfPresent(entry, "randomTalents", subspecies.randomTalents);
  assignIfPresent(entry, "talentReplacement", talentReplacementRecord(subspecies));
  assignIfPresent(entry, "movement", subspecies.movement);
  assignIfPresent(entry, "fate", subspecies.fate);
  assignIfPresent(entry, "resilience", subspecies.resilience);
  assignIfPresent(entry, "extra", subspecies.extra);
  assignIfPresent(entry, "careerTable", careerTableKey);

  return entry;
}

export function getSpeciesCareerTableColumn(definition: Pick<SpeciesBuilderDefinition, "key">) {
  return definition.key;
}

export function getSubspeciesCareerTableColumn(
  definition: Pick<SpeciesBuilderDefinition, "key">,
  subspecies: Pick<SpeciesBuilderSubspeciesDefinition, "key">,
) {
  return `${definition.key}-${subspecies.key}`;
}

function talentReplacementRecord(
  definition: SpeciesBuilderDefinition | SpeciesBuilderSubspeciesDefinition,
): Record<string, string> | undefined {
  const rowRecord = talentReplacementRecordFromRows(definition.talentReplacementRows);

  return rowRecord ?? definition.talentReplacements;
}

function careerReplacementRecord(
  definition: SpeciesBuilderDefinition,
): Record<string, string[]> | undefined {
  const rowRecord = careerReplacementRecordFromRows(definition.careerReplacementRows);

  return rowRecord ?? definition.careerReplacements;
}
