<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from "vue";
import { useSpeciesItemStore } from "../../../state/species-item";
const props = defineProps<{ uuid: string; editable: boolean }>();
const store = useSpeciesItemStore(props.uuid);
const notes = ref<HTMLElement>();
const gmNotes = ref<HTMLElement>();
const cleanups: Array<() => void> = [];
onMounted(() => {
  for (const [field, host] of [
    ["description", notes.value],
    ["gmdescription", gmNotes.value],
  ] as const) {
    if (!host) continue;
    cleanups.push(
      store.mountNotes(host, field, store.draft.system[field].value, props.editable, (value) => {
        store.draft.system[field].value = value;
      }),
    );
  }
});
onBeforeUnmount(() => cleanups.forEach((cleanup) => cleanup()));
</script>

<template>
  <fieldset v-if="store.isGM" class="dui-fieldset">
    <legend class="dui-fieldset-legend">GM Notes</legend>
    <button
      v-if="editable"
      type="button"
      class="dui-btn dui-btn-xs app:justify-self-start"
      @click="store.editNotes('gmdescription')"
    >
      Edit GM Notes
    </button>
    <div ref="gmNotes" class="app:min-h-32" aria-label="GM Notes" />
  </fieldset>
  <fieldset class="dui-fieldset">
    <legend class="dui-fieldset-legend">Notes</legend>
    <button
      v-if="editable"
      type="button"
      class="dui-btn dui-btn-xs app:justify-self-start"
      @click="store.editNotes('description')"
    >
      Edit Notes
    </button>
    <div ref="notes" class="app:min-h-32" aria-label="Notes" />
  </fieldset>
</template>
