import { SPECIES_ITEM_TYPE } from "./adapter";
import { worldSpeciesItems } from "./repository";

export function hasNativeSpeciesSupport(): boolean {
  return typeof CONFIG.Item.dataModels["species"] === "function";
}

/** A type-only update preserves document IDs, references, effects, and original authoring data. */
export async function migrateSpeciesItemsToNative(): Promise<number> {
  if (!hasNativeSpeciesSupport() || !game.user?.isGM) return 0;
  if (game.users?.activeGM && game.users.activeGM.id !== game.user.id) return 0;
  let converted = 0;
  for (const item of worldSpeciesItems().filter((item) => item.type === SPECIES_ITEM_TYPE)) {
    await item.update({ type: "species" });
    converted += 1;
  }
  return converted;
}
