import {
  NpcActorSizeKey,
  type NpcActorCombatProfile,
  type NpcMountTraitSummary,
} from "../../../../../types/npc-builder";

import {
  readBooleanFromPaths,
  readNumberFromPaths,
  readOptionalNumberFromPaths,
  readStringPath,
} from "../../../../../shared/object-readers";
import { assertFoundryActor } from "../../../../foundry/document-guards";

const ACTOR_SIZE_KEYS = new Set<string>(Object.values(NpcActorSizeKey));

export async function loadActorCombatProfile(actorUuid: string): Promise<NpcActorCombatProfile> {
  const actor = assertFoundryActor(await fromUuid(actorUuid));

  return readActorCombatProfile(actor);
}

export function readActorCombatProfile(actor: FoundryActorDocument): NpcActorCombatProfile {
  return {
    characteristics: {
      initiative: readCharacteristicValue(actor, "i"),
      strength: readCharacteristicValue(actor, "s"),
      strengthBonus: readCharacteristicBonus(actor, "s"),
      toughness: readCharacteristicValue(actor, "t"),
    },
    img: actor.img ?? "",
    movement: readNumberFromPaths(actor.system, [["details", "move", "value"]]),
    name: actor.name,
    size: readActorSize(actor),
    traits: readMountTraits(actor),
    uuid: actor.uuid,
    wounds: readNumberFromPaths(actor.system, [
      ["status", "wounds", "max"],
      ["status", "wounds", "value"],
    ]),
  };
}

function readMountTraits(actor: FoundryActorDocument): NpcMountTraitSummary[] {
  return (
    actor.items?.contents
      .filter((item) => item.type === "trait" && !isDisabledTrait(item))
      .map((item) => readMountTrait(actor, item))
      .sort((left, right) => left.name.localeCompare(right.name)) ?? []
  );
}

function readMountTrait(
  actor: FoundryActorDocument,
  item: FoundryItemDocument,
): NpcMountTraitSummary {
  const damage = readBooleanFromPaths(item.system, [["rollable", "damage"]]);
  const specification = readStringPath(item.system, ["specification", "value"]);

  return {
    damage,
    fixedDamage: damage ? readFixedTraitDamage(actor, item, specification) : null,
    name: item.name,
    specification,
    uuid: item.uuid,
  };
}

function readFixedTraitDamage(
  actor: FoundryActorDocument,
  item: FoundryItemDocument,
  specification: string,
): number {
  const preparedDamage = readOptionalNumberFromPaths(item, [["Damage"]]);

  if (preparedDamage !== null) {
    return preparedDamage;
  }

  const baseDamage = Number(specification);
  const bonusCharacteristic = readStringPath(item.system, ["rollable", "bonusCharacteristic"]);

  return (
    (Number.isFinite(baseDamage) ? baseDamage : 0) +
    (bonusCharacteristic ? readCharacteristicBonus(actor, bonusCharacteristic) : 0)
  );
}

function readCharacteristicValue(actor: FoundryActorDocument, key: string): number {
  return readNumberFromPaths(actor.system, [
    ["characteristics", key, "value"],
    ["characteristics", key, "initial"],
  ]);
}

function readCharacteristicBonus(actor: FoundryActorDocument, key: string): number {
  const preparedBonus = readOptionalNumberFromPaths(actor.system, [
    ["characteristics", key, "bonus"],
  ]);

  return preparedBonus ?? Math.floor(readCharacteristicValue(actor, key) / 10);
}

function readActorSize(actor: FoundryActorDocument): NpcActorSizeKey {
  const size = readStringPath(actor.system, ["details", "size", "value"]);

  return ACTOR_SIZE_KEYS.has(size) ? (size as NpcActorSizeKey) : NpcActorSizeKey.Average;
}

function isDisabledTrait(item: FoundryItemDocument): boolean {
  return readBooleanFromPaths(item.system, [["disabled"], ["disabled", "value"]]);
}
